window.GHIDURI={"G1": {"titlu": "Cum fac o captură de ecran", "parti": [{"t": "Pe calculator cu Windows (cel mai simplu)", "pasi": ["Apasă <b>în același timp</b> tastele <code>Windows</code> + <code>Shift</code> + <code>S</code>. Tasta <code>Windows</code> e cea cu sigla (patru pătrățele), în stânga jos. <code>Shift</code> e tasta cu săgeata în sus, de deasupra lui <code>Ctrl</code>.", "Ecranul se întunecă puțin, iar sus apare o bară mică. Lasă alegerea pe <b>Dreptunghi</b> (prima pictogramă).", "Ține apăsat butonul stâng al mouse-ului și <b>trage un dreptunghi</b> peste ce vrei să prinzi. Când dai drumul la buton, captura e gata.", "Captura e acum „în memorie” (clipboard), ca un text copiat. Mergi în Word sau în e-mail, dai click unde o vrei și apeși <code>Ctrl</code> + <code>V</code>. Apare imaginea.", "Vrei s-o salvezi ca fișier? În dreapta jos apare un mesaj mic, „Captură copiată în clipboard”. Dă click pe el, apoi pe pictograma <b>dischetă</b> (Salvare), alege folderul și scrie numele."]}, {"t": "Varianta cu o singură tastă", "pasi": ["Apasă tasta <code>PrtSc</code> (sau <code>Print Screen</code>), de obicei sus, în dreapta tastaturii. Pe Windows 11 se deschide aceeași bară de captură. Pe Windows 10 se copiază tot ecranul, iar tu lipești cu <code>Ctrl</code> + <code>V</code>."]}, {"t": "Pe telefon", "pasi": ["<b>Android</b> (Samsung, Xiaomi etc.): apasă <b>în același timp</b> butonul de pornire și butonul de volum în jos, o secundă. Ecranul clipește: captura e în <b>Galerie</b>.", "<b>iPhone fără buton rotund</b>: butonul din lateral + volum sus, în același timp. <b>iPhone cu buton rotund</b>: butonul rotund + butonul de pornire."]}, {"t": "Dacă nu merge", "pasi": ["Nu se întâmplă nimic la <code>Windows</code> + <code>Shift</code> + <code>S</code>? Apasă tastele pe rând și ține-le apăsate până la ultima. Sau caută în meniul Start „<b>Instrument de decupare</b>” (Snipping Tool) și apasă <b>Nou</b>.", "Pe laptop, <code>PrtSc</code> poate cere și tasta <code>Fn</code> (apeși <code>Fn</code> + <code>PrtSc</code>)."]}]}, "G2": {"titlu": "Cum lipesc o captură într-un document Word", "parti": [{"t": "Pașii", "pasi": ["Fă captura (ghidul <b>G1</b>). Nu mai trebuie salvată: e deja în memorie.", "Deschide documentul Word și dă click <b>exact în locul</b> unde vrei imaginea, de exemplu pe un rând gol de la final.", "Apasă <code>Ctrl</code> + <code>V</code>. Imaginea apare.", "E prea mare? Dă click pe ea: apar cerculețe în colțuri. Prinde un <b>colț</b> și trage spre interior. Din colț, imaginea își păstrează proporțiile.", "Salvează documentul cu <code>Ctrl</code> + <code>S</code>."]}, {"t": "Dacă nu merge", "pasi": ["Nu se lipește nimic? Captura nu s-a făcut. Mai fă o dată pasul din ghidul G1 și lipește imediat după."]}]}, "G3": {"titlu": "Cum salvez un fișier cu numele corect și unde îl găsesc", "parti": [{"t": "Salvarea", "pasi": ["În Word, Excel sau PowerPoint apasă <b>Fișier</b> (File) → <b>Salvare ca</b> (Save As) → <b>Răsfoire</b> (Browse). Pe unele versiuni: <b>Acest PC</b> (This PC).", "În stânga ferestrei alege <b>Documente</b> (Documents). E un loc ușor de ținut minte.", "În căsuța <b>Nume fișier</b> (File name) șterge ce scrie și pune numele cerut, de exemplu <code>E14_Word_Popescu_Maria</code>. <b>Fără diacritice și fără spații</b>: în loc de spațiu pui liniuță jos <code>_</code> (<code>Shift</code> + tasta minus).", "Apasă <b>Salvare</b> (Save). De acum, la fiecare modificare apeși doar <code>Ctrl</code> + <code>S</code>."]}, {"t": "Unde îl găsesc mai târziu", "pasi": ["Apasă <code>Windows</code> + <code>E</code>: se deschide <b>Explorer</b> (dosarul cu fișiere). În stânga dai click pe <b>Documente</b>.", "Fișierele descărcate de pe site ajung, de obicei, în <b>Descărcări</b> (Downloads), tot din stânga.", "Nu-l găsești? Sus în dreapta, în căsuța de căutare din Explorer, scrie o parte din nume (de exemplu <code>E14</code>)."]}, {"t": "De ce fără diacritice în nume", "pasi": ["Unele programe de e-mail și unele servere „strică” literele ă, î, ș, ț din numele fișierelor. Textul <b>din interiorul</b> documentului îl scrii, firește, cu diacritice."]}]}, "G4": {"titlu": "Cum salvez un document ca PDF", "parti": [{"t": "Din Word sau PowerPoint", "pasi": ["Cu documentul deschis: <b>Fișier</b> (File) → <b>Salvare ca</b> (Save As) → <b>Răsfoire</b> (Browse).", "Jos, la <b>Tip fișier</b> (Save as type), deschide lista și alege <b>PDF (*.pdf)</b>.", "Verifică numele și apasă <b>Salvare</b> (Save). Documentul original rămâne neschimbat: acum ai două fișiere, <code>.docx</code> (sau <code>.pptx</code>) și <code>.pdf</code>."]}, {"t": "Varianta 2", "pasi": ["<b>Fișier</b> → <b>Export</b> → <b>Creare document PDF/XPS</b> → <b>Publicare</b>."]}, {"t": "Verifică", "pasi": ["Deschide PDF-ul (dublu click). Trebuie să arate exact ca documentul. Dacă vezi pagini goale sau tăiate, întoarce-te în Word și repară, apoi salvează din nou ca PDF."]}]}, "G5": {"titlu": "Cum atașez un fișier la un e-mail", "parti": [{"t": "Outlook (aplicația sau outlook.com)", "pasi": ["Apasă <b>E-mail nou</b> (New mail).", "Apasă pe <b>agrafă</b>, <b>Atașare fișier</b> (Attach File) → <b>Răsfoiți acest computer</b> (Browse this computer).", "Alege fișierul (de obicei din <b>Documente</b>) → <b>Deschidere</b>. Fișierul apare ca o casetă mică sub subiect."]}, {"t": "Gmail sau Yahoo", "pasi": ["<b>Scrieți</b> (Compose), apoi, jos, pictograma <b>agrafă</b>. Alegi fișierul → <b>Deschidere</b>."]}, {"t": "De pe telefon (aplicația Gmail)", "pasi": ["Scrii mesajul nou, apoi sus apeși <b>agrafa</b> → <b>Atașează fișierul</b> → alegi fișierul din <b>Descărcări</b> sau <b>Fișiere</b>."]}, {"t": "Dacă nu merge", "pasi": ["Fișierul e prea mare (peste 20–25 MB)? Salvează-l pe OneDrive și trimite un link (ghidul <b>G9</b>).", "Nu vezi fișierul în listă? Uită-te în <b>Descărcări</b> sau caută-l după nume (ghidul <b>G3</b>)."]}]}, "G6": {"titlu": "Cum trimit tema pe e-mail", "parti": [{"t": "Pașii", "pasi": ["<b>La</b> (To): <code>bogdan@pandapc.ro</code>", "<b>Subiect</b>: exact textul din pagina exercițiului. Apasă butonul <b>Copiază</b> de lângă el, apoi în e-mail, la Subiect, <code>Ctrl</code> + <code>V</code>. Înlocuiește „Nume Prenume” cu numele tău.", "<b>Mesaj</b>: 1–2 rânduri, de exemplu: „Bună ziua, vă trimit exercițiul E04. Mulțumesc!” și numele tău.", "<b>Atașează</b> fișierul (ghidul <b>G5</b>) și verifică dacă apare caseta cu numele lui.", "Apasă <b>Trimitere</b> (Send). Verifică în <b>Elemente trimise</b> (Sent) că e-mailul a plecat."]}, {"t": "Bine de știut", "pasi": ["Nu există termen-limită: trimiți când ai terminat. Rezolvarea apare pe site a doua zi după ora exercițiului, de la 17:00."]}]}, "G7": {"titlu": "Cum folosesc „Verificare accesibilitate” (Word, PowerPoint)", "parti": [{"t": "Pașii", "pasi": ["Fila <b>Revizuire</b> (Review) → <b>Verificare accesibilitate</b> (Check Accessibility). Pe versiunile noi butonul poate fi sub săgeata de lângă el.", "În dreapta se deschide un panou cu <b>Erori</b> (Errors) și <b>Avertismente</b> (Warnings).", "Dă click pe o problemă: programul îți arată unde e și, dedesubt, <b>Remedieri recomandate</b> (Recommended Actions). Alegi una și se rezolvă (de exemplu adaugi text alternativ).", "Când lista e goală, documentul trece verificarea de bază."]}, {"t": "Ce înseamnă cele mai dese mesaje", "pasi": ["<b>Text alternativ lipsă</b>: o imagine nu are descriere pentru cititorul de ecran.", "<b>Titlu lipsă</b> (în PowerPoint): diapozitivul nu are casetă de titlu.", "<b>Contrast insuficient</b>: textul se citește greu pe fundal."]}]}, "G8": {"titlu": "Scurtăturile de tastatură de bază", "parti": [{"t": "Pentru orice program", "pasi": ["<code>Ctrl</code> + <code>C</code> copiază · <code>Ctrl</code> + <code>V</code> lipește · <code>Ctrl</code> + <code>X</code> taie · <code>Ctrl</code> + <code>Z</code> anulează ultima acțiune (salvatorul tuturor).", "<code>Ctrl</code> + <code>S</code> salvează · <code>Ctrl</code> + <code>P</code> tipărește · <code>Ctrl</code> + <code>F</code> caută un cuvânt.", "<code>Alt</code> + <code>Tab</code> trece de la o fereastră la alta."]}, {"t": "Fără mouse", "pasi": ["<code>Tab</code> te duce la următorul buton sau câmp, <code>Shift</code> + <code>Tab</code> la cel de dinainte. <code>Enter</code> apasă butonul ales, iar <code>Spațiu</code> bifează o căsuță.", "Săgețile te mută într-o listă sau într-un meniu."]}, {"t": "Accesibilitate", "pasi": ["<code>Windows</code> + <code>+</code> pornește <b>Lupa</b> (Magnifier), iar <code>Windows</code> + <code>Esc</code> o oprește.", "<code>Ctrl</code> + <code>Windows</code> + <code>Enter</code> pornește și oprește <b>Naratorul</b> (cititorul de ecran din Windows).", "În browser, <code>Ctrl</code> + <code>+</code> mărește pagina, <code>Ctrl</code> + <code>-</code> o micșorează, <code>Ctrl</code> + <code>0</code> o readuce la normal."]}]}, "G9": {"titlu": "Cum partajez un fișier din OneDrive", "parti": [{"t": "Pașii (OneDrive pe web sau în Explorer)", "pasi": ["Click dreapta pe fișier → <b>Partajare</b> (Share). Pe web: selectezi fișierul și apeși <b>Partajare</b> sus.", "În fereastră, uită-te la rândul care spune <b>cine</b> are acces, de exemplu „Oricine are linkul poate edita”. Dă click pe el (sau pe rotița <b>Setări</b>).", "Alege <b>Persoane specifice</b> (pe unele versiuni: <b>Persoanele pe care le alegeți</b>). Așa, linkul merge doar la cei pe care îi scrii tu.", "Alege <b>ce pot face</b>: <b>Poate vizualiza</b> (doar citește) sau <b>Poate edita</b> (poate modifica). Implicit alege <b>vizualizare</b>.", "Scrie adresa de e-mail a persoanei, apoi <b>Trimitere</b> (Send) sau <b>Copiere link</b> (Copy link)."]}, {"t": "Bine de știut", "pasi": ["La <b>Persoane specifice</b> nu există parolă și dată de expirare. Acestea apar doar la „Oricine are linkul”, și doar pe unele conturi.", "Poți schimba sau opri accesul oricând, din același meniu: <b>Gestionare acces</b> (Manage access)."]}]}, "G10": {"titlu": "Cum văd cât spațiu ocupă OneDrive, telefonul sau căsuța de e-mail", "parti": [{"t": "OneDrive", "pasi": ["Pe web: intră pe onedrive.live.com (sau OneDrive-ul de la serviciu). Jos în stânga vezi „<b>… GB folosiți din …</b>”.", "Pe calculator: click pe norișorul OneDrive din dreapta jos (lângă ceas) → rotița → <b>Setări</b> (Settings) → <b>Cont</b> (Account)."]}, {"t": "Telefonul", "pasi": ["<b>Android</b>: <b>Setări</b> → <b>Stocare</b> (pe Samsung: <b>Setări</b> → <b>Îngrijire dispozitiv</b> / Întreținere baterie și dispozitiv → <b>Stocare</b>). Numele exacte diferă de la un telefon la altul.", "<b>iPhone</b>: <b>Configurări</b> → <b>General</b> → <b>Spațiu iPhone</b>."]}, {"t": "E-mailul", "pasi": ["<b>Gmail</b>: jos, sub lista de mesaje, vezi „… GB din 15 GB”.", "<b>Outlook.com</b>: <b>Setări</b> (rotița) → <b>General</b> → <b>Stocare</b> (Storage).", "Caută e-mailurile cu atașamente mari: în Gmail scrii în căutare <code>has:attachment larger:10M</code>."]}]}};
window.EX=[{"cod": "E01", "titlu": "Excel: bugetul meu pe o lună (SUM, AVERAGE, format 0.00)", "statut": "obl", "nota": "N3", "ore": [7], "suport": "1.1 Excel, pg. 5-8", "org": "Fișa evaluare – Nota 3", "vechi": "T01", "zi": 1, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-02", "sg2": "2026-10-27", "teorie": [{"zi": 2, "ora": 7, "titlu": "Word, Excel și drumul fișierului (OneDrive)"}], "gata": true, "fisa": "fise/Fisa_E01_Excel_Buget.docx", "rez_doc": "fise/Rezolvare_E01_Excel_Buget.docx", "pornire_var": [], "pornire": null, "pornire_desc": null, "model": ["fise/Model_E01_Buget.xlsx"], "fisier": "E01_Excel_Nume_Prenume.xlsx", "subiect": "E01 – Excel – Nume Prenume", "predare_obl": true, "pe_scurt": "<b>Exercițiul se notează (Nota 3).</b> Faci în Excel <b>bugetul tău pe o lună</b>: cel puțin 6 cheltuieli, cu sumele tale (le poți estima). Totalul îl calculează Excel, cu formula de adunare <b>=SUM</b>, iar media pe o cheltuială cu <b>=AVERAGE</b>. Apoi dai tabelului un aspect îngrijit: antet colorat, borduri, sume cu două zecimale. Cifrele sunt ale tale, deci lucrarea ta nu seamănă cu a nimănui. Miezul: <b>cam 40 de minute</b>.", "recap": ["Foaia Excel e o <b>grilă</b>: coloanele au litere (A, B, C), rândurile au numere (1, 2, 3). Fiecare celulă are o <b>adresă</b>, de exemplu <code>C4</code>.", "Orice <b>formulă</b> începe cu semnul <code>=</code>. <code>=SUM(C4:C9)</code> adună tot ce e între C4 și C9; <code>=AVERAGE(C4:C9)</code> face media. Două puncte (<code>:</code>) înseamnă „de la… până la…”.", "Nu tastezi niciodată rezultatul de mână. Dacă schimbi o sumă, formula se <b>recalculează singură</b>. Așa verifici că ai lucrat corect."], "text_dat": "", "cerinte": [{"titlu": "Tabelul cu cheltuieli și totalul cu =SUM", "minute": 20, "pasi": ["Deschide <b>Excel</b> → <b>Registru de lucru necompletat</b> (Blank workbook). Salvează-l imediat ca <code>E01_Excel_Nume_Prenume.xlsx</code>, în <b>Documente</b> (ghidul <b>G3</b>).", "În <code>A1</code> scrie titlul: <b>Bugetul meu – luna …</b> (luna aleasă de tine). În <code>A2</code> scrie numele tău și, dacă sumele sunt estimate, „sume estimate”.", "Pe rândul 3 scrie antetul: <code>A3</code> <b>Nr.</b>, <code>B3</code> <b>Cheltuiala</b>, <code>C3</code> <b>Suma (lei)</b>.", "Pe rândurile 4–9 scrie <b>cel puțin 6 cheltuieli</b> ale tale (de exemplu: chirie sau întreținere, mâncare, transport, utilități, telefon și internet, haine). În coloana C scrii doar <b>numărul</b>, fără „lei”.", "Pe rândul de sub ultima cheltuială scrie în coloana B <b>TOTAL</b>, iar în coloana C formula <code>=SUM(C4:C9)</code> și apasă <code>Enter</code>. Dacă ai mai multe cheltuieli, schimbă <code>C9</code> cu ultima celulă.", "<b>Testul:</b> schimbă suma de la prima cheltuială. Totalul s-a schimbat singur? Atunci formula e corectă. Pune suma la loc."], "ghiduri": ["G3"]}, {"titlu": "Media, aspectul și trimiterea", "minute": 20, "pasi": ["Sub TOTAL, scrie în coloana B <b>Media pe o cheltuială</b>, iar în coloana C <code>=AVERAGE(C4:C9)</code> (cu aceleași celule ca la SUM).", "Selectează sumele, totalul și media → click dreapta → <b>Formatare celule</b> (Format Cells) → <b>Număr</b> (Number) → <b>2 zecimale</b>. Dacă apare <code>#####</code>, coloana e prea îngustă: dublu click pe linia dintre literele C și D.", "Selectează tot tabelul (de la antet până la medie) → fila <b>Pornire</b> → butonul <b>Borduri</b> → <b>Toate bordurile</b> (All Borders). Fă antetul <b>îngroșat</b> (<code>Ctrl</code> + <code>B</code>) și colorează-l (butonul <b>Culoare de umplere</b>, găletușa).", "Fă rândul <b>TOTAL</b> îngroșat, ca să se vadă la prima privire.", "Salvează (<code>Ctrl</code> + <code>S</code>) și trimite fișierul cu subiectul cerut (ghidurile <b>G5</b> și <b>G6</b>)."], "ghiduri": ["G5", "G6"]}], "in_plus": {"titlu": "Câți bani rămân și un grafic", "pasi": ["Cu un rând liber mai jos, scrie în B <b>Venitul lunii</b> și în C suma (poate fi estimată). Pe rândul următor scrie <b>Rămân</b> și în C o formulă care scade totalul din venit, de exemplu <code>=C14-C10</code> (cu adresele tale).", "Selectează cheltuielile și sumele lor (fără TOTAL și medie) → <b>Inserare</b> (Insert) → <b>Diagramă circulară</b> (Pie). Dă-i un titlu: „Pe ce se duc banii”.", "Ce cheltuială are felia cea mai mare? Scrie răspunsul într-o celulă de sub grafic."]}, "verifica": ["În <code>A1</code> e titlul cu luna, iar în <code>A2</code> numele tău.", "Ai cel puțin 6 cheltuieli cu sumele tale, scrise ca numere (fără „lei” în celulă).", "Totalul e calculat cu <code>=SUM(...)</code>, nu tastat: dacă dai click pe el, vezi formula în bara de sus.", "Media e calculată cu <code>=AVERAGE(...)</code>, pe aceleași celule ca totalul.", "Sumele au 2 zecimale, nicio celulă nu arată <code>#####</code>, tabelul are borduri și antet colorat.", "Fișierul se numește <code>E01_Excel_Nume_Prenume.xlsx</code> și l-ai trimis cu subiectul corect."], "rez": {"intro": "Exercițiul e personal: sumele tale sunt diferite de ale oricui. Mai jos ai <b>o lucrare-model</b> cu sume inventate, ca să vezi cum arată o lucrare de nota 10. O găsești și ca fișier Excel, <code>Model_E01_Buget.xlsx</code>: dă click pe celulele cu totalul și media ca să vezi formulele. Notarea se face după <b>baremul oficial</b>, explicat la final pe acest exercițiu.", "parti": [{"titlu": "Lucrarea-model (sume inventate)", "html": "<p><code>A1</code>: <b>Bugetul meu – luna noiembrie 2026</b> · <code>A2</code>: Maria Popescu · sume estimate</p><div class='tw'><table><thead><tr><th scope='col'>Celula</th><th scope='col'>Nr.</th><th scope='col'>Cheltuiala</th><th scope='col'>Suma (lei)</th></tr></thead><tbody><tr><td>rândul 4</td><td>1</td><td>Întreținere</td><td>900,00</td></tr><tr><td>rândul 5</td><td>2</td><td>Mâncare</td><td>1.400,00</td></tr><tr><td>rândul 6</td><td>3</td><td>Transport</td><td>250,00</td></tr><tr><td>rândul 7</td><td>4</td><td>Utilități (curent, gaze)</td><td>520,00</td></tr><tr><td>rândul 8</td><td>5</td><td>Telefon și internet</td><td>110,00</td></tr><tr><td>rândul 9</td><td>6</td><td>Haine și încălțăminte</td><td>300,00</td></tr><tr><td>rândul 10</td><td></td><td>TOTAL  ← =SUM(C4:C9)</td><td>3.480,00</td></tr><tr><td>rândul 11</td><td></td><td>Media pe o cheltuială  ← =AVERAGE(C4:C9)</td><td>580,00</td></tr></tbody></table></div><p><b>Cum verifici:</b> 900 + 1.400 + 250 + 520 + 110 + 300 = <b>3.480</b>, iar 3.480 : 6 = <b>580</b>. Dacă la tine totalul și media se schimbă când schimbi o sumă, ai lucrat corect.</p><p><b>Pas în plus, în model:</b> venitul lunii 4.200,00 lei; <b>Rămân</b> <code>=C13-C10</code> = <b>720,00</b> lei. Felia cea mai mare din grafic: <b>Mâncare</b>.</p>"}, {"titlu": "Greșelile frecvente și cum le repari", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce vezi</th><th scope='col'>De ce</th><th scope='col'>Cum repari</th></tr></thead><tbody><tr><td>Totalul nu se schimbă când schimbi o sumă</td><td>Ai tastat rezultatul, nu formula</td><td>Șterge celula și scrie <code>=SUM(C4:C9)</code></td></tr><tr><td><code>#NUME?</code> (#NAME?)</td><td>Numele funcției e scris greșit sau Excelul e în altă limbă</td><td>Folosește butonul <b>Σ Însumare automată</b> (AutoSum) din fila Pornire: scrie singur formula</td></tr><tr><td>Totalul e 0 sau prea mic</td><td>Ai scris „900 lei” în celulă: Excel o vede ca text</td><td>Scrie doar <code>900</code>; „lei” stă în antet: <b>Suma (lei)</b></td></tr><tr><td><code>#####</code></td><td>Coloana e prea îngustă</td><td>Dublu click pe linia dintre literele coloanelor</td></tr><tr><td>O cheltuială nouă nu intră în total</td><td>Intervalul din SUM s-a oprit mai sus</td><td>Modifică intervalul (de exemplu <code>C4:C10</code>) sau inserează rândul în interiorul tabelului</td></tr></tbody></table></div>"}, {"titlu": "Cum se notează (baremul oficial) și ce urmărim", "html": "<div class='tw'><table><thead><tr><th scope='col'>Criteriu</th><th scope='col'>Puncte</th><th scope='col'>Ce urmărim la E01</th></tr></thead><tbody><tr><td>Planificarea conținutului</td><td>10</td><td>Tabelul are titlu, antet și ordine logică: cheltuieli, apoi TOTAL, apoi media.</td></tr><tr><td>Calitatea informației</td><td>15</td><td>Cel puțin 6 cheltuieli realiste; totalul și media sunt corecte (se verifică prin schimbarea unei sume).</td></tr><tr><td>Creativitate și design</td><td>10</td><td>Antet colorat și îngroșat, borduri, TOTAL evidențiat, coloane destul de late.</td></tr><tr><td>Utilizarea instrumentelor digitale</td><td>10</td><td><b>=SUM</b> și <b>=AVERAGE</b> folosite corect, pe intervalul bun; formatul cu 2 zecimale.</td></tr><tr><td>Respectarea drepturilor de autor</td><td>10</td><td>Sumele sunt ale tale (sau estimate de tine) și scrie asta în <code>A2</code>; nu ai copiat lucrarea altcuiva.</td></tr><tr><td>Adaptarea la publicul țintă</td><td>15</td><td>Oricine înțelege tabelul fără explicații: nume clare de cheltuieli, „(lei)” în antet.</td></tr><tr><td>Corectitudine lingvistică</td><td>10</td><td>Diacritice și ortografie corecte (Mâncare, Utilități, Întreținere).</td></tr><tr><td>Finalizare și prezentare</td><td>10</td><td>Fișierul are numele cerut, e salvat ca <code>.xlsx</code> și trimis cu subiectul corect.</td></tr><tr><td>Din oficiu</td><td>10</td><td></td></tr></tbody></table></div><div class='cadru'>Greșeli care costă puncte: totalul tastat de mână; „lei” scris în celule (formula dă alt rezultat); mai puțin de 6 cheltuieli; lipsa mediei; fișier trimis fără atașament sau cu alt nume.</div>"}]}, "glume": ["Excel nu te judecă pentru cât dai pe cafea. Doar adună. Exact. Fără milă.", "=SUM e ca un controlor de bilete: nu-i scapă nimeni dintre C4 și C9."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Tabelul cu cheltuieli și totalul cu =SUM", 20], ["Cerința 2 – Media, aspectul și trimiterea", 20], ["Pas în plus – Câți bani rămân și un grafic", 50], ["Întrebări și discuție", 15]]}, {"cod": "E02", "titlu": "Fișierele mele în ordine: foldere, nume, OneDrive", "statut": "rec", "nota": null, "ore": [7], "suport": "1.1, pg. 5-8", "org": "—", "vechi": "T02", "zi": 1, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-02", "sg2": "2026-10-27", "teorie": [{"zi": 2, "ora": 7, "titlu": "Word, Excel și drumul fișierului (OneDrive)"}], "gata": true, "fisa": "fise/Fisa_E02_Fisierele_mele_in_ordine.docx", "rez_doc": "fise/Rezolvare_E02_Fisierele_mele_in_ordine.docx", "pornire_var": [], "pornire": "fise/E02_Fisiere_PORNIRE.docx", "pornire_desc": "Lista celor 12 fișiere ale Costinei și tabelul de completat (nume nou + folder), plus locul pentru captură.", "model": [], "fisier": "E02_Fisiere_Nume_Prenume.docx", "subiect": "E02 – Fisiere – Nume Prenume", "predare_obl": false, "pe_scurt": "Colega ta, <b>Costina</b>, are pe desktop 12 fișiere cu nume ca „raport FINAL bun” și „Document Microsoft Word nou (3)”. Nu mai găsește nimic. Tu le dai <b>nume clare</b>, după o regulă, și le împarți în <b>4 foldere</b>. Apoi faci chiar tu foldere în <b>Documente</b>, ca să vezi cum arată ordinea. Nu ștergi nimic: doar propui. Miezul: <b>cam 35 de minute</b>.", "recap": ["Un nume bun spune <b>ce e</b> fișierul și <b>din ce lună</b>: <code>AAAA-LL_Subiect</code>, de exemplu <code>2026-10_Buget.xlsx</code>. Pus așa, Windows îl sortează singur în ordinea datei.", "Fără spații, fără diacritice, fără „final”, „nou”, „copie” sau „!!!”. Când ai mai multe variante ale aceluiași fișier: <code>_v1</code>, <code>_v2</code>.", "<b>Extensia</b> (<code>.docx</code>, <code>.xlsx</code>, <code>.pdf</code>, <code>.jpg</code>) nu se schimbă niciodată când redenumești: ea spune cu ce program se deschide fișierul."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Numele de acum</th><th scope='col'>Ce este, de fapt</th></tr></thead><tbody><tr><td>1</td><td>Document Microsoft Word nou (3).docx</td><td>Cererea ta de concediu pentru decembrie 2026</td></tr><tr><td>2</td><td>raport.docx</td><td>Raportul lunar pe octombrie 2026, prima variantă</td></tr><tr><td>3</td><td>raport FINAL bun.docx</td><td>Raportul lunar pe octombrie 2026, varianta trimisă șefului</td></tr><tr><td>4</td><td>scan_0045.pdf</td><td>Adeverința de salariat, din septembrie 2026</td></tr><tr><td>5</td><td>IMG_20260815_174512.jpg</td><td>Poză de la ziua mamei, august 2026</td></tr><tr><td>6</td><td>buget.xlsx</td><td>Bugetul pe octombrie 2026</td></tr><tr><td>7</td><td>Copie - buget.xlsx</td><td>Aceeași foaie ca nr. 6, copiată din greșeală</td></tr><tr><td>8</td><td>factura!!!.pdf</td><td>Factura de curent pe septembrie 2026</td></tr><tr><td>9</td><td>Prezentare1.pptx</td><td>Prezentarea pentru instruirea de la birou, din noiembrie 2026</td></tr><tr><td>10</td><td>NU UMBLA.xlsx</td><td>Lista cu telefoanele colegilor de tură (o actualizezi mereu)</td></tr><tr><td>11</td><td>contract.pdf</td><td>Contractul de închiriere al apartamentului, din martie 2025</td></tr><tr><td>12</td><td>WhatsApp Image 2026-09-20 at 10.12.33.jpeg</td><td>Poza cu mersul trenurilor afișat în stație</td></tr></tbody></table></div>", "cerinte": [{"titlu": "Nume noi și foldere, pe hârtie", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E02_Fisiere_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Scrie la punctul 1 <b>regula ta de denumire</b>. Poți folosi regula din „Ce ai învățat la teorie” sau una a ta, dar s-o respecți la toate fișierele.", "Alege <b>4 foldere</b>, cu număr în față ca să stea în ordine, de exemplu <code>01_Serviciu</code>, <code>02_Acte</code>, <code>03_Bani</code>, <code>04_Familie_si_poze</code>.", "Completează tabelul pentru toate cele 12 fișiere: <b>Folderul</b> și <b>Numele nou</b>. Păstrează extensia fiecăruia.", "La punctul 3 scrie care fișiere sunt în dublu și pe care îl păstrezi. La două fișiere „asemănătoare” gândește-te: sunt chiar la fel sau sunt <b>două variante</b>?"], "ghiduri": ["G3"]}, {"titlu": "Foldere adevărate în Documente", "minute": 15, "pasi": ["Deschide Explorer (<code>Windows</code> + <code>E</code>) → <b>Documente</b>. Click dreapta pe un loc gol → <b>Nou</b> (New) → <b>Folder</b>. Numește-l <code>E02_Ordine</code> și apasă <code>Enter</code>.", "Intră în <code>E02_Ordine</code> și fă înăuntru cele <b>4 foldere</b> alese de tine, la fel (click dreapta → <b>Nou</b> → <b>Folder</b>).", "Închide documentul Word, apoi mută-l în folderul potrivit: trage-l cu mausul din <b>Documente</b> pe numele folderului. Dacă nu-l mai găsești, caută-l după nume (ghidul <b>G3</b>).", "Fă o <b>captură</b> cu fereastra Explorer, în care se văd cele 4 foldere (ghidul <b>G1</b>). Deschide din nou documentul și lipește captura la punctul 4 (ghidul <b>G2</b>). Salvează."], "ghiduri": ["G1", "G2"]}], "in_plus": {"titlu": "Găsește un fișier în 10 secunde", "pasi": ["În Explorer, intră în <b>Documente</b> și scrie în caseta de căutare (dreapta sus) un cuvânt din numele unui fișier, de exemplu <code>E02</code>. Apasă <code>Enter</code>.", "Sortează fișierele după dată: click pe antetul coloanei <b>Data modificării</b> (Date modified). Click încă o dată: ordinea se inversează.", "Dacă ai OneDrive: copiază folderul <code>E02_Ordine</code> în <b>OneDrive</b> (în stânga, în Explorer) și verifică pe telefon, în aplicația OneDrive, că a apărut."]}, "verifica": ["Ai scris regula de denumire și ai respectat-o la toate fișierele.", "Toate cele 12 rânduri au folder și nume nou, fără spații, fără diacritice, fără „final” sau „copie”.", "Fiecare fișier și-a păstrat extensia (.docx rămâne .docx).", "Ai găsit perechea în dublu (6 și 7) și ai observat că 2 și 3 sunt <b>două variante</b>, nu un dublu.", "Ai făcut folderele în Documente și ai lipit captura în document."], "rez": {"intro": "Mai jos ai un model complet. Numele tale de foldere pot fi altele (de exemplu <code>01_Munca</code> în loc de <code>01_Serviciu</code>): contează să ai <b>o regulă</b> și s-o respecți la toate fișierele.", "parti": [{"titlu": "Regula și cele 12 fișiere (model)", "html": "<p><b>Regula:</b> <code>AAAA-LL_Subiect_vN</code> – anul și luna documentului, apoi subiectul, cuvintele legate cu <code>_</code>, fără spații și fără diacritice. <code>_v1</code>, <code>_v2</code> doar când există mai multe variante.</p><div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Folderul</th><th scope='col'>Numele nou</th></tr></thead><tbody><tr><td>1</td><td>01_Serviciu</td><td>2026-12_Cerere_concediu.docx</td></tr><tr><td>2</td><td>01_Serviciu</td><td>2026-10_Raport_lunar_v1.docx</td></tr><tr><td>3</td><td>01_Serviciu</td><td>2026-10_Raport_lunar_v2.docx</td></tr><tr><td>4</td><td>02_Acte</td><td>2026-09_Adeverinta_salariat.pdf</td></tr><tr><td>5</td><td>04_Familie_si_poze</td><td>2026-08_Ziua_mamei.jpg</td></tr><tr><td>6</td><td>03_Bani</td><td>2026-10_Buget.xlsx</td></tr><tr><td>7</td><td>—</td><td>nu se păstrează: e aceeași foaie ca nr. 6</td></tr><tr><td>8</td><td>03_Bani</td><td>2026-09_Factura_curent.pdf</td></tr><tr><td>9</td><td>01_Serviciu</td><td>2026-11_Prezentare_instruire.pptx</td></tr><tr><td>10</td><td>01_Serviciu</td><td>Telefoane_colegi_tura.xlsx (fără dată: e mereu la zi)</td></tr><tr><td>11</td><td>02_Acte</td><td>2025-03_Contract_inchiriere.pdf</td></tr><tr><td>12</td><td>01_Serviciu</td><td>2026-09_Mers_trenuri_statie.jpeg</td></tr></tbody></table></div>"}, {"titlu": "De ce așa", "html": "<p><b>6 și 7 sunt în dublu:</b> „Copie - buget.xlsx” e aceeași foaie. Se păstrează unul singur (nr. 6), ca să nu lucrezi într-una și să trimiți cealaltă. Nu-l ștergi tu: îi propui Costinei.</p><p><b>2 și 3 nu sunt în dublu:</b> sunt două variante ale raportului. Le păstrezi pe amândouă, cu <code>_v1</code> și <code>_v2</code>. Așa știi sigur care a plecat la șef: cea mai mare versiune.</p><p><b>Nr. 10 nu are dată:</b> lista de telefoane se actualizează mereu, deci data din nume ar minți după o lună.</p><p><b>„NU UMBLA” și „!!!” nu protejează nimic.</b> Un nume clar și folderul potrivit fac mai mult decât orice semn de exclamare.</p><p><b>Captura:</b> se văd folderul <code>E02_Ordine</code> și înăuntru cele 4 foldere, în ordinea numerelor, plus documentul tău mutat într-unul dintre ele.</p>"}]}, "glume": ["„FINAL_FINAL_ACUM_bun.docx” e ca anunțul „ultimul tren din seara asta”: îl auzi de trei ori pe seară."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Nume noi și foldere, pe hârtie", 20], ["Cerința 2 – Foldere adevărate în Documente", 15], ["Pas în plus – Găsește un fișier în 10 secunde", 55], ["Întrebări și discuție", 15]]}, {"cod": "E03", "titlu": "Căutare: „siguranța pe internet” – cuvinte-cheie, primul site, e credibil?", "statut": "obl", "nota": "N1", "ore": [5, 11], "suport": "1.2, pg. 9-13; 1.4, pg. 21", "org": "Fișa evaluare – Nota 1, Act. 2", "vechi": "T03", "zi": 2, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-05", "sg2": "2026-10-28", "teorie": [{"zi": 2, "ora": 5, "titlu": "Motoare de căutare, operatori, surse"}, {"zi": 3, "ora": 11, "titlu": "Gândire critică"}], "gata": true, "fisa": "fise/Fisa_E03_Cautare.docx", "rez_doc": "fise/Rezolvare_E03_Cautare.docx", "pornire_var": [], "pornire": "fise/E03_Cautare_PORNIRE.docx", "pornire_desc": "Foaia de răspuns, cu câmpurile din fișa de evaluare a organizatorului (cuvinte-cheie, primul site, credibilitate) și tabelul cu cele 5 criterii.", "model": [], "fisier": "E03_Cautare_Nume_Prenume.docx", "subiect": "E03 – Cautare – Nume Prenume", "predare_obl": true, "pe_scurt": "<b>Exercițiul se notează (Nota 1, împreună cu E04 și E06).</b> Cauți pe internet informații despre <b>„siguranța pe internet”</b>, exact ca în fișa de evaluare: scrii <b>cuvintele-cheie</b> folosite, <b>primul site accesat</b> și dacă <b>sursa e credibilă și de ce</b>. Verdictul îl dai cu cele 5 criterii din suportul de curs, confirmi într-o a doua sursă și scrii 3 sfaturi pentru colegi. Căutarea e a ta: o dovedești cu o captură în care se vede data. Miezul: <b>cam 45 de minute</b>.", "recap": ["<b>Cuvintele-cheie:</b> 2–4 cuvinte clare, nu o propoziție întreagă. Ghilimelele caută <b>expresia exactă</b> (<code>\"siguranța pe internet\"</code>), <code>site:ro</code> caută doar pe site-uri din România, <code>-</code> exclude un cuvânt.", "Rezultatele cu eticheta <b>Sponsorizat</b> (Sponsored) sunt <b>reclame</b>. „Primul site” e primul rezultat obișnuit de sub ele.", "Cele <b>5 criterii</b> pentru o sursă (suport, 1.4, pg. 21): <b>Autoritate</b> (cine scrie?), <b>Publicație</b> (instituție, presă, blog, firmă?), <b>Actualitate</b> (are dată?), <b>Obiectivitate</b> (ton calm sau alarmist? vinde ceva?), <b>Verificabilitate</b> (are surse? confirmă și alt site?)."], "text_dat": "", "cerinte": [{"titlu": "Căutarea și primul site", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E03_Cautare_Nume_Prenume.docx</code> (ghidul <b>G3</b>). Scrie-ți numele și data sus.", "Deschide browserul și caută despre <b>siguranța pe internet</b>. Alege tu cuvintele-cheie (2–4 cuvinte) și scrie-le în tabel <b>exact</b> cum le-ai tastat.", "Fă o <b>captură</b> cu pagina de rezultate, în care se vede și <b>ceasul cu data</b> din colțul ecranului (ghidul <b>G1</b>). Lipește-o sub tabel (ghidul <b>G2</b>).", "Treci peste rezultatele marcate <b>Sponsorizat</b>. Deschide <b>primul rezultat obișnuit</b> și copiază adresa completă din bara de adrese: click în bara de adrese (sau <code>Ctrl</code> + <code>L</code>), apoi <code>Ctrl</code> + <code>C</code>. Lipește-o în tabel (<code>Ctrl</code> + <code>V</code>).", "Află <b>cine e în spatele site-ului</b>: uită-te jos pe pagină sau la „Despre noi” / „Contact”. Scrie numele instituției, al firmei sau „nu apare”."], "ghiduri": ["G3", "G1", "G2"]}, {"titlu": "Verdictul, a doua sursă și 3 sfaturi", "minute": 25, "pasi": ["Completează tabelul de la punctul 2: pentru fiecare criteriu scrie <b>ce ai văzut</b> pe site (nu doar „da” sau „nu”). La final scrie <b>verdictul</b>: credibilă, necredibilă sau parțial.", "Fă <b>a doua căutare</b>, cu un operator: de exemplu <code>\"siguranța pe internet\" site:ro</code> sau <code>siguranța pe internet -reclamă</code>. Scrie ce ai tastat și adresa unei <b>a doua surse</b> care spune același lucru.", "La punctul 4 scrie <b>3 sfaturi</b> de siguranță pe internet, <b>cu cuvintele tale</b>, pentru colegii de birou. Câte unul pe rând, scurte și concrete.", "La <b>Sursa</b> scrie de unde ai luat sfaturile: numele site-ului și adresa lui. Nu copia fraze întregi; dacă totuși citezi, pune textul între ghilimele.", "Verifică ortografia cu <code>F7</code>, salvează (<code>Ctrl</code> + <code>S</code>) și trimite fișierul (ghidul <b>G6</b>)."], "ghiduri": ["G6"]}], "in_plus": {"titlu": "Un ghid oficial în PDF", "pasi": ["Caută <code>siguranța pe internet filetype:pdf site:ro</code>. Operatorul <code>filetype:pdf</code> aduce doar fișiere PDF.", "Deschide un rezultat de la o <b>instituție</b> (de exemplu un minister, DNSC sau o organizație cunoscută). Notează la finalul documentului titlul ghidului, cine l-a scris și anul.", "Compară: sfaturile din ghid se potrivesc cu cele 3 sfaturi ale tale?"]}, "verifica": ["Ai scris cuvintele-cheie exact cum le-ai tastat și motorul de căutare folosit.", "Primul site e un rezultat obișnuit (nu o reclamă) și are adresa completă, care începe cu <code>https://</code>.", "Captura arată pagina de rezultate și data din colțul ecranului.", "La fiecare dintre cele 5 criterii ai scris ce ai văzut, iar verdictul se potrivește cu ele.", "Ai o a doua căutare cu operator și o a doua sursă care confirmă.", "Cele 3 sfaturi sunt scrise cu cuvintele tale, iar sursa e trecută dedesubt."], "rez": {"intro": "Fiecare cursant găsește alte site-uri, deci nu există un singur răspuns. Mai jos ai <b>o lucrare-model</b> și cum se notează, criteriu cu criteriu. Site-urile din model sunt exemple: dacă tu ai găsit altele, contează să fi judecat sursa <b>cu cele 5 criterii</b> și să fi motivat verdictul.", "parti": [{"titlu": "Lucrarea-model: căutarea", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce completezi</th><th scope='col'>Exemplu bun</th></tr></thead><tbody><tr><td>Motorul de căutare</td><td>Google</td></tr><tr><td>Cuvintele-cheie</td><td>siguranța pe internet sfaturi</td></tr><tr><td>Primul site accesat</td><td>Adresa completă, copiată din bara de adrese, de exemplu o pagină de pe dnsc.ro (Directoratul Național de Securitate Cibernetică)</td></tr><tr><td>Cine e în spatele site-ului</td><td>DNSC, instituția statului care se ocupă de securitatea cibernetică în România</td></tr></tbody></table></div><p><b>Captura</b> arată lista de rezultate și, jos în dreapta, data și ora. Dacă primul rezultat ar fi fost marcat <b>Sponsorizat</b>, l-am fi sărit.</p>"}, {"titlu": "Lucrarea-model: verdictul", "html": "<div class='tw'><table><thead><tr><th scope='col'>Criteriul</th><th scope='col'>Ce am văzut</th></tr></thead><tbody><tr><td>Autoritate</td><td>Scrie o instituție a statului, specializată exact în acest subiect.</td></tr><tr><td>Publicație</td><td>Site oficial (.ro), nu blog și nu magazin.</td></tr><tr><td>Actualitate</td><td>Pagina are data publicării, din ultimii ani (sau: „nu are dată, dar site-ul e actualizat des”).</td></tr><tr><td>Obiectivitate</td><td>Ton calm, explicativ. Nu vinde nimic și nu sperie.</td></tr><tr><td>Verificabilitate</td><td>Aceleași sfaturi apar și pe salvaticopiii.ro, la secțiunea despre siguranța online.</td></tr><tr><td>Verdict</td><td><b>Credibilă</b>: instituție de specialitate, ton calm, informația se confirmă în altă sursă.</td></tr></tbody></table></div><p><b>A doua căutare:</b> <code>\"siguranța pe internet\" site:ro</code> → a doua sursă: o pagină de pe salvaticopiii.ro.</p><p><b>Exemplu de verdict „parțial”:</b> un articol pe blogul unei firme care vinde antivirus. Sfaturile pot fi bune, dar scopul e să vândă: confirmi într-o sursă fără interes comercial.</p>"}, {"titlu": "Lucrarea-model: 3 sfaturi pentru colegi", "html": "<p>1) Folosește la fiecare cont <b>altă parolă</b>, lungă, și pornește <b>autentificarea în doi pași</b> acolo unde se poate.</p><p>2) Nu apăsa pe linkuri din mesaje care te grăbesc („contul se blochează azi”). Intră singur pe site-ul oficial.</p><p>3) Ține telefonul și calculatorul <b>actualizate</b>: actualizările închid exact ușile pe care intră hoții.</p><p><b>Sursa:</b> Directoratul Național de Securitate Cibernetică, dnsc.ro (adresa completă a paginii); confirmat pe salvaticopiii.ro.</p>"}, {"titlu": "Cum se notează (baremul oficial) și ce urmărim", "html": "<div class='tw'><table><thead><tr><th scope='col'>Criteriu</th><th scope='col'>Puncte</th><th scope='col'>Ce urmărim la E03</th></tr></thead><tbody><tr><td>Planificarea conținutului</td><td>10</td><td>Câmpurile din fișa de evaluare sunt completate în ordine: cuvinte-cheie, primul site, credibilitate, apoi a doua sursă și sfaturile.</td></tr><tr><td>Calitatea informației</td><td>15</td><td>Verdictul se sprijină pe cele 5 criterii, cu ce ai văzut pe site; sfaturile sunt corecte și pe subiect.</td></tr><tr><td>Creativitate și design</td><td>10</td><td>Documentul e îngrijit: tabelele completate, captura decupată și clară.</td></tr><tr><td>Utilizarea instrumentelor digitale</td><td>10</td><td>Cuvinte-cheie potrivite, un operator folosit corect, adresa copiată din bara de adrese, captura lipită.</td></tr><tr><td>Respectarea drepturilor de autor</td><td>10</td><td>Sursa e trecută cu numele site-ului și adresa; sfaturile sunt cu cuvintele tale, nu copiate.</td></tr><tr><td>Adaptarea la publicul țintă</td><td>15</td><td>Sfaturile sunt scrise pentru colegi: scurte, concrete, ușor de pus în practică.</td></tr><tr><td>Corectitudine lingvistică</td><td>10</td><td>Diacritice, ortografie, propoziții complete.</td></tr><tr><td>Finalizare și prezentare</td><td>10</td><td>Fișierul are numele cerut și e trimis cu subiectul corect.</td></tr><tr><td>Din oficiu</td><td>10</td><td></td></tr></tbody></table></div><div class='cadru'>Greșeli care costă puncte: „e credibil pentru că e primul la Google”; o reclamă trecută drept primul site; adresa scrisă pe scurt („dnsc”) în loc de adresa completă; verdict fără motive; sfaturi copiate de pe site, fără sursă; lipsa capturii.</div>"}]}, "glume": ["Primul rezultat la Google nu e neapărat cel mai bun. E doar primul. Ca vagonul de lângă locomotivă: nu e cel mai confortabil, doar cel mai aproape."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Căutarea și primul site", 20], ["Cerința 2 – Verdictul, a doua sursă și 3 sfaturi", 25], ["Pas în plus – Un ghid oficial în PDF", 45], ["Întrebări și discuție", 15]]}, {"cod": "E04", "titlu": "E-mail formal către angajator", "statut": "obl", "nota": "N1", "ore": [9], "suport": "1.3, pg. 14-20", "org": "Fișa evaluare – Nota 1, Act. 1", "vechi": "T04", "zi": 2, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-05", "sg2": "2026-10-28", "teorie": [{"zi": 3, "ora": 9, "titlu": "Comunicare digitală · e-mail"}], "gata": true, "fisa": "fise/Fisa_E04_Email_angajator.docx", "rez_doc": "fise/Rezolvare_E04_Email_angajator.docx", "pornire_var": [], "pornire": "fise/E04_Email_PORNIRE.docx", "pornire_desc": "Foaia cu câmpurile din fișa de evaluare (destinatar, subiect, mesaj) și lista de verificare de dinainte de trimitere.", "model": [], "fisier": "E04_Email_Nume_Prenume.docx", "subiect": "E04 – Subiectul tău – Nume Prenume", "predare_obl": true, "pe_scurt": "<b>Exercițiul se notează (Nota 1, împreună cu E03 și E06).</b> Scrii <b>un e-mail formal către angajator</b>, ca în fișa de evaluare: <b>destinatar, subiect, mesaj</b>. Alegi una dintre cele 5 situații și o completezi cu detaliile tale. Întâi îl scrii în Word, apoi <b>îl trimiți de-adevăratelea</b>, de pe adresa ta. Formatorul joacă rolul șefului. Miezul: <b>cam 40 de minute</b>.", "recap": ["<b>Subiectul</b> spune din prima despre ce e vorba: „Cerere concediu de odihnă 15–19 decembrie”, nu „Salut” și nu „URGENT!!!”.", "<b>Mesajul</b>, în ordine: adresare („Bună ziua, domnule / doamnă …,”); contextul; <b>ce ceri</b>; <b>până când</b> sau <b>pentru ce dată</b>; mulțumirea; încheierea („Cu stimă,”) și <b>semnătura</b> (nume, funcție, telefon).", "<b>Trei secunde înainte de Trimitere</b> (suport 1.3, pg. 15): ortografia; destinatarii (cine trebuie, nimeni în plus); atașamentul chiar atașat. Fără MAJUSCULE: online înseamnă că strigi."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Situația (alegi una)</th></tr></thead><tbody><tr><td>1</td><td>Ceri <b>concediu de odihnă</b> pentru câteva zile alese de tine.</td></tr><tr><td>2</td><td>Ceri aprobarea pentru un <b>schimb de tură</b> cu un coleg (cine, ce zile).</td></tr><tr><td>3</td><td>Ceri o <b>adeverință de salariat</b> (pentru bancă, grădiniță, primărie).</td></tr><tr><td>4</td><td>Anunți că <b>întârzii o zi</b> (de exemplu o programare la un ghișeu sau mașina în service) și propui cum recuperezi.</td></tr><tr><td>5</td><td>Ceri să participi la un <b>curs</b> sau la o instruire (care, când, de ce îți folosește la serviciu).</td></tr></tbody></table></div><p>Poți inventa numele șefului și adresa lui de e-mail (de exemplu <code>ion.popescu@exemplu.ro</code>). Datele tale, zilele și motivul sunt alese de tine.</p>", "cerinte": [{"titlu": "Scrie e-mailul în Word", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E04_Email_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Alege <b>o situație</b> din tabelul „<b>Textul pe care îl folosești</b>” și scrie numărul ei sus. Hotărăște detaliile: zilele, numele colegului, pentru ce ai nevoie de adeverință etc.", "Completează <b>Destinatarul</b> și <b>Subiectul</b>. Subiectul are 4–8 cuvinte și spune exact ce ceri (cu zilele, dacă e cazul).", "Scrie <b>Mesajul</b>, 5–8 rânduri: adresare; contextul într-o propoziție; <b>cererea</b>; data sau termenul; mulțumirea; „Cu stimă,” și semnătura (nume, funcție, telefon de serviciu sau „telefon inventat”).", "Bifează lista de la punctul 2. Unde ai „Nu”, corectează. Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": ["G3"]}, {"titlu": "Trimite e-mailul de-adevăratelea", "minute": 20, "pasi": ["Deschide e-mailul tău și apasă <b>E-mail nou</b> (New mail / Compose). <b>Către:</b> <code>bogdan@pandapc.ro</code> (formatorul joacă rolul șefului).", "<b>Subiect:</b> <code>E04 – </code> urmat de subiectul tău, apoi numele, de exemplu: <code>E04 – Cerere concediu de odihnă 15–19 decembrie – Popescu Maria</code>.", "Copiază <b>mesajul</b> din Word (selectezi, <code>Ctrl</code> + <code>C</code>) și lipește-l în e-mail (<code>Ctrl</code> + <code>V</code>). Verifică să nu se fi stricat rândurile sau diacriticele.", "<b>Atașează</b> documentul Word (ghidul <b>G5</b>) și verifică dacă apare caseta cu numele lui. În mesaj adaugă un rând: „Atașez și documentul cu cererea.”", "Ultimele 3 secunde: ortografia, destinatarul, atașamentul. Apoi <b>Trimitere</b>. Verifică în <b>Elemente trimise</b> (Sent) că a plecat (ghidul <b>G6</b>)."], "ghiduri": ["G5", "G6"]}], "in_plus": {"titlu": "Semnătura automată", "pasi": ["<b>Outlook:</b> <b>Setări</b> (rotița) → <b>Cont</b> → <b>Semnături</b> (Signatures). <b>Gmail:</b> rotița → <b>Vedeți toate setările</b> → <b>Semnătură</b>.", "Scrie o semnătură de 2–3 rânduri: nume și prenume, funcția, telefonul (poate fi inventat). Salvează.", "Deschide un <b>E-mail nou</b> și verifică că semnătura apare singură. Fă o captură (ghidul <b>G1</b>) și lipește-o la finalul documentului."]}, "verifica": ["În Word ai completat destinatarul, subiectul și mesajul, iar lista de verificare e bifată.", "Subiectul spune clar ce ceri (cu zilele sau data, unde e cazul).", "Mesajul are adresare, context, cerere, termen, mulțumire, încheiere și semnătură, fără MAJUSCULE și fără „!!!”.", "E-mailul a plecat la <code>bogdan@pandapc.ro</code>, cu subiectul care începe cu „E04 – ” și se termină cu numele tău.", "Documentul Word e atașat, iar e-mailul apare în Elemente trimise."], "rez": {"intro": "Mai jos ai <b>câte un e-mail-model pentru fiecare dintre cele 5 situații</b>. Detaliile tale sunt altele: contează ca e-mailul tău să aibă <b>aceleași părți</b>, în aceeași ordine, și tonul potrivit pentru un șef. La final, cum se notează după baremul oficial.", "parti": [{"titlu": "Situația 1 – Concediu de odihnă", "html": "<div class='cadru'>Către: Ion Popescu &lt;ion.popescu@exemplu.ro&gt; · Subiect: Cerere concediu de odihnă 15–19 decembrie<br>Bună ziua, domnule Popescu,<br>vă rog să-mi aprobați 5 zile de concediu de odihnă, de luni, 15 decembrie, până vineri, 19 decembrie, inclusiv. Lucrările mele curente le predau colegei Elena Stan până vineri, 12 decembrie. Atașez și documentul cu cererea.<br>Vă mulțumesc!<br>Cu stimă,<br>Maria Popescu<br>Casa de bilete, stația Iași · tel. 07xx xxx xxx</div>"}, {"titlu": "Situația 2 – Schimb de tură", "html": "<div class='cadru'>Subiect: Aprobare schimb de tură 3 noiembrie – Popescu / Ilie<br>Bună ziua, doamnă Rusu,<br>vă rog să aprobați un schimb de tură: luni, 3 noiembrie, lucrez eu tura de după-amiază (15:00–23:00) în locul lui Radu Ilie, iar el lucrează tura mea de dimineață (7:00–15:00). Radu este de acord și este în copie la acest mesaj.<br>Vă mulțumesc!<br>Cu stimă,<br>Maria Popescu</div><p><b>De ce e Radu în Cc:</b> el trebuie doar să știe, nu să aprobe. Ceilalți colegi nu primesc mesajul.</p>"}, {"titlu": "Situația 3 – Adeverință de salariat", "html": "<div class='cadru'>Subiect: Cerere adeverință de salariat pentru bancă<br>Bună ziua, doamnă Ionescu,<br>vă rog să-mi eliberați o adeverință de salariat, de care am nevoie la bancă pentru un credit. Dacă se poate, aș avea nevoie de ea până miercuri, 5 noiembrie. O pot ridica de la biroul dumneavoastră sau o puteți trimite scanată pe e-mail.<br>Vă mulțumesc!<br>Cu stimă,<br>Maria Popescu, casa de bilete</div>"}, {"titlu": "Situația 4 – Întârziere anunțată din timp", "html": "<div class='cadru'>Subiect: Întârziere joi, 6 noiembrie, până la ora 10:00<br>Bună ziua, domnule Popescu,<br>vă anunț că joi, 6 noiembrie, ajung la serviciu la ora 10:00 în loc de 8:00, pentru că am o programare la ghișeul de pașapoarte. Recuperez cele două ore vineri, de la 15:00 la 17:00, dacă sunteți de acord. Colega Elena Stan știe ce e urgent în ziua aceea.<br>Vă mulțumesc pentru înțelegere!<br>Cu stimă,<br>Maria Popescu</div>"}, {"titlu": "Situația 5 – Participare la un curs", "html": "<div class='cadru'>Subiect: Cerere participare la cursul „Excel pentru birou”, 10–12 noiembrie<br>Bună ziua, doamnă Rusu,<br>vă rog să-mi aprobați participarea la cursul online „Excel pentru birou”, din 10–12 noiembrie, între 17:00 și 19:00, după program. Cursul m-ar ajuta să fac mai repede situațiile lunare de vânzări. Nu afectează turele mele.<br>Vă mulțumesc!<br>Cu stimă,<br>Maria Popescu</div>"}, {"titlu": "E-mailul trimis la formator", "html": "<p><b>Către:</b> bogdan@pandapc.ro · <b>Subiect:</b> <code>E04 – Cerere concediu de odihnă 15–19 decembrie – Popescu Maria</code> · <b>Mesajul:</b> cel din Word · <b>Atașament:</b> <code>E04_Email_Popescu_Maria.docx</code>.</p><div class='cadru'>Greșeala clasică: „Atașez documentul” în mesaj, dar fără atașament. De aceea atașezi întâi fișierul și abia apoi scrii propoziția.</div>"}, {"titlu": "Cum se notează (baremul oficial) și ce urmărim", "html": "<div class='tw'><table><thead><tr><th scope='col'>Criteriu</th><th scope='col'>Puncte</th><th scope='col'>Ce urmărim la E04</th></tr></thead><tbody><tr><td>Planificarea conținutului</td><td>10</td><td>Câmpurile din fișa de evaluare sunt completate: destinatar, subiect, mesaj; mesajul are părțile în ordinea bună.</td></tr><tr><td>Calitatea informației</td><td>15</td><td>Cererea e clară și completă: ce, când, până când; detaliile se potrivesc între ele (zile, ore).</td></tr><tr><td>Creativitate și design</td><td>10</td><td>Mesajul e aerisit, pe paragrafe scurte, cu semnătură îngrijită.</td></tr><tr><td>Utilizarea instrumentelor digitale</td><td>10</td><td>E-mailul a fost trimis cu adevărat, cu subiectul cerut și documentul atașat.</td></tr><tr><td>Respectarea drepturilor de autor</td><td>10</td><td>Conținut propriu, fără date personale reale ale altora (numele șefului și adresa pot fi inventate).</td></tr><tr><td>Adaptarea la publicul țintă</td><td>15</td><td>Ton formal și politicos, potrivit pentru un șef: adresare, mulțumire, „Cu stimă”.</td></tr><tr><td>Corectitudine lingvistică</td><td>10</td><td>Diacritice, ortografie, punctuație; fără MAJUSCULE și fără „!!!”.</td></tr><tr><td>Finalizare și prezentare</td><td>10</td><td>Documentul Word are numele cerut, iar lista de verificare e bifată.</td></tr><tr><td>Din oficiu</td><td>10</td><td></td></tr></tbody></table></div><div class='cadru'>Greșeli care costă puncte: subiect gol sau „Cerere”; „Salut” sau „Hey” către șef; lipsa datei sau a termenului; lipsa semnăturii; „atașez documentul”, dar fără atașament; e-mail trimis la altă adresă.</div>"}]}, "glume": ["Un e-mail fără subiect e ca un tren fără tăbliță cu destinația: poate e al tău, dar nu urcă nimeni."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Scrie e-mailul în Word", 20], ["Cerința 2 – Trimite e-mailul de-adevăratelea", 20], ["Pas în plus – Semnătura automată", 50], ["Întrebări și discuție", 15]]}, {"cod": "E05", "titlu": "Excel: media, minimul, maximul (AVERAGE, MIN, MAX)", "statut": "rec", "nota": null, "ore": [7], "suport": "1.1, pg. 6-8", "org": "—", "vechi": "T05", "zi": 3, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-06", "sg2": "2026-10-29", "teorie": [{"zi": 2, "ora": 7, "titlu": "Word, Excel și drumul fișierului (OneDrive)"}], "gata": true, "fisa": "fise/Fisa_E05_Excel_Media_Min_Max.docx", "rez_doc": "fise/Rezolvare_E05_Excel_Media_Min_Max.docx", "pornire_var": [], "pornire": "fise/E05_Bilete_PORNIRE.xlsx", "pornire_desc": "Tabelul cu biletele vândute la Casa 1, Casa 2 și Casa 3, de luni până vineri; coloana și rândurile pentru formule sunt goale.", "model": ["fise/Model_E05_Bilete.xlsx"], "fisier": "E05_Excel_Nume_Prenume.xlsx", "subiect": "E05 – Excel – Nume Prenume", "predare_obl": false, "pe_scurt": "Ai într-un fișier Excel <b>biletele vândute la 3 case de bilete</b>, de luni până vineri (cifre inventate). Afli cu formule <b>totalul pe zi</b>, <b>totalul pe săptămână</b>, <b>media pe zi</b>, <b>minimul</b> și <b>maximul</b>. Apoi răspunzi la 3 întrebări ale șefei, citind rezultatele. Miezul: <b>cam 35 de minute</b>.", "recap": ["Funcțiile din aceeași familie se scriu la fel: <code>=SUM(...)</code> adună, <code>=AVERAGE(...)</code> face media, <code>=MIN(...)</code> dă cea mai mică valoare, <code>=MAX(...)</code> pe cea mai mare.", "Scrii formula o singură dată, apoi <b>tragi de pătrățelul</b> din colțul din dreapta jos al celulei (mânerul de umplere). Adresele se schimbă singure: <code>B4:D4</code> devine <code>B5:D5</code>.", "Dacă Excelul tău e în română și nu recunoaște numele, folosește săgeata de lângă butonul <b>Σ</b> (Însumare automată): acolo sunt <b>Medie</b>, <b>Min</b>, <b>Max</b>."], "text_dat": "", "cerinte": [{"titlu": "Totaluri și medii cu SUM și AVERAGE", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, deschide-l, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E05_Excel_Nume_Prenume.xlsx</code> (ghidul <b>G3</b>).", "<b>Totalul pe zi:</b> în <code>E4</code> scrie <code>=SUM(B4:D4)</code> și <code>Enter</code>. Click din nou pe <code>E4</code>, apucă pătrățelul din colțul din dreapta jos și trage-l până la <code>E8</code>.", "<b>Totalul pe săptămână:</b> în <code>B9</code> scrie <code>=SUM(B4:B8)</code>. Trage pătrățelul spre dreapta, până la <code>E9</code>.", "<b>Media pe zi:</b> în <code>B10</code> scrie <code>=AVERAGE(B4:B8)</code> și trage spre dreapta până la <code>E10</code>.", "Verifică: în <code>E9</code> trebuie să-ți iasă <b>1872</b>. Dacă nu, dă click pe celule și citește formulele în bara de sus."], "ghiduri": ["G3"]}, {"titlu": "Minimul, maximul și cele 3 întrebări", "minute": 15, "pasi": ["<b>Minimul:</b> în <code>B11</code> scrie <code>=MIN(B4:B8)</code>. <b>Maximul:</b> în <code>B12</code> scrie <code>=MAX(B4:B8)</code>. Trage-le pe amândouă spre dreapta, până la coloana E.", "Selectează rândul cu mediile (<code>B10:E10</code>) → click dreapta → <b>Formatare celule</b> → <b>Număr</b> → <b>2 zecimale</b>.", "<b>Testul:</b> schimbă biletele de vineri la Casa 1 (<code>B8</code>) în <code>100</code>. Se schimbă singure totalurile, media, minimul și maximul? Apasă <code>Ctrl</code> + <code>Z</code> ca să pui cifra la loc.", "Răspunde la cele 3 întrebări din fișier (sub tabel), citind rezultatele: <b>ce casă a vândut cel mai mult</b>, <b>în ce zi s-au vândut cele mai puține bilete</b>, <b>câte bilete s-au vândut în medie pe zi, la toate casele</b>. Salvează."], "ghiduri": []}], "in_plus": {"titlu": "Colorează zilele aglomerate", "pasi": ["Selectează <code>E4:E8</code> → <b>Pornire</b> → <b>Formatare condiționată</b> (Conditional Formatting) → <b>Reguli evidențiere celule</b> → <b>Mai mare decât</b> (Greater Than).", "Scrie <code>374,4</code> (media) și alege o culoare. Ce zi a ieșit colorată?", "Selectează <code>A3:D8</code> → <b>Inserare</b> → <b>Diagramă cu coloane</b> (Column). Titlul: „Bilete vândute pe zile”."]}, "verifica": ["Coloana E are totalul pe fiecare zi, cu <code>=SUM</code>, nu tastat.", "Rândul 9 are totalurile pe săptămână; în <code>E9</code> e <b>1872</b>.", "Rândurile 10–12 au media (cu 2 zecimale), minimul și maximul, cu formule.", "Ai făcut testul cu <code>B8</code> și ai pus cifra la loc.", "Ai răspuns la cele 3 întrebări din fișier."], "rez": {"intro": "Cifrele din fișierul de pornire sunt aceleași pentru toți, deci rezultatele trebuie să-ți iasă <b>exact</b> ca mai jos. Fișierul rezolvat e și pe site: <code>Model_E05_Bilete.xlsx</code>, cu toate formulele.", "parti": [{"titlu": "Tabelul rezolvat", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ziua</th><th scope='col'>Casa 1</th><th scope='col'>Casa 2</th><th scope='col'>Casa 3</th><th scope='col'>Total pe zi</th></tr></thead><tbody><tr><td>Luni</td><td>142</td><td>118</td><td>96</td><td>356</td></tr><tr><td>Marți</td><td>128</td><td>105</td><td>88</td><td>321</td></tr><tr><td>Miercuri</td><td>135</td><td>121</td><td>92</td><td>348</td></tr><tr><td>Joi</td><td>150</td><td>112</td><td>101</td><td>363</td></tr><tr><td>Vineri</td><td>187</td><td>164</td><td>133</td><td>484</td></tr><tr><td>Total săptămână</td><td>742</td><td>620</td><td>510</td><td>1872</td></tr><tr><td>Media pe zi</td><td>148,40</td><td>124,00</td><td>102,00</td><td>374,40</td></tr><tr><td>Minimul</td><td>128</td><td>105</td><td>88</td><td>321</td></tr><tr><td>Maximul</td><td>187</td><td>164</td><td>133</td><td>484</td></tr></tbody></table></div><p><b>Formulele:</b> <code>E4</code> <code>=SUM(B4:D4)</code>, trasă până la <code>E8</code> · <code>B9</code> <code>=SUM(B4:B8)</code> · <code>B10</code> <code>=AVERAGE(B4:B8)</code> · <code>B11</code> <code>=MIN(B4:B8)</code> · <code>B12</code> <code>=MAX(B4:B8)</code>, toate trase spre dreapta până la coloana E.</p>"}, {"titlu": "Cele 3 întrebări", "html": "<p>1) <b>Casa 1</b> a vândut cel mai mult: <b>742</b> de bilete (rândul 9).</p><p>2) Cele mai puține bilete s-au vândut <b>marți</b>: <b>321</b> (minimul din coloana E).</p><p>3) În medie, la toate casele: <b>374,40</b> bilete pe zi (<code>E10</code>).</p><p><b>Pas în plus:</b> colorată iese doar <b>vinerea</b> (484, singura peste medie). Vinerea e ziua în care ar trebui deschise toate casele.</p><div class='cadru'>Dacă la tine <code>E9</code> dă alt număr: probabil ai tras formula și peste rândul cu totaluri sau ai scris un interval greșit (de exemplu <code>B4:B9</code>, care adună și totalul). Click pe celulă și citește formula.</div>"}]}, "glume": ["MAX arată vinerea. Orice casier de la CFR știa asta și fără Excel. Dar acum avem și dovada."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Totaluri și medii cu SUM și AVERAGE", 20], ["Cerința 2 – Minimul, maximul și cele 3 întrebări", 15], ["Pas în plus – Colorează zilele aglomerate", 55], ["Întrebări și discuție", 15]]}, {"cod": "E06", "titlu": "Mesaj jignitor într-un grup online: ce faci și cum răspunzi", "statut": "obl", "nota": "N1", "ore": [9, 13, 15], "suport": "1.3, pg. 18-20; secț. 2", "org": "Fișa evaluare – Nota 1, Act. 3", "vechi": "—", "zi": 3, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-06", "sg2": "2026-10-29", "teorie": [{"zi": 3, "ora": 9, "titlu": "Comunicare digitală · e-mail"}, {"zi": 4, "ora": 13, "titlu": "Comunicarea digitală la locul de muncă"}, {"zi": 4, "ora": 15, "titlu": "Egalitate de șanse și nediscriminare"}], "gata": true, "fisa": "fise/Fisa_E06_Mesaj_jignitor.docx", "rez_doc": "fise/Rezolvare_E06_Mesaj_jignitor.docx", "pornire_var": [], "pornire": "fise/E06_Raspuns_PORNIRE.docx", "pornire_desc": "Cele 3 scenarii și foaia de răspuns: tabelul cu pașii tăi, locul pentru mesajul din grup, mesajul către administrator, „de ce așa” și sursa.", "model": [], "fisier": "E06_Raspuns_Nume_Prenume.docx", "subiect": "E06 – Mesaj jignitor – Nume Prenume", "predare_obl": true, "pe_scurt": "<b>Exercițiul se notează (Nota 1, împreună cu E03 și E04).</b> Ca în fișa de evaluare: <b>primești un mesaj jignitor într-un grup online. Ce faci? Cum răspunzi?</b> Primești un scenariu după prima literă a numelui de familie (A, B sau C). Faci un document Word cu <b>pașii tăi</b> și <b>răspunsul tău</b>: un mesaj scurt în grup și unul în privat, către administrator. Răspunsul e scris de tine, deci lucrarea ta nu seamănă cu a nimănui. Miezul: <b>cam 45 de minute</b>. <b>Subgrupa 1</b> îl face în <b>ziua 16</b> (recuperare, intră în Nota 1).", "recap": ["<b>Neticheta</b> (suport 1.3, pg. 20): răspunzi politicos, chiar și când e tensiune; fără MAJUSCULE; nu redistribui ce nu e al tău. Răspunsul calm îl ajută pe cel jignit și îl lasă fără public pe cel care jignește.", "Ironia la adresa felului în care scrie cineva, a vârstei, a originii sau a meseriei lui e <b>discriminare</b> (Ora 15 și fișa de lucru a organizatorului despre nediscriminare). Cine tace și pune emoticoane care râd o întărește.", "Ordinea care funcționează: <b>nu răspunzi la nervi</b> → <b>păstrezi dovada</b> (captură cu data) → <b>răspunzi o dată, calm</b> → <b>anunți administratorul</b> → dacă se repetă, <b>raportezi</b> și <b>blochezi</b>. La amenințări: <b>112</b>."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Scenariul</th><th scope='col'>Numele de familie începe cu</th><th scope='col'>Ce s-a întâmplat</th></tr></thead><tbody><tr><td>A</td><td>A – H</td><td><b>Grupul de WhatsApp al turei.</b> Colega nouă, Ioana, întreabă unde găsește formularul de schimb de tură și face câteva greșeli de scriere. Colegul Dan răspunde: „Ha ha, întâi învață să scrii, apoi te apuci de formulare 😂. De unde v-au mai adus și pe voi?” Doi colegi pun emoticoane care râd. Administratorul grupului e șefa de tură, Ana Rusu.</td></tr><tr><td>B</td><td>I – P</td><td><b>Grupul de Facebook al blocului.</b> Ai scris politicos că liftul nu merge de 3 zile și ai întrebat dacă a anunțat cineva administratorul. Un vecin îți răspunde public: „Iar te plângi? Urcă pe scări, poate mai slăbești. Oameni ca tine doar fac gălăgie.” Grupul are un administrator, domnul Matei.</td></tr><tr><td>C</td><td>Q – Z</td><td><b>Grupul de WhatsApp al părinților din clasă.</b> O mamă, doamna Elena, care lucrează în ture de noapte, întreabă a doua oară ce teme au copiii. Un tată scrie: „Cine nu e în stare să citească grupul n-are ce căuta aici. Scoateți-o, că ne umple de întrebări proaste.” Administratoarea grupului e învățătoarea, doamna Lungu.</td></tr></tbody></table></div><p>Literele cu diacritice se citesc fără ele: Ă și Â ca A, Î ca I, Ș ca S, Ț ca T. Dacă formatorul îți dă alt scenariu, lucrezi pe acela.</p>", "cerinte": [{"titlu": "Ce faci: pașii tăi", "minute": 20, "pasi": ["Află-ți <b>scenariul</b> din tabelul „<b>Textul pe care îl folosești</b>”, după prima literă a numelui de familie.", "Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E06_Raspuns_Nume_Prenume.docx</code> (ghidul <b>G3</b>). Scrie sus numele și litera scenariului.", "Citește scenariul tău de două ori. Întreabă-te: <b>pe cine</b> jignește mesajul? <b>Ce</b> e jignitor în el? Mai sunt și alții care <b>râd</b> sau tac?", "Completează tabelul „<b>Ce fac</b>” cu <b>5 pași, în ordine</b>, iar la fiecare scrie și <b>de ce</b>. Folosește ordinea din „Ce ai învățat la teorie”, adaptată la scenariul tău.", "Scrie sub tabel <b>cel puțin 2 lucruri pe care nu le faci</b> (de exemplu: nu răspund cu o jignire; nu trimit captura în alte grupuri)."], "ghiduri": ["G3"]}, {"titlu": "Cum răspunzi: mesajul din grup și cel către administrator", "minute": 25, "pasi": ["Scrie <b>mesajul tău în grup</b>, 2–4 rânduri: calm, fără să repeți jignirea, fără MAJUSCULE. La A și C sprijini persoana jignită și răspunzi la întrebarea ei; la B rămâi la subiect (liftul).", "Scrie <b>mesajul în privat către administrator</b> (3–5 rânduri): adresare; ce s-a întâmplat, când și în ce grup; că ai o captură; <b>ce îi ceri</b> (să amintească regulile grupului, să șteargă mesajul); încheiere.", "La „<b>De ce am răspuns așa</b>” scrie 2–3 propoziții: ce ai urmărit și ce regulă de netichetă sau de nediscriminare ai respectat.", "La <b>Sursa</b> scrie de unde ai luat regulile, de exemplu: „Suport de curs Competențe digitale, 1.3 Etichetă digitală, pg. 20; secțiunea 2, pg. 25–32”.", "Verifică ortografia cu <code>F7</code>, salvează (<code>Ctrl</code> + <code>S</code>) și trimite fișierul (ghidul <b>G6</b>)."], "ghiduri": ["G6"]}], "in_plus": {"titlu": "Unde e butonul „Raportează” la tine în telefon", "pasi": ["<b>WhatsApp:</b> ține degetul apăsat pe un mesaj → <b>⋮</b> (sau <b>Mai multe</b>) → caută <b>Raportează</b> (Report). Nu apăsa: doar află unde e.", "Tot în WhatsApp: <b>Setări</b> → <b>Confidențialitate</b> → <b>Grupuri</b>. Aici alegi <b>cine te poate adăuga</b> în grupuri.", "<b>Facebook:</b> la un comentariu, apasă <b>…</b> → vezi opțiunea <b>Raportează comentariul</b> (sau „Găsește ajutor sau raportează”).", "Fă o captură cu unul dintre aceste ecrane, fără nume de persoane (ghidul <b>G1</b>), și lipește-o la finalul documentului (ghidul <b>G2</b>)."]}, "verifica": ["Ai scris litera scenariului tău, iar răspunsul se potrivește cu el.", "Tabelul are 5 pași în ordine, fiecare cu „de ce”, și ai scris cel puțin 2 lucruri pe care nu le faci.", "Mesajul din grup e calm, scurt, nu repetă jignirea și nu jignește înapoi.", "Mesajul către administrator spune ce, când, unde, că ai dovada și ce ceri.", "Ai explicat de ce ai răspuns așa și ai trecut sursa.", "Ai verificat ortografia (<code>F7</code>) și ai trimis fișierul cu subiectul corect."], "rez": {"intro": "Răspunsul fiecăruia e diferit, dar <b>pașii</b> sunt aceiași. Mai jos ai pașii-model și <b>câte un răspuns-model pentru fiecare scenariu</b>. La final, cum se notează după baremul oficial.", "parti": [{"titlu": "Ce faci: pașii-model (pentru toate scenariile)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Pasul</th><th scope='col'>Ce fac</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>1</td><td>Nu răspund pe loc. Aștept câteva minute.</td><td>Un răspuns la nervi face din jignire o ceartă cu public.</td></tr><tr><td>2</td><td>Fac o captură cu mesajul, numele grupului, data și ora.</td><td>Dacă mesajul e șters, dovada rămâne. Administratorul are nevoie de ea.</td></tr><tr><td>3</td><td>Răspund o singură dată, calm, în grup.</td><td>Persoana jignită vede că nu e singură; cel care jignește rămâne fără aplauze.</td></tr><tr><td>4</td><td>Îi scriu în privat administratorului, cu captura.</td><td>El poate aminti regulile, șterge mesajul sau scoate pe cineva din grup.</td></tr><tr><td>5</td><td>Dacă se repetă: raportez mesajul în aplicație, blochez persoana sau ies din grup. La amenințări sun la 112.</td><td>Aplicațiile au reguli împotriva hărțuirii; amenințarea e treaba Poliției.</td></tr></tbody></table></div><p><b>Ce NU faci:</b> nu jignești înapoi; nu repeți jignirea în răspuns; nu trimiți captura în alte grupuri „să vadă toată lumea”; nu ștergi conversația (pierzi dovada); nu pui și tu un emoticon care râde.</p>"}, {"titlu": "Scenariul A – Grupul turei (Ioana și Dan)", "html": "<div class='cadru'>În grup: „Ioana, formularul de schimb de tură e în dosarul comun, la Formulare, sau îl iei de la casa 1. Bine ai venit în echipă! Dan, aici ne ajutăm între noi. Să păstrăm grupul pentru treabă, fără ironii.”</div><div class='cadru'>Către Ana Rusu, în privat: „Bună ziua, doamna Rusu, azi, la 14:20, în grupul turei, Dan a ironizat-o pe colega nouă, Ioana, pentru felul în care scrie, iar alți doi colegi au râs. Am păstrat o captură. Vă rog să le amintiți colegilor regulile grupului și, dacă considerați, să ștergeți mesajul. Mulțumesc! Maria”</div><p><b>Ce e jignitor:</b> ironia despre felul în care scrie cineva și „de unde v-au mai adus” (o etichetă pusă unui grup de oameni). E exact cazul din fișa de lucru a organizatorului despre nediscriminare (partea IV).</p>"}, {"titlu": "Scenariul B – Grupul blocului (jignirea e la tine)", "html": "<div class='cadru'>În grup: „Revin la subiect: liftul nu merge din luni. L-am sunat azi pe administratorul blocului și vine joi cu firma de întreținere. Vă rog să păstrăm discuția la subiect și fără remarci personale.”</div><div class='cadru'>Către domnul Matei, administratorul grupului: „Bună ziua, domnule Matei, azi, la 19:05, sub postarea mea despre lift, un membru al grupului mi-a adresat remarci jignitoare despre aspectul meu. Am o captură. Vă rog să ștergeți comentariul și să amintiți regulile grupului. Vă mulțumesc! Maria Popescu, ap. 12”</div><p><b>De ce nu răspunzi la jignire:</b> orice replică despre persoana lui mută discuția de la lift la ceartă. Rămâi la subiect, iar jignirea o rezolvă administratorul. Dacă se repetă: <b>Raportează comentariul</b> și <b>Blochează</b>.</p>"}, {"titlu": "Scenariul C – Grupul părinților (doamna Elena)", "html": "<div class='cadru'>În grup: „Doamna Elena, temele pentru mâine sunt la matematică exercițiile 3 și 4 de la pagina 21 și lectura de la pagina 15. Cu toții mai pierdem mesaje, mai ales după o tură de noapte. Grupul e pentru întrebări ca acestea.”</div><div class='cadru'>Către doamna Lungu, în privat: „Bună seara, doamna Lungu, în grupul clasei, azi la 21:40, un părinte a cerut să fie scoasă din grup o mamă care a întrebat de teme, cu cuvinte jignitoare. Am o captură. V-aș ruga să amintiți regulile grupului. Poate ar ajuta un mesaj fixat (pin) cu temele zilei. Mulțumesc! Maria Popescu”</div><p><b>Ce e jignitor:</b> „întrebări proaste” și cererea de a o <b>exclude</b> din grup. Excluderea cuiva dintr-un grup e una dintre formele de discriminare din fișa organizatorului (partea I).</p>"}, {"titlu": "De ce așa (model)", "html": "<p>„Am răspuns calm, o singură dată, ca persoana jignită să vadă că nu e singură, fără să transform grupul într-o ceartă. Jignirea am lăsat-o administratorului, care are puterea să o oprească, și am păstrat dovada. Am respectat regula de netichetă: răspunzi politicos, chiar și în situații tensionate.”</p><p><b>Sursa:</b> Suport de curs Competențe digitale, 1.3 Etichetă digitală (Netiquette), pg. 20; secțiunea 2, Egalitate de șanse și nediscriminare, pg. 25–32.</p>"}, {"titlu": "Cum se notează (baremul oficial) și ce urmărim", "html": "<div class='tw'><table><thead><tr><th scope='col'>Criteriu</th><th scope='col'>Puncte</th><th scope='col'>Ce urmărim la E06</th></tr></thead><tbody><tr><td>Planificarea conținutului</td><td>10</td><td>Documentul are toate părțile, în ordine: pașii, ce nu faci, cele două mesaje, de ce, sursa.</td></tr><tr><td>Calitatea informației</td><td>15</td><td>Pașii sunt corecți și în ordinea bună; ai recunoscut ce e jignitor în scenariul tău.</td></tr><tr><td>Creativitate și design</td><td>10</td><td>Documentul e aerisit și ușor de citit; tabelul e completat îngrijit.</td></tr><tr><td>Utilizarea instrumentelor digitale</td><td>10</td><td>Ai lucrat corect în Word (tabel, salvare cu numele cerut, <code>F7</code>); la Pas în plus, captura e lipită.</td></tr><tr><td>Respectarea drepturilor de autor</td><td>10</td><td>Sursa e trecută; în capturi nu se văd nume sau numere reale.</td></tr><tr><td>Adaptarea la publicul țintă</td><td>15</td><td>Mesajul din grup e potrivit grupului (colegi, vecini, părinți), iar cel către administrator e politicos și precis.</td></tr><tr><td>Corectitudine lingvistică</td><td>10</td><td>Diacritice, ortografie, fără MAJUSCULE.</td></tr><tr><td>Finalizare și prezentare</td><td>10</td><td>Fișierul are numele cerut și e trimis cu subiectul corect.</td></tr><tr><td>Din oficiu</td><td>10</td><td></td></tr></tbody></table></div><div class='cadru'>Greșeli care costă puncte: răspuns cu o jignire „mai elegantă”; jignirea repetată în răspuns; lipsa mesajului către administrator; pași fără „de ce”; „le-aș spune ce cred despre ei” în loc de un mesaj scris; lipsa sursei.</div>"}]}, "glume": ["Un răspuns calm într-un grup aprins e ca frâna de mână: nu e spectaculos, dar oprește trenul."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Ce faci: pașii tăi", 20], ["Cerința 2 – Cum răspunzi: mesajul din grup și cel către administrator", 25], ["Pas în plus – Unde e butonul „Raportează” la tine în telefon", 45], ["Întrebări și discuție", 15]]}, {"cod": "E07", "titlu": "Comunicare la job: mesajul complet și canalul potrivit", "statut": "rec", "nota": null, "ore": [13], "suport": "secț. 2, pg. 25-32", "org": "Studii comunicare și etichetă", "vechi": "T06", "zi": 4, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-07", "sg2": "2026-10-30", "teorie": [{"zi": 4, "ora": 13, "titlu": "Comunicarea digitală la locul de muncă"}], "gata": true, "fisa": "fise/Fisa_E07_Comunicare.docx", "rez_doc": "fise/Rezolvare_E07_Comunicare.docx", "pornire_var": [], "pornire": "fise/E07_Comunicare_PORNIRE.docx", "pornire_desc": "Cele 4 mesaje vagi, detaliile pe care le știi tu, cele 5 situații și tabelele de completat.", "model": [], "fisier": "E07_Comunicare_Nume_Prenume.docx", "subiect": "E07 – Comunicare – Nume Prenume", "predare_obl": false, "pe_scurt": "Patru colegi au trimis mesaje din care nu înțelegi nimic: „Casa 2 nu merge.”, „Trimite-mi aia.”. Tu le <b>rescrii complete</b>, cu ora, locul și ce se cere. Apoi alegi <b>canalul potrivit</b> pentru 5 situații (apel, e-mail, grup, față în față) și îndulcești un mesaj scris prea sec. Miezul: <b>cam 35 de minute</b>.", "recap": ["Un mesaj complet răspunde din prima la <b>4 întrebări</b>: <b>ce</b> s-a întâmplat, <b>cât de mare</b> e problema (ora, durata, locul), <b>de ce</b> (dacă știi) și <b>ce se cere</b> celui care citește (studiul de caz „Trenul întârzie”).", "<b>Canalul potrivit</b> (suport, pg. 26–27): urgențele prin <b>apel</b>, nu prin e-mail citit peste o oră; ce trebuie să rămână scris, prin <b>e-mail</b>; grupurile separate pe scopuri, cu etichete <b>URGENT</b> / <b>INFORMARE</b>; ce privește un singur om, <b>în privat</b>.", "Tonul: „Te rog”, „Mulțumesc” și o propoziție întreagă schimbă tot. „Dă-mi un răspuns rapid!” sună ostil; „Te rog să-mi confirmi până la 15:00” cere același lucru."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Mesajul primit</th></tr></thead><tbody><tr><td>1</td><td>„Casa 2 nu merge.”</td></tr><tr><td>2</td><td>„Mâine schimbăm ceva la program.”</td></tr><tr><td>3</td><td>„Trimite-mi aia.”</td></tr><tr><td>4</td><td>„S-a pierdut ceva în sală.”</td></tr></tbody></table></div><p>Ce știi tu și nu știu colegii: casa 2 e închisă de la 14:10, pentru că s-a blocat imprimanta de bilete; IT-ul vine până la 16:00. De mâine, 3 noiembrie, casa 3 se deschide la 6:00 în loc de 7:00, pentru trenul de 6:20 spre București. Lui Mihai îi ceri situația vânzărilor de ieri (fișierul Excel), până la 12:00. La 9:30 s-a găsit în sala de așteptare un rucsac negru, fără nume; l-ai predat la biroul de obiecte găsite.</p><div class='tw'><table><thead><tr><th scope='col'>Situația</th><th scope='col'>Ce s-a întâmplat</th></tr></thead><tbody><tr><td>A</td><td>Un călător s-a prăbușit în sala de așteptare și nu răspunde.</td></tr><tr><td>B</td><td>Programul casei de bilete de sărbători, pentru toți colegii din stație.</td></tr><tr><td>C</td><td>Un coleg a greșit restul unui călător, iar tu vrei să-i spui.</td></tr><tr><td>D</td><td>Aplicația de vânzare s-a oprit chiar acum, la toate casele.</td></tr><tr><td>E</td><td>Ceri șefei o zi liberă luna viitoare.</td></tr></tbody></table></div>", "cerinte": [{"titlu": "Rescrie cele 4 mesaje complete", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E07_Comunicare_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Citește paragraful cu <b>ce știi tu și nu știu colegii</b>. De acolo iei orele, locurile și numele.", "La fiecare mesaj scrie în coloana „<b>Ce lipsește</b>” care dintre cele 4 întrebări rămân fără răspuns: ce? cât? de ce? ce se cere?", "Rescrie mesajul <b>complet</b>, în 1–3 propoziții, cu cifre (ora, data, numărul casei) și cu ce trebuie să facă cel care citește.", "Citește-l ca și cum ai fi colegul care abia a intrat în tură: mai ai vreo întrebare? Dacă da, mesajul nu e gata."], "ghiduri": ["G3"]}, {"titlu": "Alege canalul și îndreaptă tonul", "minute": 15, "pasi": ["În tabelul 2 alege <b>canalul</b> pentru fiecare dintre cele 5 situații și scrie <b>de ce</b>, într-o propoziție. Unele situații au nevoie de <b>două</b> canale.", "La punctul 3 rescrie mesajul cu „<b>???</b>” și „<b>!!!</b>”: fără majuscule și fără semne în șir, fără acuzații, cu o rugăminte clară. 2–3 propoziții.", "Verifică ortografia cu <code>F7</code> și salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Grupul tău de la serviciu, pe scopuri", "pasi": ["Gândește-te la un grup aglomerat pe care îl folosești (WhatsApp, Teams). Ca în studiul de caz cu 200 de mesaje pe zi: cum l-ai împărți în <b>2–3 grupuri</b>, pe scopuri?", "Scrie la finalul documentului numele grupurilor și <b>o regulă</b> pentru fiecare (de exemplu: „URGENȚE – doar probleme care nu pot aștepta 10 minute; fără poze și glume”)."]}, "verifica": ["Fiecare mesaj rescris spune ce, cât (oră, loc), de ce și ce se cere.", "Ai folosit detaliile date: 14:10, 16:00, 3 noiembrie, 6:00, 12:00, 9:30.", "La situația A ai ales <b>apelul</b> (112), nu un mesaj; la D, apelul la IT <b>și</b> grupul URGENT.", "Mesajul cu „???” și „!!!” are acum ton calm și o rugăminte clară."], "rez": {"intro": "Mai jos ai mesajele rescrise, canalele și tonul îndreptat. Formulările tale pot fi altele: contează ca mesajele să răspundă la <b>aceleași 4 întrebări</b> și canalele să fie aceleași.", "parti": [{"titlu": "Cerința 1 – Mesajele complete", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Ce lipsea</th><th scope='col'>Mesajul complet</th></tr></thead><tbody><tr><td>1</td><td>de când, de ce, până când, ce fac colegii</td><td>„Casa 2 e închisă de la 14:10: s-a blocat imprimanta de bilete. IT-ul vine până la 16:00. Vă rog să trimiteți călătorii la casele 1 și 3.”</td></tr><tr><td>2</td><td>ce se schimbă, de când, de ce, cine e afectat</td><td>„De mâine, 3 noiembrie, casa 3 se deschide la 6:00 în loc de 7:00, pentru trenul de 6:20 spre București. Colegii din tura de dimineață de la casa 3 vin la 5:50.”</td></tr><tr><td>3</td><td>cui, ce anume, până când, cum</td><td>„Mihai, te rog să-mi trimiți pe e-mail, până la 12:00, situația vânzărilor de ieri (fișierul Excel). O pun în raportul lunar. Mulțumesc!”</td></tr><tr><td>4</td><td>ce, unde, când, ce s-a făcut, ce se cere</td><td>„La 9:30 s-a găsit în sala de așteptare un rucsac negru, fără nume. L-am predat la biroul de obiecte găsite. Dacă întreabă cineva de el, îl trimiteți acolo.”</td></tr></tbody></table></div>"}, {"titlu": "Cerința 2 – Canalul potrivit", "html": "<div class='tw'><table><thead><tr><th scope='col'>Situația</th><th scope='col'>Canalul</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>A</td><td>Apel la <b>112</b>, apoi apel la șeful de tură</td><td>E o urgență medicală: fiecare minut contează. Un mesaj poate fi citit prea târziu.</td></tr><tr><td>B</td><td><b>E-mail</b> + grupul <b>INFORMARE</b></td><td>Programul trebuie să rămână scris, să-l găsească oricine; grupul doar anunță că a venit.</td></tr><tr><td>C</td><td><b>Față în față</b> sau mesaj <b>privat</b></td><td>Privește un singur om. Spus în grup, devine o umilire publică.</td></tr><tr><td>D</td><td><b>Apel la IT</b> + grupul <b>URGENT</b></td><td>IT-ul trebuie să afle imediat; colegii trebuie să știe ce le spun călătorilor.</td></tr><tr><td>E</td><td><b>E-mail</b> către șefă</td><td>O cerere care trebuie aprobată lasă urme scrise (vezi și E04).</td></tr></tbody></table></div>"}, {"titlu": "Același mesaj, alt ton (model)", "html": "<div class='cadru'>„Bună ziua tuturor! Aseară casa 1 a rămas deschisă după închidere. Vă rog ca ultimul din tură să verifice ușa și seiful înainte să plece. Mulțumesc!”</div><p><b>Ce s-a schimbat:</b> fără „???” și „!!!”, fără acuzație („cine a lăsat iar”), cu ce s-a întâmplat și cu o rugăminte pe care o poate urma oricine.</p>"}]}, "glume": ["„Trimite-mi aia” e ca „ne vedem acolo”: sună clar doar pentru cel care a scris."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Rescrie cele 4 mesaje complete", 20], ["Cerința 2 – Alege canalul și îndreaptă tonul", 15], ["Pas în plus – Grupul tău de la serviciu, pe scopuri", 55], ["Întrebări și discuție", 15]]}, {"cod": "E08", "titlu": "Nediscriminare: material digital (afiș / 3 diapozitive / postare)", "statut": "obl", "nota": "N2", "ore": [15], "suport": "secț. 2, pg. 25-32", "org": "Fișa evaluare – Nota 2", "vechi": "T07", "zi": 4, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-07", "sg2": "2026-10-30", "teorie": [{"zi": 4, "ora": 15, "titlu": "Egalitate de șanse și nediscriminare"}], "gata": true, "fisa": "fise/Fisa_E08_Nediscriminare.docx", "rez_doc": "fise/Rezolvare_E08_Nediscriminare.docx", "pornire_var": [], "pornire": "fise/E08_Plan_PORNIRE.docx", "pornire_desc": "Planul materialului tău, pe o pagină: subiectul, scopul, publicul, formatul, titlul, cele 3 mesaje-cheie, exemplul, îndemnul, imaginea și sursele.", "model": ["fise/Model_E08_Afis.docx"], "fisier": "E08_Nediscriminare_Nume_Prenume.pdf", "subiect": "E08 – Nediscriminare – Nume Prenume", "predare_obl": true, "pe_scurt": "<b>Exercițiul se notează (Nota 2).</b> Ca în fișa de evaluare: creezi un <b>material digital despre nediscriminarea în mediile digitale</b>, la alegere: <b>afiș</b>, <b>prezentare de 3 diapozitive</b> sau <b>postare</b>. Alegi subiectul din listă și scopul (<b>informare, promovare sau instruire</b>), pentru colegii tăi. Întâi îți faci un plan scurt, apoi materialul, pe care îl salvezi ca PDF. Materialul e al tău, deci nu seamănă cu al nimănui. Miezul: <b>cam 45 de minute</b>.", "recap": ["<b>Discriminarea</b> înseamnă că o persoană e tratată defavorabil sau exclusă din cauza genului, vârstei, originii, dizabilității sau a altor caracteristici. <b>Directă</b>: pe față („căutăm un băiat tânăr”). <b>Indirectă</b>: o regulă care pare neutră, dar dezavantajează pe unii (anunțul pus doar pe WhatsApp).", "<b>Accesibilitatea</b> (suport, pg. 30): text lizibil, <b>contrast</b> bun, litere mari, <b>text alternativ</b> la imagini, subtitrări. <b>Incluziunea</b>: fiecare are acces și poate participa, fără rușine și fără teamă că e judecat.", "Un material bun are: <b>titlu</b> care spune tot, <b>3 mesaje-cheie</b> scurte, <b>un exemplu</b> „așa da / așa nu”, <b>un îndemn</b> (ce face cititorul de mâine) și <b>sursa</b>. În România: Legea 202/2002 (egalitatea de șanse între femei și bărbați), OG 137/2000 (combaterea discriminării), CNCD."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Subiectul (alegi unul)</th></tr></thead><tbody><tr><td>1</td><td>Limbaj care îi include pe toți, în grupurile de lucru</td></tr><tr><td>2</td><td>Documente pe care le poate citi oricine (text alternativ, contrast, titluri)</td></tr><tr><td>3</td><td>Femei și bărbați: aceleași șanse la instruire și la promovare</td></tr><tr><td>4</td><td>Vârsta nu e un criteriu: cum îi ajutăm pe colegii mai puțin obișnuiți cu tehnologia</td></tr><tr><td>5</td><td>Ce faci când vezi o glumă discriminatorie într-un grup online</td></tr><tr><td>6</td><td>Anunțuri de angajare fără discriminare</td></tr><tr><td>7</td><td>Călătorii cu dizabilități și serviciile digitale (bilete online, informare)</td></tr></tbody></table></div><div class='tw'><table><thead><tr><th scope='col'>Formatul</th><th scope='col'>Cum arată</th><th scope='col'>Cum îl predai</th></tr></thead><tbody><tr><td>Afiș</td><td>o pagină în Word (orientare tip Portret), litere de cel puțin 24 pt la text și 40 pt la titlu</td><td>PDF (ghidul <b>G4</b>)</td></tr><tr><td>Prezentare</td><td>3 diapozitive în PowerPoint: titlu + 2 diapozitive de conținut, litere de cel puțin 28 pt</td><td>PDF sau .pptx</td></tr><tr><td>Postare</td><td>o postare pentru o pagină sau un grup: cel mult 120 de cuvinte, o imagine, 2–3 etichete (#)</td><td>PDF (o scrii în Word, cu imaginea)</td></tr></tbody></table></div>", "cerinte": [{"titlu": "Planul materialului", "minute": 15, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E08_Plan_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Alege <b>subiectul</b> și <b>formatul</b> din tabelele „<b>Textul pe care îl folosești</b>”. Hotărăște <b>scopul</b>: vrei să-i <b>informezi</b> pe colegi, să <b>promovezi</b> un comportament sau să-i <b>înveți</b> să facă ceva?", "Scrie <b>titlul</b> și <b>3 mesaje-cheie</b>: propoziții scurte, de cel mult 12 cuvinte fiecare, pe înțelesul oricui.", "Scrie <b>un exemplu</b> concret „Așa nu → Așa da” (de exemplu un mesaj sau un anunț rescris) și <b>îndemnul</b>: ce face cititorul de mâine.", "Alege <b>imaginea</b> (o pictogramă din Word sau PowerPoint: <b>Inserare</b> → <b>Pictograme</b>) și scrie-i textul alternativ. Notează <b>sursele</b>: secțiunea 2 din suportul de curs și, dacă vrei, o lege sau un site (cncd.ro)."], "ghiduri": ["G3"]}, {"titlu": "Materialul, verificat și salvat ca PDF", "minute": 30, "pasi": ["Deschide un fișier nou în programul potrivit formatului (Word pentru afiș și postare, PowerPoint pentru diapozitive) și salvează-l ca <code>E08_Nediscriminare_Nume_Prenume</code> (.docx sau .pptx).", "Pune în material ce ai planificat: <b>titlul</b>, <b>cele 3 mesaje</b>, <b>exemplul</b>, <b>îndemnul</b>, <b>imaginea</b>, iar jos, mic, <b>sursele</b> și numele tău.", "Designul: un singur font clar (de exemplu Calibri sau Arial), cel mult 2–3 culori, text închis pe fundal deschis, litere mari (vezi tabelul cu formatele). Mai puțin text = mai bine.", "Click dreapta pe imagine → <b>Vizualizare text alternativ</b> (View Alt Text) și scrie descrierea. Apoi <b>Revizuire</b> → <b>Verificare accesibilitate</b> și repară erorile (ghidul <b>G7</b>).", "Salvează ca <b>PDF</b> (ghidul <b>G4</b>) și deschide PDF-ul să vezi că arată bine. Completează „Verificarea de la final” din plan.", "Trimite <b>PDF-ul</b> și <b>planul</b>, atașate la același e-mail, cu subiectul cerut (ghidurile <b>G5</b> și <b>G6</b>)."], "ghiduri": ["G7", "G4", "G5", "G6"]}], "in_plus": {"titlu": "Testul de 10 secunde", "pasi": ["Arată materialul unui coleg sau unui membru al familiei <b>10 secunde</b>, apoi ascunde-l. Întreabă: „Despre ce era? Ce trebuie să faci?”", "Dacă nu poate răspunde, titlul sau îndemnul nu sunt destul de clare. Scurtează-le și salvează din nou PDF-ul.", "Opțional: fă același material și în alt format (afișul ca postare sau invers)."]}, "verifica": ["Planul are toate cele 12 rânduri completate.", "Materialul e pe subiectul ales, are titlu, 3 mesaje-cheie, un exemplu „așa nu / așa da”, un îndemn și sursele.", "Imaginea are text alternativ, iar Verificarea accesibilității nu arată erori.", "Literele sunt destul de mari, contrastul e bun, folosești cel mult 2–3 culori.", "Ai salvat ca PDF, ai verificat PDF-ul și l-ai trimis împreună cu planul."], "rez": {"intro": "Fiecare material e diferit, deci nu există un singur răspuns. Mai jos ai <b>un plan-model</b>, <b>un afiș-model</b> (și ca fișier: <code>Model_E08_Afis.docx</code>), cum ar arăta același subiect ca 3 diapozitive și ca postare, apoi cum se notează după baremul oficial.", "parti": [{"titlu": "Planul-model", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce hotărăsc</th><th scope='col'>Alegerea mea</th></tr></thead><tbody><tr><td>Subiectul</td><td>1 – Limbaj care îi include pe toți, în grupurile de lucru</td></tr><tr><td>Scopul</td><td>Promovare: vreau ca, de mâine, colegii să scrie altfel în grup</td></tr><tr><td>Publicul țintă</td><td>Colegii de la casele de bilete și din stație</td></tr><tr><td>Formatul</td><td>Afiș, o pagină, salvat ca PDF</td></tr><tr><td>Titlul</td><td>Scrie așa cum ai vrea să ți se scrie</td></tr><tr><td>Mesajul-cheie 1</td><td>Nu glumim pe seama vârstei, a genului sau a felului în care scrie cineva.</td></tr><tr><td>Mesajul-cheie 2</td><td>Anunțurile importante ajung la toți: grup, e-mail și avizier.</td></tr><tr><td>Mesajul-cheie 3</td><td>Cine întreabă nu deranjează: răspundem cu răbdare.</td></tr><tr><td>Exemplul</td><td>Așa nu: „Băieți, mâine schimbăm tura.” → Așa da: „Dragi colegi, de mâine, 3 noiembrie, tura de dimineață începe la 6:00.”</td></tr><tr><td>Îndemnul</td><td>Înainte de Trimitere, întreabă-te: îl poate citi oricine și nu jignește pe nimeni?</td></tr><tr><td>Imaginea</td><td>Pictograma „grup de oameni”; text alternativ: „Pictogramă: patru oameni diferiți, unul lângă altul”</td></tr><tr><td>Sursele</td><td>Suport de curs Competențe digitale, secțiunea 2, pg. 28–32; OG 137/2000; cncd.ro</td></tr></tbody></table></div>"}, {"titlu": "Afișul-model", "html": "<div class='cadru'>SCRIE AȘA CUM AI VREA SĂ ȚI SE SCRIE (titlu, 44 pt)<br>• Nu glumim pe seama vârstei, a genului sau a felului în care scrie cineva.<br>• Anunțurile importante ajung la toți: grup, e-mail și avizier.<br>• Cine întreabă nu deranjează: răspundem cu răbdare.<br>Așa nu: „Băieți, mâine schimbăm tura.”  →  Așa da: „Dragi colegi, de mâine, 3 noiembrie, tura de dimineață începe la 6:00.”<br>Înainte de Trimitere: îl poate citi oricine și nu jignește pe nimeni?<br>Surse: Suport de curs Competențe digitale, secț. 2; OG 137/2000; cncd.ro · Maria Popescu, casa de bilete</div><p><b>De ce funcționează:</b> titlul spune ideea în 8 cuvinte; trei mesaje, nu zece; un exemplu din viața stației; un îndemn pe care îl poți face mâine; sursele jos; text bleumarin pe fundal alb, o singură culoare de accent.</p>"}, {"titlu": "Același subiect, în alte formate", "html": "<p><b>3 diapozitive:</b> 1) titlul + o pictogramă; 2) cele 3 mesaje-cheie, câte unul pe rând, 32 pt; 3) exemplul „așa nu / așa da” + îndemnul + sursele, jos.</p><div class='cadru'>Postare-model (84 de cuvinte): „Un mesaj în grupul turei ajunge la 20 de colegi. Unii citesc pe telefon, alții pe un ecran mic, unii au abia venit. Trei reguli simple: nu glumim pe seama vârstei, a genului sau a felului în care scrie cineva; anunțurile importante ajung și pe e-mail și la avizier; cine întreabă nu deranjează. Înainte de Trimitere, întreabă-te: îl poate citi oricine și nu jignește pe nimeni? #incluziune #respect #colegi” · Imagine: pictogramă cu un grup de oameni, cu text alternativ · Sursa: Suport de curs, secț. 2.</div>"}, {"titlu": "Cum se notează (baremul oficial) și ce urmărim", "html": "<div class='tw'><table><thead><tr><th scope='col'>Criteriu</th><th scope='col'>Puncte</th><th scope='col'>Ce urmărim la E08</th></tr></thead><tbody><tr><td>Planificarea conținutului</td><td>10</td><td>Planul e complet și materialul îl urmează: titlu, 3 mesaje, exemplu, îndemn, surse; ordinea e logică.</td></tr><tr><td>Calitatea informației</td><td>15</td><td>Informația e corectă (ce e discriminarea, directă/indirectă, accesibilitatea) și pe subiectul ales.</td></tr><tr><td>Creativitate și design</td><td>10</td><td>Aspect îngrijit: un font, 2–3 culori, contrast bun, mult spațiu liber, litere mari.</td></tr><tr><td>Utilizarea instrumentelor digitale</td><td>10</td><td>Programul folosit corect: pictogramă cu text alternativ, Verificare accesibilitate, salvare ca PDF.</td></tr><tr><td>Respectarea drepturilor de autor</td><td>10</td><td>Sursele sunt trecute pe material; imaginile sunt pictogramele din Office sau făcute de tine.</td></tr><tr><td>Adaptarea la publicul țintă</td><td>15</td><td>Pe înțelesul colegilor: propoziții scurte, exemple din stație, ton prietenos, fără „trebuie” la fiecare rând.</td></tr><tr><td>Corectitudine lingvistică</td><td>10</td><td>Diacritice, ortografie, fără greșeli de tipar.</td></tr><tr><td>Finalizare și prezentare</td><td>10</td><td>PDF-ul se deschide, are numele cerut și a fost trimis împreună cu planul.</td></tr><tr><td>Din oficiu</td><td>10</td><td></td></tr></tbody></table></div><div class='cadru'>Greșeli care costă puncte: un text lung copiat din suport, pus pe o pagină; zece mesaje în loc de trei; text gri pe fundal colorat; imagine fără text alternativ; poze luate de pe internet fără sursă; lipsa îndemnului; trimis ca .docx când formatul ales era afiș (PDF).</div>"}]}, "glume": ["Un afiș cu 300 de cuvinte nu e afiș. E un regulament care s-a rătăcit pe perete."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Planul materialului", 15], ["Cerința 2 – Materialul, verificat și salvat ca PDF", 30], ["Pas în plus – Testul de 10 secunde", 45], ["Întrebări și discuție", 15]]}, {"cod": "E09", "titlu": "Egalitate de șanse: fișa de lucru a organizatorului + rescriere incluzivă", "statut": "rec", "nota": null, "ore": [15], "suport": "secț. 2, pg. 25-32", "org": "FIȘA DE LUCRU – Nediscriminare", "vechi": "T07", "zi": 5, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-08", "sg2": "2026-11-02", "teorie": [{"zi": 4, "ora": 15, "titlu": "Egalitate de șanse și nediscriminare"}], "gata": true, "fisa": "fise/Fisa_E09_Egalitate_de_sanse.docx", "rez_doc": "fise/Rezolvare_E09_Egalitate_de_sanse.docx", "pornire_var": [], "pornire": "fise/E09_Egalitate_PORNIRE.docx", "pornire_desc": "Fișa de lucru a organizatorului (părțile I–IV) și tabelul cu cele 6 fraze de rescris.", "model": [], "fisier": "E09_Egalitate_Nume_Prenume.docx", "subiect": "E09 – Egalitate – Nume Prenume", "predare_obl": false, "pe_scurt": "Rezolvi <b>fișa de lucru a organizatorului</b> despre nediscriminare (grilă, adevărat/fals, asociere și un studiu de caz), exact cum o vei vedea la curs. Apoi faci exercițiul de <b>rescriere incluzivă</b>: 6 fraze care exclud pe cineva devin fraze care îi includ pe toți. Miezul: <b>cam 40 de minute</b>.", "recap": ["<b>Egalitatea de șanse</b>: aceleași condiții și oportunități pentru toți, indiferent de gen, vârstă, origine sau dizabilitate. <b>Tratamentul egal</b>: respect și corectitudine, fără favoruri și fără discriminări (suport, pg. 29).", "<b>Incluziunea digitală</b> e responsabilitatea <b>tuturor</b>, nu doar a programatorilor: a celui care scrie anunțul, a celui care face documentul, a celui care alege canalul.", "<b>Rescrierea incluzivă</b> (studiul de caz 7): „angajăm băieți pentru muncă fizică” → „angajăm <b>persoane</b> pentru muncă fizică”. Pui <b>persoana</b> înaintea caracteristicii („persoană cu dizabilități”, „călător care folosește scaun rulant”) și ceri <b>competența</b>, nu vârsta sau genul."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Fraza de rescris</th></tr></thead><tbody><tr><td>1</td><td>„Căutăm un băiat tânăr și energic pentru ghișeul de informații.”</td></tr><tr><td>2</td><td>„Doamnelor, nu vă speriați de noul program, e simplu chiar și pentru voi.”</td></tr><tr><td>3</td><td>„Colegii mai în vârstă să stea liniștiți, nu trebuie să înțeleagă aplicația, o fac cei tineri.”</td></tr><tr><td>4</td><td>„Un handicapat a cerut rampă la intrarea în stație.”</td></tr><tr><td>5</td><td>„Ședința e la 18:00, cine are copii să se descurce.”</td></tr><tr><td>6</td><td>„Anunțul e doar pe grupul de WhatsApp. Cine n-are smartphone, ghinion.”</td></tr></tbody></table></div>", "cerinte": [{"titlu": "Fișa de lucru a organizatorului (I–IV)", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E09_Egalitate_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "<b>Partea I:</b> scrie litera răspunsului corect la fiecare dintre cele 4 întrebări. <b>Partea II:</b> scrie <b>A</b> (adevărat) sau <b>F</b> (fals).", "<b>Partea III:</b> asociază fiecare situație cu tipul ei. Atenție: două situații sunt incluziune (a și c sunt amândouă „Incluziune”).", "<b>Partea IV:</b> răspunde la cele 3 întrebări ale studiului de caz, în 1–3 propoziții fiecare. La „soluții” scrie <b>cel puțin 3</b>, de la cine e martor până la platformă."], "ghiduri": ["G3"]}, {"titlu": "Rescriere incluzivă: 6 fraze", "minute": 20, "pasi": ["La fiecare frază din partea V scrie întâi <b>pe cine exclude</b> (femeile, colegii mai în vârstă, persoanele cu dizabilități, părinții, cine n-are smartphone).", "Rescrie fraza astfel încât să <b>includă pe toți</b> și să spună același lucru util: ce e nevoie, când, unde. Ceri <b>competența</b>, nu vârsta sau genul.", "La fraza 4 pune <b>persoana</b> înaintea caracteristicii. La 5 și 6 propune și o <b>soluție</b> (altă oră, înregistrare, încă un canal).", "Citește fiecare frază rescrisă cu voce tare: ai spune-o la fel, față în față, colegului despre care e vorba? Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Un anunț real, rescris", "pasi": ["Caută un anunț de angajare sau un anunț public pe internet (de exemplu pe un site de locuri de muncă) care cere „băiat”, „fată”, „sub 35 de ani” sau „aspect plăcut”.", "Copiază adresa lui la finalul documentului și rescrie anunțul incluziv, în 3–4 rânduri. Nu scrie numele firmei."]}, "verifica": ["Ai completat toate întrebările din părțile I–III.", "La partea IV ai numit comportamentul, efectele și cel puțin 3 soluții.", "Toate cele 6 fraze au scris pe cine exclud și sunt rescrise incluziv, cu aceeași informație utilă.", "La 4 ai pus persoana înaintea caracteristicii; la 5 și 6 ai propus o soluție."], "rez": {"intro": "Părțile I–III au un singur răspuns corect. La IV și V formulările tale pot fi altele: contează ideile de mai jos.", "parti": [{"titlu": "Părțile I–III", "html": "<div class='tw'><table><thead><tr><th scope='col'>Partea</th><th scope='col'>Răspunsurile corecte</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>I</td><td>1 – <b>b</b> · 2 – <b>b</b> · 3 – <b>c</b> · 4 – <b>c</b></td><td>Excluderea pe baza originii e discriminare; incluziunea = acces egal pentru toți; raportezi conținutul ofensator; un site inaccesibil exclude.</td></tr><tr><td>II</td><td>1 – <b>A</b> · 2 – <b>F</b> · 3 – <b>A</b> · 4 – <b>F</b></td><td>Incluziunea e treaba tuturor, nu doar a programatorilor; excluderea nu e acceptabilă „în unele cazuri”.</td></tr><tr><td>III</td><td>1 – <b>b</b> (Discriminare) · 2 – <b>a</b> (Incluziune) · 3 – <b>c</b> (Incluziune)</td><td>Subtitrarea și ajutorul pentru cei noi îi includ pe alții; comentariile jignitoare exclud.</td></tr></tbody></table></div>"}, {"titlu": "Partea IV – Studiul de caz (model)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Întrebarea</th><th scope='col'>Răspuns-model</th></tr></thead><tbody><tr><td>Ce tip de comportament</td><td>Hărțuire online (cyberbullying) și discriminare: persoana e umilită public pentru felul în care scrie, nu pentru ce spune.</td></tr><tr><td>Efecte</td><td>Rușine, retragere (nu mai scrie, nu mai cere ajutor), stres, pierderea încrederii în sine; ceilalți învață că e „normal” să râzi.</td></tr><tr><td>Soluții</td><td>1) Nu râzi și nu dai „like”. 2) Îi scrii calm celui ironizat, în public sau în privat, că nu e singur. 3) Ceri administratorului să amintească regulile și să șteargă comentariul. 4) Raportezi comentariul pe platformă. 5) Dacă se repetă: raportezi la superior (la serviciu) sau la CNCD.</td></tr></tbody></table></div>"}, {"titlu": "Partea V – Rescriere incluzivă (model)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Pe cine exclude</th><th scope='col'>Fraza rescrisă</th></tr></thead><tbody><tr><td>1</td><td>Femeile și persoanele mai în vârstă</td><td>„Căutăm o persoană energică, cu plăcere de a lucra cu publicul, pentru ghișeul de informații.”</td></tr><tr><td>2</td><td>Femeile (ton protector)</td><td>„Noul program e simplu. Vă trimit ghidul pas cu pas, iar mâine la 10:00 îl încercăm împreună.”</td></tr><tr><td>3</td><td>Colegii mai în vârstă</td><td>„Joi, la 14:00, facem o instruire de 30 de minute pentru toată lumea. Cine vrea ajutor și după, mă găsește la casa 1.”</td></tr><tr><td>4</td><td>Persoanele cu dizabilități (eticheta în locul persoanei)</td><td>„Un călător care folosește scaun rulant a cerut o rampă la intrarea în stație.”</td></tr><tr><td>5</td><td>Părinții (și oricine are alte obligații)</td><td>„Ședința e la 18:00. Pentru cine nu poate ajunge, o înregistrăm și trimitem rezumatul pe e-mail.”</td></tr><tr><td>6</td><td>Cine n-are smartphone sau WhatsApp</td><td>„Anunțul e pe grupul de WhatsApp, pe e-mail și la avizierul din birou.”</td></tr></tbody></table></div><p><b>Regula de verificare:</b> fraza rescrisă spune la fel de clar <b>ce e nevoie</b>, dar nu mai pune pe nimeni deoparte pentru gen, vârstă, dizabilitate sau situația familială.</p>"}]}, "glume": ["„E simplu chiar și pentru voi” e ca „nu te supăra, dar…”: tot ce urmează doare."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Fișa de lucru a organizatorului (I–IV)", 20], ["Cerința 2 – Rescriere incluzivă: 6 fraze", 20], ["Pas în plus – Un anunț real, rescris", 50], ["Întrebări și discuție", 15]]}, {"cod": "E10", "titlu": "Accesibilitate: verifică și repară un document Word", "statut": "rec", "nota": null, "ore": [17], "suport": "secț. 2, pg. 25-32", "org": "Studii nediscriminare 6, 8", "vechi": "T08", "zi": 5, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-08", "sg2": "2026-11-02", "teorie": [{"zi": 5, "ora": 17, "titlu": "Accesibilitate, incluziune și colaborare la distanță"}], "gata": true, "fisa": "fise/Fisa_E10_Accesibilitate_Word.docx", "rez_doc": "fise/Rezolvare_E10_Accesibilitate_Word.docx", "pornire_var": [], "pornire": "fise/E10_Anunt_PORNIRE.docx", "pornire_desc": "Anunțul „Programul de iarnă al casei de bilete”, cu 7 probleme de accesibilitate ascunse în el: titluri false, imagine fără text alternativ, tabel fără antet, text gri, link „click aici”, MAJUSCULE și rânduri goale.", "model": ["fise/Model_E10_Accesibil.docx"], "fisier": "E10_Accesibil_Nume_Prenume.docx", "subiect": "E10 – Accesibilitate – Nume Prenume", "predare_obl": false, "pe_scurt": "Primești un anunț în Word care <b>arată</b> în regulă, dar pe care nu-l poate folosi oricine: o colegă cu cititor de ecran, un coleg cu vedere slabă. Pornești <b>Verificarea accesibilității</b>, cauți și cu ochiul tău problemele pe care nu le prinde și <b>le repari</b>, până când Word spune că nu mai găsește nimic. Miezul: <b>cam 40 de minute</b>.", "recap": ["Un <b>cititor de ecran</b> citește cu voce tare ce e pe ecran. Pentru el, o imagine fără <b>text alternativ</b> e „imagine”, iar un titlu făcut doar cu litere mari și îngroșate e un paragraf oarecare. Titlurile adevărate se fac cu <b>stiluri</b> (<b>Titlu 1</b>).", "<b>Contrastul</b>: text gri deschis pe alb nu se citește bine pe telefon, la soare sau de către cineva cu vedere slabă. <b>Linkurile</b> spun unde duc („Programul trenurilor de iarnă”), nu „click aici”.", "<b>Revizuire</b> → <b>Verificare accesibilitate</b> (ghidul <b>G7</b>) arată <b>erori</b> și <b>avertismente</b> și îți spune cum le repari. Nu le prinde pe toate: textul scris cu MAJUSCULE sau rândurile goale puse cu <code>Enter</code> le vezi tu."], "text_dat": "", "cerinte": [{"titlu": "Găsește problemele", "minute": 15, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E10_Accesibil_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "<b>Revizuire</b> (Review) → <b>Verificare accesibilitate</b> (Check Accessibility). În dreapta se deschide panoul cu <b>Erori</b> și <b>Avertismente</b>. Notează-le pe o foaie sau la finalul documentului.", "Uită-te și tu, cu ochiul: <b>Vizualizare</b> → bifează <b>Panou de navigare</b> (Navigation Pane). Apar titlurile? Dacă panoul e gol, titlurile sunt false.", "Apasă <b>¶</b> (fila <b>Pornire</b>): vezi rândurile goale puse cu <code>Enter</code>. Caută textul gri deschis și textul scris cu MAJUSCULE.", "Scrie la finalul documentului lista problemelor găsite: <b>cel puțin 6</b>."], "ghiduri": ["G3", "G7"]}, {"titlu": "Repară-le și verifică din nou", "minute": 25, "pasi": ["<b>Titlurile:</b> pune cursorul pe fiecare titlu și alege din <b>Pornire</b> → <b>Stiluri</b> → <b>Titlu 1</b> (Heading 1). Verifică în Panoul de navigare: acum apar.", "<b>Imaginea:</b> click dreapta pe ea → <b>Vizualizare text alternativ</b> (View Alt Text) → scrie ce arată și de ce e acolo, într-o propoziție.", "<b>Tabelul:</b> click în tabel → fila <b>Proiectare tabel</b> (Table Design) → bifează <b>Rând antet</b> (Header Row). Apoi click dreapta pe primul rând → <b>Proprietăți tabel</b> → <b>Rând</b> → bifează <b>Se repetă ca rând antet</b> (Repeat as header row).", "<b>Textul gri:</b> selectează-l → butonul <b>Culoare font</b> (A cu bară colorată) → <b>Automat</b>. <b>Linkul:</b> click dreapta pe „click aici” → <b>Editare link</b> → la <b>Text de afișat</b> scrie unde duce.", "<b>MAJUSCULELE:</b> selectează paragraful → fila <b>Pornire</b> → butonul <b>Aa</b> (Modificare litere mari/mici) → <b>Tip propoziție</b> (Sentence case). Apoi refă literele mari la nume (Ana Rusu). <b>Rândurile goale:</b> șterge-le; dacă vrei spațiu, folosește <b>Spațiere după</b> paragraf (fila <b>Aspect</b>).", "Rulează din nou <b>Verificare accesibilitate</b>. Când scrie „<b>Nu s-au găsit probleme de accesibilitate</b>”, salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": ["G7"]}], "in_plus": {"titlu": "Ascultă documentul", "pasi": ["<b>Revizuire</b> → <b>Citire cu voce tare</b> (Read Aloud). Word citește documentul. Se înțelege fără să vezi ecranul?", "Pornește <b>Naratorul</b> (<code>Ctrl</code> + <code>Windows</code> + <code>Enter</code>) și mergi prin document cu săgețile. Oprește-l cu aceleași taste. Dacă Naratorul n-are voce în română, citește cu accent englezesc: e normal.", "Verifică și un document al tău, de la serviciu: câte probleme găsește Verificarea accesibilității?"]}, "verifica": ["Panoul de navigare arată toate cele 3 titluri.", "Imaginea are text alternativ care spune ce arată.", "Tabelul are rând antet, care se repetă pe pagina următoare.", "Nu mai e text gri deschis, nici MAJUSCULE, nici rânduri goale puse cu Enter.", "Linkul spune unde duce, iar Verificarea accesibilității nu mai găsește probleme."], "rez": {"intro": "Documentul are <b>7 probleme</b>. Verificarea accesibilității le găsește pe unele (numărul exact poate să difere de la o versiune de Office la alta), restul le vezi tu. Documentul reparat e și pe site: <code>Model_E10_Accesibil.docx</code>.", "parti": [{"titlu": "Cele 7 probleme și cum le repari", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Problema</th><th scope='col'>O găsește Word?</th><th scope='col'>Cine e încurcat</th><th scope='col'>Cum o repari</th></tr></thead><tbody><tr><td>1</td><td>Titlurile sunt doar text mare și îngroșat</td><td>uneori (sfat)</td><td>Cine folosește cititor de ecran: nu poate sări de la un titlu la altul</td><td>Stilul <b>Titlu 1</b></td></tr><tr><td>2</td><td>Imaginea n-are text alternativ</td><td>da, <b>eroare</b></td><td>Cititorul de ecran spune doar „imagine”</td><td>Click dreapta → <b>Vizualizare text alternativ</b></td></tr><tr><td>3</td><td>Tabelul n-are rând antet</td><td>da, avertisment</td><td>Cititorul de ecran nu știe ce înseamnă fiecare coloană</td><td><b>Proiectare tabel</b> → <b>Rând antet</b> + <b>Se repetă ca rând antet</b></td></tr><tr><td>4</td><td>Text gri deschis pe alb</td><td>da, avertisment (contrast)</td><td>Vedere slabă, ecran de telefon, lumină puternică</td><td><b>Culoare font</b> → <b>Automat</b></td></tr><tr><td>5</td><td>Linkul se numește „click aici”</td><td>uneori</td><td>Cititorul de ecran citește lista de linkuri: „click aici, click aici…”</td><td><b>Editare link</b> → <b>Text de afișat</b>: „Mersul trenurilor de iarnă”</td></tr><tr><td>6</td><td>Paragraf scris cu MAJUSCULE</td><td>nu</td><td>Se citește greu; unele cititoare de ecran citesc literă cu literă</td><td>Butonul <b>Aa</b> → <b>Tip propoziție</b></td></tr><tr><td>7</td><td>Rânduri goale puse cu Enter</td><td>nu (uneori sfat)</td><td>Cititorul de ecran spune „gol, gol, gol”</td><td>Le ștergi; folosești <b>Spațiere după</b></td></tr></tbody></table></div>"}, {"titlu": "Textul alternativ și linkul (model)", "html": "<p><b>Text alternativ:</b> „Pictogramă: un fulg de nea lângă un ceas, pentru programul de iarnă.” Scurt, spune ce arată și de ce e acolo. Nu începe cu „Imagine cu…”: cititorul de ecran spune deja că e o imagine.</p><p><b>Linkul:</b> „Mersul trenurilor de iarnă, pe site-ul stației” în loc de „click aici”.</p><div class='cadru'>La final, panoul spune „Nu s-au găsit probleme de accesibilitate” (sau doar sfaturi). Panoul de navigare arată: Programul de iarnă al casei de bilete · Ce se schimbă · Cui vă adresați.</div>"}]}, "glume": ["„Click aici” e ca „vino încoace”, strigat într-o gară: vin toți și nu știe nimeni de ce."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Găsește problemele", 15], ["Cerința 2 – Repară-le și verifică din nou", 25], ["Pas în plus – Ascultă documentul", 50], ["Întrebări și discuție", 15]]}, {"cod": "E11", "titlu": "Accesibilitate: o zi fără mouse (tastatură, Lupa, Naratorul)", "statut": "rec", "nota": null, "ore": [17], "suport": "secț. 2, pg. 25-32", "org": "Studii nediscriminare 3, 9", "vechi": "T08", "zi": 6, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-09", "sg2": "2026-11-03", "teorie": [{"zi": 5, "ora": 17, "titlu": "Accesibilitate, incluziune și colaborare la distanță"}], "gata": true, "fisa": "fise/Fisa_E11_Fara_mouse.docx", "rez_doc": "fise/Rezolvare_E11_Fara_mouse.docx", "pornire_var": [], "pornire": "fise/E11_Fara_mouse_PORNIRE.docx", "pornire_desc": "Jurnalul tău „fără mouse”: tabelul cu cele 10 încercări (a mers? ce a fost greu?) și locul pentru concluzii. Îl completezi tot fără mouse.", "model": [], "fisier": "E11_Fara_mouse_Nume_Prenume.docx", "subiect": "E11 – Fara mouse – Nume Prenume", "predare_obl": false, "pe_scurt": "O jumătate de oră <b>fără mouse</b>. Pui mausul deoparte (sau dezactivezi touchpad-ul) și faci lucruri obișnuite doar din <b>tastatură</b>: pornești programe, treci între ferestre, navighezi pe un site, salvezi. Apoi încerci <b>Lupa</b> și <b>Naratorul</b>, uneltele Windows pentru cine vede slab sau deloc. La final scrii ce bariere ai simțit, ca în studiile de caz ale organizatorului. Miezul: <b>cam 40 de minute</b>.", "recap": ["Mulți oameni <b>nu pot folosi mausul</b>: o mână rănită, tremor, o dizabilitate motorie. Un portal care merge <b>doar</b> cu mausul îi exclude (studiul de caz 3: încălcarea accesibilității universale).", "<code>Tab</code> mută <b>focusul</b> (conturul care arată unde ești) de la un element la altul, <code>Shift</code> + <code>Tab</code> înapoi, <code>Enter</code> apasă, <code>Esc</code> închide. Un site bine făcut se poate folosi tot așa.", "<b>Lupa</b> mărește ecranul pentru cine vede slab. <b>Naratorul</b> e cititorul de ecran din Windows: citește cu voce tare ce e pe ecran (studiul de caz 9: simularea unui utilizator cu dizabilitate)."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Ce încerci</th><th scope='col'>Tastele</th></tr></thead><tbody><tr><td>1</td><td>Deschide meniul Start și pornește Word (fără mouse)</td><td><code>Windows</code>, scrii <code>word</code>, <code>Enter</code></td></tr><tr><td>2</td><td>Treci de la o fereastră deschisă la alta</td><td><code>Alt</code> + <code>Tab</code> (ții <code>Alt</code>, apeși <code>Tab</code> de câte ori trebuie)</td></tr><tr><td>3</td><td>Deschide Explorer</td><td><code>Windows</code> + <code>E</code></td></tr><tr><td>4</td><td>Arată desktopul, apoi înapoi</td><td><code>Windows</code> + <code>D</code> (de două ori)</td></tr><tr><td>5</td><td>În browser: mergi în bara de adrese și scrie o adresă</td><td><code>Ctrl</code> + <code>L</code>, scrii, <code>Enter</code></td></tr><tr><td>6</td><td>Pe o pagină: treci de la un link la altul și deschide unul</td><td><code>Tab</code> (înainte), <code>Shift</code> + <code>Tab</code> (înapoi), <code>Enter</code></td></tr><tr><td>7</td><td>Caută un cuvânt pe pagină</td><td><code>Ctrl</code> + <code>F</code></td></tr><tr><td>8</td><td>Salvează documentul</td><td><code>Ctrl</code> + <code>S</code></td></tr><tr><td>9</td><td>Pornește Lupa, mărește, micșorează, oprește</td><td><code>Windows</code> + <code>+</code>, <code>Windows</code> + <code>-</code>, <code>Windows</code> + <code>Esc</code></td></tr><tr><td>10</td><td>Pornește și oprește Naratorul</td><td><code>Ctrl</code> + <code>Windows</code> + <code>Enter</code></td></tr></tbody></table></div>", "cerinte": [{"titlu": "Windows și programele, doar din tastatură", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b> (ultima dată cu mausul!) și deschide-l. Apasă <b>Activare editare</b> dacă apare bara galbenă. De acum <b>pune mausul deoparte</b>.", "Salvează fișierul cu numele tău: <code>F12</code> deschide <b>Salvare ca</b>; scrii <code>E11_Fara_mouse_Nume_Prenume</code> și <code>Enter</code> (ghidul <b>G3</b>).", "Fă încercările 1–8 din tabelul „<b>Textul pe care îl folosești</b>”, una câte una. Dacă te blochezi, apasă <code>Esc</code> sau <code>Alt</code> + <code>Tab</code> ca să revii.", "La încercarea 6, alege un site cunoscut (de exemplu site-ul CFR Călători sau al primăriei) și numără de câte ori apeși <code>Tab</code> până ajungi la meniu. Vezi conturul (focusul) pe ecran?", "După fiecare încercare, revino în jurnal (<code>Alt</code> + <code>Tab</code>) și completează rândul: <b>A mers?</b> și <b>Ce a fost greu</b>."], "ghiduri": ["G3", "G8"]}, {"titlu": "Lupa, Naratorul și concluziile", "minute": 20, "pasi": ["<b>Lupa:</b> apasă <code>Windows</code> + <code>+</code> de 2–3 ori. Mișcă-te prin jurnal: ecranul te urmărește. Micșorează cu <code>Windows</code> + <code>-</code> și oprește cu <code>Windows</code> + <code>Esc</code>.", "<b>Naratorul:</b> apasă <code>Ctrl</code> + <code>Windows</code> + <code>Enter</code>. Dacă apare o fereastră de bun venit, apasă <code>Enter</code> pe <b>OK</b>. Mergi prin jurnal cu săgețile și ascultă 1–2 minute. Oprește-l cu aceleași taste.", "Completează rândurile 9 și 10 din jurnal.", "La „<b>Ce am descoperit</b>” scrie <b>3 lucruri grele</b>, ce ar trebui să aibă un site ca să meargă din tastatură și cum a sunat Naratorul.", "Salvează (<code>Ctrl</code> + <code>S</code>). Abia acum poți lua mausul înapoi."], "ghiduri": ["G8"]}], "in_plus": {"titlu": "Încă trei unelte de accesibilitate", "pasi": ["<code>Ctrl</code> + <code>+</code> și <code>Ctrl</code> + <code>-</code> în browser: măresc și micșorează doar pagina. <code>Ctrl</code> + <code>0</code> revine la normal.", "<b>Setări</b> → <b>Accesibilitate</b> → <b>Dimensiune text</b>: mărește textul în tot Windows-ul. Pune-l la loc după.", "<b>Setări</b> → <b>Accesibilitate</b> → <b>Subtitrări</b> (sau <b>Subtitrări în direct</b>, pe Windows 11, <code>Windows</code> + <code>Ctrl</code> + <code>L</code>): pornește un clip cu sunet și vezi dacă apar subtitrările."]}, "verifica": ["Ai făcut toate cele 10 încercări și ai completat jurnalul.", "Ai salvat fișierul cu <code>F12</code>, fără mouse.", "Ai pornit și oprit Lupa și Naratorul.", "Ai scris 3 lucruri grele și ce ar trebui să aibă un site ca să meargă din tastatură."], "rez": {"intro": "Tastele sunt aceleași pentru toți. Ce a fost greu e diferit pentru fiecare: mai jos ai ce spun de obicei cursanții și ce înseamnă pentru accesibilitate.", "parti": [{"titlu": "Cele 10 încercări (răspunsuri exacte)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Ce încerci</th><th scope='col'>Tastele</th></tr></thead><tbody><tr><td>1</td><td>Deschide meniul Start și pornește Word (fără mouse)</td><td><code>Windows</code>, scrii <code>word</code>, <code>Enter</code></td></tr><tr><td>2</td><td>Treci de la o fereastră deschisă la alta</td><td><code>Alt</code> + <code>Tab</code> (ții <code>Alt</code>, apeși <code>Tab</code> de câte ori trebuie)</td></tr><tr><td>3</td><td>Deschide Explorer</td><td><code>Windows</code> + <code>E</code></td></tr><tr><td>4</td><td>Arată desktopul, apoi înapoi</td><td><code>Windows</code> + <code>D</code> (de două ori)</td></tr><tr><td>5</td><td>În browser: mergi în bara de adrese și scrie o adresă</td><td><code>Ctrl</code> + <code>L</code>, scrii, <code>Enter</code></td></tr><tr><td>6</td><td>Pe o pagină: treci de la un link la altul și deschide unul</td><td><code>Tab</code> (înainte), <code>Shift</code> + <code>Tab</code> (înapoi), <code>Enter</code></td></tr><tr><td>7</td><td>Caută un cuvânt pe pagină</td><td><code>Ctrl</code> + <code>F</code></td></tr><tr><td>8</td><td>Salvează documentul</td><td><code>Ctrl</code> + <code>S</code></td></tr><tr><td>9</td><td>Pornește Lupa, mărește, micșorează, oprește</td><td><code>Windows</code> + <code>+</code>, <code>Windows</code> + <code>-</code>, <code>Windows</code> + <code>Esc</code></td></tr><tr><td>10</td><td>Pornește și oprește Naratorul</td><td><code>Ctrl</code> + <code>Windows</code> + <code>Enter</code></td></tr></tbody></table></div><p>Dacă la 10 ți-a cerut confirmare, e normal: prima dată Windows arată o fereastră despre Narator. La Lupa, <code>Windows</code> + <code>+</code> înseamnă tasta Windows și tasta <code>+</code> (de lângă <code>Backspace</code> sau de pe tastatura numerică).</p>"}, {"titlu": "Ce descoperă de obicei cursanții", "html": "<p><b>Grele:</b> găsești greu unde e focusul pe unele site-uri; trebuie să apeși <code>Tab</code> de 20–30 de ori până la meniu; ferestrele de cookie-uri nu se închid din tastatură; Naratorul vorbește repede și citește tot, inclusiv meniurile.</p><div class='cadru'>Ce trebuie să aibă un site ca să meargă din tastatură: <b>focus vizibil</b> (vezi mereu unde ești); ordine logică a elementelor la <code>Tab</code>; un link „<b>Salt la conținut</b>” la început; toate butoanele și meniurile accesibile cu <code>Tab</code> și <code>Enter</code>; ferestre care se închid cu <code>Esc</code>; imagini cu text alternativ (pentru Narator).</div><p><b>Legătura cu munca ta:</b> un document Word cu titluri adevărate (E10) se parcurge ușor cu Naratorul; unul cu titluri false, nu.</p>"}]}, "glume": ["Fără mouse prima jumătate de oră e ca primul drum cu trenul de noapte: totul pare departe. A doua jumătate, știi deja unde e vagonul-restaurant."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Windows și programele, doar din tastatură", 20], ["Cerința 2 – Lupa, Naratorul și concluziile", 20], ["Pas în plus – Încă trei unelte de accesibilitate", 50], ["Întrebări și discuție", 15]]}, {"cod": "E12", "titlu": "Colaborare: comentarii și Urmărire modificări în Word", "statut": "rec", "nota": null, "ore": [13, 17], "suport": "secț. 2, pg. 25-32", "org": "—", "vechi": "T09", "zi": 6, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-09", "sg2": "2026-11-03", "teorie": [{"zi": 4, "ora": 13, "titlu": "Comunicarea digitală la locul de muncă"}, {"zi": 5, "ora": 17, "titlu": "Accesibilitate, incluziune și colaborare la distanță"}], "gata": true, "fisa": "fise/Fisa_E12_Urmarire_modificari.docx", "rez_doc": "fise/Rezolvare_E12_Urmarire_modificari.docx", "pornire_var": [], "pornire": "fise/E12_Predare_tura_PORNIRE.docx", "pornire_desc": "Documentul „Predarea turei la casa de bilete – reguli”, cu 5 modificări urmărite (Elena Stan, Radu Ilie) și 2 comentarii (Ana Rusu, Radu Ilie). Se deschide cu Urmărire modificări pornită.", "model": [], "fisier": "E12_Predare_tura_Nume_Prenume.docx", "subiect": "E12 – Colaborare – Nume Prenume", "predare_obl": false, "pe_scurt": "Colegii tăi, Elena și Radu, au corectat <b>direct în documentul tău</b> regulile de predare a turei, cu <b>Urmărire modificări</b> pornită, și au lăsat <b>comentarii</b>. Tu decizi, după regulile șefei, ce <b>accepți</b> și ce <b>respingi</b>, răspunzi la comentarii și faci o modificare a ta, urmărită. Miezul: <b>cam 35 de minute</b>.", "recap": ["<b>Urmărire modificări</b> (Track Changes, fila <b>Revizuire</b>): tot ce adaugă sau șterge cineva apare colorat, cu numele lui. Proprietarul documentului alege <b>Acceptare</b> sau <b>Respingere</b>, una câte una.", "Un <b>comentariu</b> e o întrebare sau o observație, nu o modificare. Îi <b>răspunzi</b> (butonul <b>Răspuns</b>), iar când e lămurit îl <b>rezolvi</b> (Rezolvare) sau îl ștergi.", "Un singur document, la care lucrează toți (OneDrive), e mai bun decât 5 copii trimise pe e-mail: nu mai ghicești care e varianta bună."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Regula șefei, Ana Rusu</th><th scope='col'>Ce faci</th></tr></thead><tbody><tr><td>1. Corecturile de scriere și de limbaj (diacritice, formulări care îi includ pe toți)</td><td>Accepți</td></tr><tr><td>2. Informațiile noi, utile și corecte</td><td>Accepți</td></tr><tr><td>3. Orice schimbare de <b>oră</b> sau de <b>termen</b>: o aprobă doar șefa</td><td>Respingi și îi spui într-un comentariu</td></tr><tr><td>4. Orice ștergere a unei reguli de <b>siguranță</b></td><td>Respingi</td></tr></tbody></table></div><p>Numărul de telefon al IT-ului, de care e nevoie la unul dintre comentarii: <b>interior 2345</b> (inventat).</p>", "cerinte": [{"titlu": "Acceptă sau respinge cele 5 modificări", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E12_Predare_tura_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Fila <b>Revizuire</b> (Review). La <b>Urmărire</b> (Tracking) alege afișarea <b>Toate marcajele</b> (All Markup), ca să vezi tot ce s-a schimbat și cine a schimbat.", "Apasă <b>Următoarea</b> (Next), în grupul <b>Modificări</b>. Word te duce la prima modificare. Citește-o și hotărăște, după <b>regulile șefei</b>: <b>Acceptare</b> (Accept) sau <b>Respingere</b> (Reject).", "Treci așa prin <b>toate cele 5</b> modificări. Când cineva a înlocuit un cuvânt, Word arată <b>două</b> marcaje (textul șters și textul nou): le accepți sau le respingi pe amândouă.", "Pe o foaie (sau la finalul documentului, după ce termini), notează pentru fiecare: ce era, ce ai ales și regula după care ai ales.", "Când Word spune că nu mai sunt modificări, citește documentul de la cap la coadă: are sens?"], "ghiduri": ["G3"]}, {"titlu": "Comentariile și modificarea ta", "minute": 15, "pasi": ["Mergi la comentariul <b>Anei Rusu</b> (despre IT). Apasă <b>Răspuns</b> (Reply) și scrie: ce număr ai trecut în document. Apoi, cu <b>Urmărire modificări</b> pornită (butonul e evidențiat), scrie în text, după „la IT”, numărul: <code>, la interiorul 2345</code>.", "Mergi la comentariul lui <b>Radu</b> (despre cele 10 minute). Răspunde-i politicos de ce i-ai respins modificarea și că i-ai scris șefei.", "Adaugă <b>un comentariu al tău</b> pentru Ana Rusu: selectează textul despre timpul de predare → <b>Comentariu nou</b> (New Comment) → întreabă-o dacă vrea să schimbe cele 5 minute în 10.", "Salvează (<code>Ctrl</code> + <code>S</code>). În document rămân acum doar <b>modificarea ta</b> (numărul IT), urmărită, și comentariile, cu răspunsurile tale."], "ghiduri": []}], "in_plus": {"titlu": "Compară două variante", "pasi": ["<b>Revizuire</b> → <b>Comparare</b> (Compare) → <b>Comparare…</b>. La <b>Document original</b> alege fișierul de pornire, la <b>Document revizuit</b> fișierul tău.", "Word face un al treilea document, cu toate diferențele marcate. Seamănă cu ce ai decis tu?", "Închide-l fără să-l salvezi."]}, "verifica": ["Ai acceptat cele 3 modificări ale Elenei (diacritica, formularea, rolele de hârtie) și le-ai respins pe cele 2 ale lui Radu (ștergerea regulii despre seif, cele 10 minute).", "Ai răspuns la ambele comentarii.", "Numărul IT apare în text ca modificare urmărită a ta.", "Ai adăugat un comentariu al tău pentru Ana Rusu."], "rez": {"intro": "Deciziile au un singur răspuns corect, pentru că le dau regulile șefei. Răspunsurile la comentarii pot fi formulate altfel.", "parti": [{"titlu": "Cele 5 modificări", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Cine</th><th scope='col'>Ce a schimbat</th><th scope='col'>Decizia</th><th scope='col'>Regula</th></tr></thead><tbody><tr><td>1</td><td>Elena Stan</td><td>„fişa” → „fișa” (ș cu virgulă, nu cu sedilă)</td><td><b>Acceptare</b></td><td>1 – corectură de scriere</td></tr><tr><td>2</td><td>Radu Ilie</td><td>șterge „Seiful se încuie după fiecare numărare.”</td><td><b>Respingere</b></td><td>4 – regulă de siguranță</td></tr><tr><td>3</td><td>Elena Stan</td><td>„băiatului din tura următoare” → „colegului sau colegei din tura următoare”</td><td><b>Acceptare</b></td><td>1 – formulare care îi include pe toți</td></tr><tr><td>4</td><td>Radu Ilie</td><td>„în 5 minute” → „în cel mult 10 minute”</td><td><b>Respingere</b></td><td>3 – schimbare de termen, o aprobă doar șefa</td></tr><tr><td>5</td><td>Elena Stan</td><td>adaugă „Rolele noi sunt în dulapul din stânga.”</td><td><b>Acceptare</b></td><td>2 – informație nouă, utilă</td></tr></tbody></table></div>"}, {"titlu": "Răspunsurile la comentarii (model)", "html": "<div class='cadru'>Către Ana Rusu: „Am trecut numărul IT-ului în document: interiorul 2345.”</div><div class='cadru'>Către Radu Ilie: „Mulțumesc, Radu! Am respins modificarea, pentru că termenele le aprobă doar Ana. I-am lăsat un comentariu să decidă ea dacă trecem la 10 minute.”</div><div class='cadru'>Comentariul tău, pentru Ana Rusu: „Ana, Radu propune 10 minute pentru predare în loc de 5 (aseară a durat 8). Vrei să schimbăm termenul?”</div>"}, {"titlu": "Documentul la final", "html": "<div class='cadru'>Predarea turei la casa de bilete – reguli<br>1. La sfârșitul turei, casierul numără banii din casă și completează fișa de predare. Seiful se încuie după fiecare numărare.<br>2. Predarea se face în prezența colegului sau colegei din tura următoare, în 5 minute.<br>3. Rola de hârtie pentru imprimantă se schimbă când apare banda roșie. Rolele noi sunt în dulapul din stânga.<br>4. Problemele cu aplicația de vânzare se anunță la IT, la interiorul 2345.  ← singura modificare urmărită rămasă: a ta</div>"}]}, "glume": ["Urmărire modificări e ca jurnalul de bord al trenului: nu împiedică pe nimeni să greșească, dar știi mereu cine a tras de frână."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Acceptă sau respinge cele 5 modificări", 20], ["Cerința 2 – Comentariile și modificarea ta", 15], ["Pas în plus – Compară două variante", 55], ["Întrebări și discuție", 15]]}, {"cod": "E13", "titlu": "Ședința online: invitația și minuta", "statut": "rec", "nota": null, "ore": [17, 13], "suport": "secț. 2, pg. 25-32", "org": "Studii comunicare și etichetă", "vechi": "T09", "zi": 7, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-12", "sg2": "2026-11-04", "teorie": [{"zi": 5, "ora": 17, "titlu": "Accesibilitate, incluziune și colaborare la distanță"}, {"zi": 4, "ora": 13, "titlu": "Comunicarea digitală la locul de muncă"}], "gata": true, "fisa": "fise/Fisa_E13_Sedinta_online.docx", "rez_doc": "fise/Rezolvare_E13_Sedinta_online.docx", "pornire_var": [], "pornire": "fise/E13_Sedinta_PORNIRE.docx", "pornire_desc": "Documentul are scenariul, un șablon de invitație de completat și notițele luate în ședință.", "model": [], "fisier": "E13_Sedinta_Nume_Prenume.docx", "subiect": "E13 – Ședința – Nume Prenume", "predare_obl": false, "pe_scurt": "Șefa biroului îți cere să organizezi o <b>ședință online de 30 de minute</b>. Tu scrii <b>invitația</b> (cu agendă și plan B), apoi transformi <b>notițele dezordonate</b> luate în ședință într-o <b>minută</b> scurtă: ce s-a hotărât și cine ce face, până când. Miezul exercițiului: <b>cam 40 de minute</b>. Restul timpului e pentru „Pas în plus” și întrebări.", "recap": ["O ședință bună are <b>4 obiceiuri</b>: agenda trimisă din timp; ora exactă în calendar; linkul verificat și trimis din timp; camera și microfonul testate cu un minut înainte.", "<b>Planul B</b>: un număr de telefon de rezervă și o persoană care trimite rezumatul dacă pică legătura.", "<b>Minuta</b> nu e o stenogramă. Scrii doar <b>deciziile</b> și <b>acțiunile</b> (cine – ce – până când). Discuțiile fără concluzie nu intră."], "text_dat": "", "cerinte": [{"titlu": "Invitația la ședință", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b> (butonul „Fișier de pornire”) și deschide-l. Dacă sus apare o bară galbenă cu <b>Activare editare</b> (Enable Editing), apasă pe ea. Altfel nu poți scrie în document.", "Salvează imediat fișierul cu numele tău: <code>E13_Sedinta_Nume_Prenume.docx</code> (vezi ghidul <b>G3</b>). De acum lucrezi doar în fișierul tău.", "Citește <b>mesajul șefei</b> de la începutul documentului. Acolo găsești tot: subiectul, ziua, ora, cine participă, ce se discută și ce pregătește fiecare.", "Completează <b>invitația</b> din tabel, rând cu rând: <b>Subiect</b>, <b>Când</b> (ziua și ora de început și de sfârșit), <b>Unde</b> (scrie <code>[link Zoom]</code>), <b>Participanți</b>, <b>Agenda</b> (3 puncte, fiecare cu minutele lui), <b>Ce pregătiți</b>, <b>Plan B</b>.", "Verifică: minutele din agendă adunate dau exact durata ședinței? Ora de sfârșit se potrivește cu durata?"], "ghiduri": ["G3"]}, {"titlu": "Minuta ședinței", "minute": 20, "pasi": ["Mergi la partea a doua a documentului: <b>Notițele luate în ședință</b>. Sunt scrise în grabă, amestecate, ca în realitate.", "Citește-le o dată de la cap la coadă. Apoi întreabă-te la fiecare rând: <b>e o decizie?</b> (ceva hotărât) <b>e o acțiune?</b> (cineva are de făcut ceva până la o dată) <b>sau doar o discuție?</b>", "Scrie <b>deciziile</b> în tabelul „Decizii”, câte una pe rând, ca propoziții scurte și complete.", "Scrie <b>acțiunile</b> în tabelul „Acțiuni”: <b>Cine</b> – <b>Ce face</b> – <b>Până când</b>.", "Completează <b>Următoarea ședință</b> (când, cât durează, unde). Discuțiile fără concluzie <b>nu</b> intră în minută.", "Salvează fișierul (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Pune ședința în calendarul tău", "pasi": ["Deschide calendarul pe care îl folosești: <b>Outlook</b> (Calendar → <b>Eveniment nou</b> / New event) sau <b>Google Calendar</b> (butonul <b>Creează</b> / Create).", "Completează titlul, ziua, ora de început și de sfârșit și, la descriere, lipește agenda din invitația ta. <b>Nu adăuga invitați</b>: e doar un exercițiu.", "Salvează evenimentul și fă o <b>captură de ecran</b> (ghidul <b>G1</b>). Lipește captura la finalul documentului tău (ghidul <b>G2</b>)."]}, "verifica": ["Invitația are subiect clar, zi și oră exactă (început și sfârșit), link, participanți, agendă în 3 puncte cu minute, ce pregătiți, plan B.", "Minutele din agendă dau împreună 30.", "Minuta are 4 decizii și 3 acțiuni (cine – ce – până când) și data următoarei ședințe.", "Discuția despre cafea <b>nu</b> apare în minută."], "rez": {"intro": "Mai jos ai invitația și minuta completate exact după datele din fișierul de pornire. Formulările tale pot fi puțin diferite. Contează ca <b>toate informațiile</b> să fie acolo și ca <b>deciziile și acțiunile</b> să fie aceleași.", "parti": [{"titlu": "Cerința 1 – Invitația (model complet)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Câmp</th><th scope='col'>Ce scrii</th></tr></thead><tbody><tr><td>Subiect</td><td>Ședință online: programul casei de bilete de sărbători</td></tr><tr><td>Când</td><td>Joi, [data], 10:00–10:30 (30 de minute)</td></tr><tr><td>Unde</td><td>Online, pe Zoom: [link Zoom]</td></tr><tr><td>Participanți</td><td>Ana Rusu, Mihai Pop, Elena Stan, Radu Ilie și eu (scriu minuta)</td></tr><tr><td>Agenda</td><td>1) Programul pe ture între 24 și 31 decembrie – 15 min · 2) Cine ține ghișeul de informații – 10 min · 3) Cum anunțăm călătorii – 5 min</td></tr><tr><td>Ce pregătiți</td><td>Fiecare vine cu zilele dintre 24 și 31 decembrie în care nu poate lucra.</td></tr><tr><td>Plan B</td><td>Dacă pică Zoom-ul, sunați la 07xx xxx xxx (număr fictiv). Rezumatul îl trimit eu pe e-mail, în aceeași zi.</td></tr></tbody></table></div><p><b>De ce așa:</b> 15 + 10 + 5 = <b>30 de minute</b>, exact cât ține ședința (10:00–10:30). Toate cele trei subiecte din mesajul șefei apar în agendă, în ordinea importanței.</p><p><b>Greșeala frecventă:</b> „Joi după-amiază” sau „pe la 10”. Ora trebuie să fie <b>exactă</b>, cu început și sfârșit, ca să intre corect în calendarul fiecăruia.</p>"}, {"titlu": "Cerința 2 – Minuta (model complet)", "html": "<p><b>Minuta ședinței – programul casei de bilete de sărbători</b></p><p>Data: joi, [data], 10:00–10:30, online (Zoom). Participanți: Ana Rusu, Mihai Pop, Elena Stan, Radu Ilie. Minuta: [numele tău].</p><div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Decizie</th></tr></thead><tbody><tr><td>1</td><td>Între 24 și 31 decembrie, turele rămân aceleași: dimineața 7:00–15:00, după-amiaza 15:00–23:00.</td></tr><tr><td>2</td><td>Pe 25 și 26 decembrie, Radu Ilie îl înlocuiește pe Mihai Pop.</td></tr><tr><td>3</td><td>La ghișeul de informații stă Elena Stan dimineața și Mihai Pop după-amiaza.</td></tr><tr><td>4</td><td>Călătorii sunt anunțați prin afiș la intrare și prin mesaj pe pagina stației.</td></tr></tbody></table></div><div class='tw'><table><thead><tr><th scope='col'>Cine</th><th scope='col'>Ce face</th><th scope='col'>Până când</th></tr></thead><tbody><tr><td>Elena Stan</td><td>Face afișul pentru intrare</td><td>vineri</td></tr><tr><td>Ana Rusu</td><td>Trimite textul pentru pagina stației</td><td>luni</td></tr><tr><td>Radu Ilie</td><td>Verifică dacă merge imprimanta de la casă</td><td>miercuri</td></tr></tbody></table></div><p>Următoarea ședință: joi viitoare, 10:00–10:15, pe Zoom (15 minute).</p><p><b>De ce lipsește discuția despre cafea:</b> nu s-a hotărât nimic și nimeni nu are de făcut nimic. O minută bună păstrează doar ce <b>schimbă ceva</b>.</p><p><b>Cum verifici:</b> fiecare rând din tabelul „Acțiuni” are <b>un singur om</b>, <b>o singură treabă</b> și <b>o dată</b>. Dacă un rând are „toți” sau „cât mai repede”, nu e o acțiune clară.</p>"}, {"titlu": "Pas în plus – evenimentul din calendar", "html": "<p>În captură trebuie să se vadă titlul, ziua, ora 10:00–10:30 și agenda în descriere. Fără invitați adăugați.</p>"}]}, "glume": ["O ședință fără agendă e ca un tren fără mers: pleacă, dar nu știe nimeni unde ajunge.", "Minuta bună e ca biletul de tren: scurtă, clară și cu ora exactă."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Invitația la ședință", 20], ["Cerința 2 – Minuta ședinței", 20], ["Pas în plus – Pune ședința în calendarul tău", 50], ["Întrebări și discuție", 15]]}, {"cod": "E14", "titlu": "Word: document cu titluri, listă, tabel și cuprins automat", "statut": "rec", "nota": null, "ore": [19, 7], "suport": "1.1 Word, pg. 5-6; secț. 3", "org": "Studii crearea de conținut digital", "vechi": "T12", "zi": 7, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-12", "sg2": "2026-11-04", "teorie": [{"zi": 5, "ora": 19, "titlu": "Conținut digital: Word și PowerPoint"}, {"zi": 2, "ora": 7, "titlu": "Word, Excel și drumul fișierului (OneDrive)"}], "gata": true, "fisa": "fise/Fisa_E14_Word.docx", "rez_doc": "fise/Rezolvare_E14_Word.docx", "pornire_var": [], "pornire": "fise/E14_Word_PORNIRE.docx", "pornire_desc": "Textul ghidului, scris tot cu litere normale (fără titluri, fără listă, fără tabel).", "model": ["fise/Model_E14_Word.docx"], "fisier": "E14_Word_Nume_Prenume.docx", "subiect": "E14 – Word – Nume Prenume", "predare_obl": false, "pe_scurt": "Primești un text <b>neformatat</b>: „Ghidul noului coleg”. Îl transformi într-un document ordonat: <b>titluri cu stiluri</b>, o <b>listă cu marcatori</b>, un <b>tabel</b> și un <b>cuprins automat</b>, plus <b>numărul paginii</b>. Miezul exercițiului: <b>cam 40 de minute</b>.", "recap": ["<b>Stilurile</b> (Titlu, Titlu 1) nu sunt doar „litere mai mari”. Word înțelege din ele <b>structura</b> documentului. Din ele face cuprinsul automat și panoul de navigare, iar cititoarele de ecran anunță titlurile.", "<b>Lista cu marcatori</b> e pentru idei de același fel, <b>tabelul</b> pentru informații care se compară pe coloane.", "<b>Cuprinsul automat</b> se face din titluri. Dacă schimbi un titlu, actualizezi cuprinsul cu un click."], "text_dat": "", "cerinte": [{"titlu": "Titlurile și lista", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, deschide-l, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l cu numele tău: <code>E14_Word_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "<b>Titlul documentului.</b> Dă un click oriunde pe primul rând, „Ghidul noului coleg de la casa de bilete”. Sus, în fila <b>Pornire</b> (Home), în caseta <b>Stiluri</b>, apasă pe <b>Titlu</b> (Title). Rândul devine mare: e titlul documentului.", "<b>Cele 4 titluri de capitol.</b> Pe rând, dă click pe fiecare dintre rândurile: „Despre birou”, „Programul”, „Cui te adresezi”, „Patru reguli de siguranță digitală”, și apasă stilul <b>Titlu 1</b> (Heading 1).", "<b>Verificare rapidă:</b> fila <b>Vizualizare</b> (View) → bifează <b>Panou de navigare</b> (Navigation Pane). În stânga trebuie să vezi <b>exact cele 4 titluri</b>. Dacă lipsește unul, înseamnă că nu are stilul Titlu 1.", "<b>Lista.</b> Sub „Patru reguli de siguranță digitală” sunt 4 rânduri cu reguli. Selectează-le: ții apăsat butonul stâng al mouse-ului la începutul primului rând și tragi până la sfârșitul ultimului. Apoi, în fila <b>Pornire</b>, apasă butonul <b>Marcatori</b> (Bullets), cel cu trei puncte și trei linii."], "ghiduri": ["G3"]}, {"titlu": "Tabelul, cuprinsul și numărul paginii", "minute": 25, "pasi": ["<b>Tabelul.</b> Sub „Cui te adresezi” sunt 4 rânduri în care informațiile sunt despărțite prin punct și virgulă (;). Selectează-le pe toate 4.", "Mergi la <b>Inserare</b> (Insert) → <b>Tabel</b> (Table) → <b>Conversie text în tabel…</b> (Convert Text to Table…). În fereastra care apare, la <b>Separare text la</b> (Separate text at) alege <b>Altele</b> (Other) și scrie <code>;</code> în căsuță. Apasă <b>OK</b>. Gata: ai un tabel cu 3 coloane și 4 rânduri.", "Cu cursorul în tabel, sus apare fila <b>Proiectare tabel</b> (Table Design). Alege orice stil din galerie, ca primul rând (antetul) să se vadă diferit.", "<b>Cuprinsul.</b> Dă click la sfârșitul titlului documentului și apasă <code>Enter</code>, ca să faci un rând gol sub el. Mergi la <b>Referințe</b> (References) → <b>Cuprins</b> (Table of Contents) → <b>Tabel automat 1</b> (Automatic Table 1). Apar cele 4 titluri.", "<b>Numărul paginii.</b> <b>Inserare</b> (Insert) → <b>Număr de pagină</b> (Page Number) → <b>Sfârșitul paginii</b> (Bottom of Page) → alege varianta cu numărul <b>la mijloc</b>. Apoi apasă <b>Închidere antet și subsol</b> (Close Header and Footer).", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Schimbă un stil o singură dată, pentru tot documentul", "pasi": ["În caseta <b>Stiluri</b>, click dreapta pe <b>Titlu 1</b> → <b>Modificare…</b> (Modify…). Alege altă culoare și apasă <b>OK</b>. Toate cele 4 titluri se schimbă deodată: asta e puterea stilurilor.", "Schimbă textul unui titlu (de exemplu „Programul” → „Programul de lucru”). Apoi click în cuprins → <b>Actualizare tabel</b> (Update Table) → <b>Actualizare întreg tabelul</b> → <b>OK</b>. Cuprinsul se corectează singur.", "Salvează documentul și ca PDF (ghidul <b>G4</b>). Deschide PDF-ul: rândurile din cuprins sunt linkuri pe care poți da click."]}, "verifica": ["Primul rând are stilul <b>Titlu</b>, iar cele 4 capitole stilul <b>Titlu 1</b> (le vezi toate 4 în Panoul de navigare).", "Cele 4 reguli sunt o listă cu marcatori.", "Sub „Cui te adresezi” ai un tabel cu 3 coloane și 4 rânduri (cu antet).", "Sub titlu ai un cuprins automat cu 4 rânduri, iar jos pe pagină numărul paginii."], "rez": {"intro": "Rezolvarea are două părți: <b>cum trebuie să arate</b> documentul la final și <b>de ce</b> fiecare pas se face așa. Lângă rezolvare găsești și documentul-model (<code>Model_E14_Word.docx</code>), pe care îl poți deschide și compara cu al tău.", "parti": [{"titlu": "Cum arată documentul la final", "html": "<div class='tw'><table><thead><tr><th scope='col'>Rândul / partea</th><th scope='col'>Stil sau element</th><th scope='col'>Cum verifici</th></tr></thead><tbody><tr><td>Ghidul noului coleg de la casa de bilete</td><td>Titlu (Title)</td><td>Click pe rând: în caseta Stiluri e evidențiat „Titlu”</td></tr><tr><td>Cuprins (sub titlu)</td><td>Cuprins automat (Tabel automat 1)</td><td>Are 4 rânduri, cu numărul paginii la dreapta</td></tr><tr><td>Despre birou</td><td>Titlu 1 (Heading 1)</td><td>Apare în Panoul de navigare</td></tr><tr><td>Programul</td><td>Titlu 1</td><td>Apare în Panoul de navigare</td></tr><tr><td>Cui te adresezi</td><td>Titlu 1 + tabel 3 × 4 sub el</td><td>Tabelul are antetul: Problema · Cui te adresezi · Cum</td></tr><tr><td>Patru reguli de siguranță digitală</td><td>Titlu 1 + listă cu 4 marcatori</td><td>Fiecare regulă începe cu un punct (•)</td></tr><tr><td>Subsolul paginii</td><td>Număr de pagină, la mijloc</td><td>Jos pe pagină apare „1”</td></tr></tbody></table></div>"}, {"titlu": "Tabelul (conținutul exact)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Problema</th><th scope='col'>Cui te adresezi</th><th scope='col'>Cum</th></tr></thead><tbody><tr><td>Nu merge imprimanta</td><td>Radu Ilie (IT)</td><td>telefon interior 214</td></tr><tr><td>Nu știi un tarif</td><td>Elena Stan</td><td>mesaj pe Teams</td></tr><tr><td>Vrei să schimbi o tură</td><td>Ana Rusu</td><td>e-mail, cu o zi înainte</td></tr></tbody></table></div><p><b>De ce „Conversie text în tabel” și nu desenat de mână:</b> datele erau deja scrise, despărțite prin <code>;</code>. Word le pune singur în coloane, fără să rescrii nimic și fără greșeli.</p>"}, {"titlu": "Lista (conținutul exact)", "html": "<p>• Blochează calculatorul când pleci de la birou (<code>Windows</code> + <code>L</code>).</p><p>• Nu spune nimănui parola, nici colegilor.</p><p>• Nu deschide atașamente de la expeditori pe care nu-i cunoști.</p><p>• Anunță imediat IT-ul dacă ceva ți se pare suspect.</p>"}, {"titlu": "Greșeli frecvente și cum le repari", "html": "<p><b>„Am făcut titlurile mai mari și îngroșate, dar nu apar în cuprins.”</b> Ai schimbat doar aspectul, nu stilul. Dă click pe titlu și apasă <b>Titlu 1</b>.</p><p><b>„Tabelul a ieșit cu o singură coloană.”</b> La conversie nu ai ales <code>;</code> ca separator. Apasă <code>Ctrl</code> + <code>Z</code> și refă pasul, cu <b>Altele: ;</b>.</p><p><b>„Cuprinsul arată «Nu s-au găsit intrări de cuprins».”</b> Niciun rând nu are stilul Titlu 1. Pune stilurile, apoi <b>Actualizare tabel</b>.</p><p><b>„Numărul paginii a apărut sus.”</b> Ai ales <b>Începutul paginii</b>. <code>Ctrl</code> + <code>Z</code> și alege <b>Sfârșitul paginii</b>.</p>"}]}, "glume": ["Un document fără titluri e ca o gară fără panouri: ajungi, dar nu știi pe ce linie."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Titlurile și lista", 20], ["Cerința 2 – Tabelul, cuprinsul și numărul paginii", 25], ["Pas în plus – Schimbă un stil o singură dată, pentru tot documentul", 45], ["Întrebări și discuție", 15]]}, {"cod": "E15", "titlu": "PowerPoint: 5 diapozitive pe temă dată", "statut": "rec", "nota": null, "ore": [19], "suport": "secț. 3, pg. 42-43", "org": "Studii crearea de conținut digital", "vechi": "T10", "zi": 8, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-13", "sg2": "2026-11-05", "teorie": [{"zi": 5, "ora": 19, "titlu": "Conținut digital: Word și PowerPoint"}], "gata": true, "fisa": "fise/Fisa_E15_PowerPoint.docx", "rez_doc": "fise/Rezolvare_E15_PowerPoint.docx", "pornire_var": [], "pornire": null, "pornire_desc": null, "model": ["fise/Model_E15_Prezentare.pptx"], "fisier": "E15_Prezentare_Nume_Prenume.pptx", "subiect": "E15 – Prezentare – Nume Prenume", "predare_obl": false, "pe_scurt": "Faci o prezentare scurtă, de <b>5 diapozitive</b>, cu tema „<b>O zi fără hârtie la birou</b>”. Textul îl primești gata scris: tu îl așezi frumos, alegi o temă de design, adaugi o imagine cu <b>text alternativ</b> și <b>note pentru vorbitor</b>, apoi o rulezi. Miezul exercițiului: <b>cam 40 de minute</b>.", "recap": ["Un diapozitiv = <b>o idee</b>. Cel mult 3–4 rânduri scurte, nu paragrafe.", "Text <b>mare</b> (corpul de cel puțin 20 pt), <b>contrast</b> bun (text închis pe fond deschis sau invers), <b>un singur font</b>.", "<b>Textul alternativ</b> descrie imaginea pentru cine nu o vede (cititor de ecran). <b>Notele pentru vorbitor</b> sunt pentru tine, nu se văd pe ecranul sălii."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Diapozitiv</th><th scope='col'>Titlu</th><th scope='col'>Text (câte un rând pentru fiecare marcator)</th></tr></thead><tbody><tr><td>1</td><td>O zi fără hârtie la birou</td><td>Numele tău (ca subtitlu)</td></tr><tr><td>2</td><td>De ce?</td><td>Mai puțină hârtie și toner · Documentele se găsesc mai repede · Mai puțin de arhivat</td></tr><tr><td>3</td><td>Ce facem în loc de tipărit</td><td>Citim pe ecran și comentăm în document · Trimitem PDF, nu foi scanate · Păstrăm fișierele într-un singur loc</td></tr><tr><td>4</td><td>Ce tipărim totuși</td><td>Ce cere procedura pe hârtie · Anunțurile pentru călători · Doar paginile necesare, față-verso</td></tr><tr><td>5</td><td>Încercăm o zi?</td><td>Alegem o zi pe săptămână · Numărăm foile economisite · Spunem ce a mers și ce nu</td></tr></tbody></table></div>", "cerinte": [{"titlu": "Cele 5 diapozitive", "minute": 25, "pasi": ["Deschide <b>PowerPoint</b> → <b>Prezentare necompletată</b> (Blank Presentation). Salvează imediat ca <code>E15_Prezentare_Nume_Prenume.pptx</code> (ghidul <b>G3</b>).", "Primul diapozitiv e deja de tip <b>Diapozitiv titlu</b> (Title Slide). Click în caseta mare și scrie titlul. În caseta mică scrie numele tău.", "Pentru diapozitivul 2: <b>Pornire</b> (Home) → săgeata de sub <b>Diapozitiv nou</b> (New Slide) → <b>Titlu și conținut</b> (Title and Content). Scrie titlul sus, iar în caseta de jos cele 3 rânduri. După fiecare rând apeși <code>Enter</code>, ca să apară un marcator nou.", "Repetă pentru diapozitivele 3, 4 și 5, cu textul din tabelul de mai sus.", "Alege un aspect: fila <b>Proiectare</b> (Design) → click pe o <b>temă</b> din galerie. Alege una cu <b>contrast bun</b> (litere închise pe fond deschis sau invers).", "Verifică mărimea textului: click pe un rând din corp → în <b>Pornire</b> vezi mărimea (de exemplu 28). Trebuie să fie <b>cel puțin 20</b>."], "ghiduri": ["G3"]}, {"titlu": "Imaginea, notele și rularea", "minute": 15, "pasi": ["Pe diapozitivul 2: <b>Inserare</b> (Insert) → <b>Pictograme</b> (Icons) → caută „frunză” sau „document” → alege una → <b>Inserare</b>. Dacă nu ai Pictograme: <b>Inserare</b> → <b>Forme</b> (Shapes) și desenează o formă simplă.", "Click dreapta pe imagine → <b>Vizualizare text alternativ…</b> sau <b>Editare text alternativ…</b> (View/Edit Alt Text). Scrie ce arată, de exemplu: „Pictogramă: o frunză verde”.", "Pe diapozitivul 3, jos, sub diapozitiv, e zona <b>Note</b> (Notes). Dacă nu o vezi, apasă <b>Note</b> în bara de jos. Scrie 2 propoziții pe care le-ai spune colegilor, de exemplu: „Un PDF se deschide pe orice calculator. O foaie scanată nu se poate căuta.”", "Apasă <code>F5</code>: prezentarea pornește pe tot ecranul. Treci de la un diapozitiv la altul cu săgeata <code>→</code> sau cu click. La final apasă <code>Esc</code>.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Tranziție și PDF", "pasi": ["Fila <b>Tranziții</b> (Transitions) → alege <b>Estompare</b> (Fade) → <b>Se aplică la toate</b> (Apply To All). Simplu și discret: nu alege efecte care se rotesc sau sar.", "Salvează prezentarea și ca PDF (ghidul <b>G4</b>). Un PDF se deschide pe orice calculator, chiar fără PowerPoint.", "Rulează <b>Revizuire</b> (Review) → <b>Verificare accesibilitate</b> (Check Accessibility), ghidul <b>G7</b>. Dacă nu ai pus text alternativ, apare aici."]}, "verifica": ["5 diapozitive, fiecare cu titlu, primul cu numele tău.", "Pe diapozitivele 2–5, câte 3 rânduri cu marcatori, fără paragrafe lungi.", "Textul din corp are cel puțin 20 pt și se citește bine pe fondul ales.", "Imaginea de pe diapozitivul 2 are text alternativ, iar diapozitivul 3 are note pentru vorbitor.", "Ai rulat prezentarea cu <code>F5</code>."], "rez": {"intro": "Prezentarea-model e în fișierul <code>Model_E15_Prezentare.pptx</code>. Deschide-l, apasă <code>F5</code> și compară. Tema de design poate fi alta la tine. Contează <b>structura</b>, <b>mărimea textului</b>, <b>contrastul</b>, <b>textul alternativ</b> și <b>notele</b>.", "parti": [{"titlu": "Structura corectă", "html": "<div class='tw'><table><thead><tr><th scope='col'>Diapozitiv</th><th scope='col'>Aspect (layout)</th><th scope='col'>Ce conține</th></tr></thead><tbody><tr><td>1</td><td>Diapozitiv titlu</td><td>„O zi fără hârtie la birou” + numele tău</td></tr><tr><td>2</td><td>Titlu și conținut</td><td>„De ce?” + 3 marcatori + pictogramă cu text alternativ</td></tr><tr><td>3</td><td>Titlu și conținut</td><td>„Ce facem în loc de tipărit” + 3 marcatori + note pentru vorbitor</td></tr><tr><td>4</td><td>Titlu și conținut</td><td>„Ce tipărim totuși” + 3 marcatori</td></tr><tr><td>5</td><td>Titlu și conținut</td><td>„Încercăm o zi?” + 3 marcatori</td></tr></tbody></table></div>"}, {"titlu": "De ce așa", "html": "<p><b>Layout-ul „Titlu și conținut”</b> pune titlul într-o casetă de titlu adevărată. Cititoarele de ecran și cuprinsul prezentării o recunosc. Dacă scrii titlul într-o casetă text oarecare, prezentarea „nu are titlu” pentru ele.</p><p><b>Text alternativ bun</b> = ce arată imaginea, pe scurt: „Pictogramă: o frunză verde”. <b>Nu</b> „imagine” sau „poza1.png”.</p><p><b>Note bune</b> = ce spui tu, nu ce e deja scris pe diapozitiv. Exemplu: „Un PDF se deschide pe orice calculator și păstrează aspectul. O foaie scanată e doar o poză: nu se poate căuta în ea.”</p>"}, {"titlu": "Greșeli frecvente", "html": "<p><b>Toate cele 3 idei pe un singur rând, cu virgule.</b> Apasă <code>Enter</code> după fiecare idee, ca să ai 3 marcatori.</p><p><b>Textul s-a micșorat singur la 14–16.</b> PowerPoint micșorează textul când nu încape. Șterge cuvintele în plus sau mărește caseta.</p><p><b>Nu găsesc Pictograme.</b> Unele versiuni de Office nu le au. Folosește <b>Forme</b>: și o formă are nevoie de text alternativ, dacă poartă un înțeles.</p>"}]}, "glume": ["Regula 1-3-20: o idee, trei rânduri, cel puțin 20 de puncte. Și zero animații care se învârt."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Cele 5 diapozitive", 25], ["Cerința 2 – Imaginea, notele și rularea", 15], ["Pas în plus – Tranziție și PDF", 50], ["Întrebări și discuție", 15]]}, {"cod": "E16", "titlu": "PowerPoint: repară o prezentare dezorganizată", "statut": "rec", "nota": null, "ore": [19, 17], "suport": "secț. 3, pg. 42-43", "org": "—", "vechi": "T10", "zi": 8, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-13", "sg2": "2026-11-05", "teorie": [{"zi": 5, "ora": 19, "titlu": "Conținut digital: Word și PowerPoint"}, {"zi": 5, "ora": 17, "titlu": "Accesibilitate, incluziune și colaborare la distanță"}], "gata": true, "fisa": "fise/Fisa_E16_PowerPoint.docx", "rez_doc": "fise/Rezolvare_E16_PowerPoint.docx", "pornire_var": [], "pornire": "fise/E16_Prezentare_PORNIRE.pptx", "pornire_desc": "Prezentarea „stricată”, cu 5 diapozitive, plus diapozitivul 6, „Ce am reparat”, cu un tabel gol.", "model": ["fise/Model_E16_Prezentare.pptx"], "fisier": "E16_Reparat_Nume_Prenume.pptx", "subiect": "E16 – Prezentare reparată – Nume Prenume", "predare_obl": false, "pe_scurt": "Un coleg a făcut în grabă o prezentare despre <b>imprimanta comună</b> și ți-a cerut s-o „repari”. Are <b>7 probleme</b>: greșeli de scriere, lipsa diacriticelor, un perete de text, un diapozitiv fără titlu, contrast slab, litere prea mici și fonturi amestecate. Le <b>găsești</b>, le <b>notezi</b> și le <b>repari</b>. Miezul: <b>cam 40 de minute</b>.", "recap": ["Pe un diapozitiv: <b>o idee</b>, cel mult 3–4 rânduri scurte, text de cel puțin <b>20 pt</b>, <b>un singur font</b>.", "<b>Contrastul</b>: text închis pe fond deschis sau invers. Roșu pe verde e greu de citit pentru oricine și imposibil pentru unii daltoniști.", "<b>Fiecare diapozitiv are titlu</b>. Fără titlu, un cititor de ecran nu poate spune unde ești, iar <b>Verificare accesibilitate</b> îl semnalează."], "text_dat": "", "cerinte": [{"titlu": "Găsește cele 7 probleme", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, deschide-l, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E16_Reparat_Nume_Prenume.pptx</code> (ghidul <b>G3</b>).", "Ia diapozitivele la rând, de la 1 la 5. La fiecare întreabă-te: <b>se citește ușor? e scris corect? are titlu? are prea mult text? literele sunt destul de mari? fontul e același peste tot?</b>", "Ca să afli <b>mărimea</b> și <b>fontul</b> unui text: dai click în text și te uiți în fila <b>Pornire</b> (Home), la cele două căsuțe din stânga sus (de exemplu „Arial” și „28”).", "Mergi la diapozitivul 6, „Ce am reparat”. Click în tabel și completează câte un rând pentru fiecare problemă: <b>Diapozitivul</b> · <b>Problema</b> · <b>Cum am reparat</b>. Ai 7 rânduri."], "ghiduri": ["G3"]}, {"titlu": "Repară-le", "minute": 20, "pasi": ["<b>Greșeli de scriere și diacritice:</b> corectează cuvintele direct în text. Ca ajutor, apasă <code>F7</code>: PowerPoint îți arată cuvintele pe care nu le recunoaște.", "<b>Peretele de text (diapozitivul 2):</b> șterge paragraful lung și scrie în loc <b>4 idei scurte</b>, câte una pe rând, cu <code>Enter</code> după fiecare.", "<b>Diapozitivul fără titlu (3):</b> <b>Pornire</b> → <b>Aspect</b> (Layout) → <b>Titlu și conținut</b>. Scrie un titlu, de exemplu „Ce tipărim”.", "<b>Contrastul (3):</b> selectează textul roșu → <b>Pornire</b> → <b>Culoare font</b> (Font Color) → negru. Apoi click dreapta pe fundal → <b>Formatare fundal</b> (Format Background) → <b>Umplere solidă</b> (Solid fill) → alb (sau o culoare foarte deschisă).", "<b>Litere mici (4):</b> selectează textul → în căsuța de mărime scrie <code>24</code> → <code>Enter</code>.", "<b>Fonturile amestecate:</b> pe fiecare diapozitiv selectează tot textul (<code>Ctrl</code> + <code>A</code> în casetă) și alege <b>același font</b> peste tot, de exemplu <b>Calibri</b> sau <b>Arial</b>.", "Rulează cu <code>F5</code> și verifică tot. Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Verificare accesibilitate", "pasi": ["Fila <b>Revizuire</b> (Review) → <b>Verificare accesibilitate</b> (Check Accessibility), ghidul <b>G7</b>. Rulează-o întâi pe <b>fișierul de pornire</b> (îl redeschizi) și apoi pe <b>fișierul tău reparat</b>.", "Notează pe diapozitivul 6, sub tabel: câte <b>erori</b> și <b>avertismente</b> apăreau înainte și câte după."]}, "verifica": ["Tabelul de pe diapozitivul 6 are 7 rânduri: problemă + reparație.", "Nu mai există „Prezentrae”, „imediiat” și cuvinte fără diacritice.", "Diapozitivul 2 are 4 idei scurte, nu un paragraf.", "Diapozitivul 3 are titlu și text închis pe fond deschis.", "Textul de pe diapozitivul 4 are cel puțin 24 pt, iar toată prezentarea folosește un singur font."], "rez": {"intro": "Aici ai <b>toate cele 7 probleme</b>, unde sunt și cum se repară, plus textul corect. Prezentarea reparată e în fișierul <code>Model_E16_Prezentare.pptx</code>.", "parti": [{"titlu": "Cele 7 probleme și reparațiile", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Diapozitiv</th><th scope='col'>Problema</th><th scope='col'>Cum se repară</th></tr></thead><tbody><tr><td>1</td><td>1 și 5</td><td>Greșeli de tastare: „Prezentrae”, „imediiat”</td><td>„Prezentare”, „imediat” (ajutor: tasta F7)</td></tr><tr><td>2</td><td>toate</td><td>Lipsesc diacriticele: „comuna”, „Tipariti”, „Intrebari”, „Scrieti-ne”, „afla”, „langa” etc.</td><td>„comună”, „Tipăriți”, „Întrebări”, „Scrieți-ne”, „află”, „lângă”</td></tr><tr><td>3</td><td>2</td><td>Perete de text: un singur paragraf lung</td><td>4 idei scurte, câte una pe rând (vezi mai jos)</td></tr><tr><td>4</td><td>3</td><td>Diapozitivul nu are titlu</td><td>Aspect „Titlu și conținut” + titlul „Ce tipărim”</td></tr><tr><td>5</td><td>3</td><td>Text roșu pe fundal verde: contrast slab</td><td>Text negru pe fundal alb (sau foarte deschis)</td></tr><tr><td>6</td><td>4</td><td>Litere prea mici: 12 pt</td><td>Cel puțin 24 pt</td></tr><tr><td>7</td><td>1, 2, rest</td><td>Fonturi amestecate: Comic Sans, Times New Roman, Arial</td><td>Un singur font peste tot (de exemplu Calibri)</td></tr></tbody></table></div>"}, {"titlu": "Textul corect, diapozitiv cu diapozitiv", "html": "<p><b>1.</b> Prezentare: imprimanta comună</p><p><b>2.</b> Reguli: • Imprimanta e pe hol, lângă sala de ședințe. • Dacă se blochează hârtia, nu trage de ea cu forța. • Deschide capacul din față și urmează desenul de pe capac. • Anunță colegul de la IT pe chat.</p><p><b>3.</b> Ce tipărim: • Tipăriți doar ce e necesar. • Folosiți față-verso.</p><p><b>4.</b> Toner: • Când tonerul e pe terminate, apare un mesaj pe ecran. • Anunțați IT-ul imediat. • Nu scuturați cartușul.</p><p><b>5.</b> Întrebări? • Scrieți-ne imediat pe chat.</p>"}, {"titlu": "Greșeli frecvente", "html": "<p><b>Am mărit doar titlul diapozitivului 4.</b> Problema era textul din corp (12 pt). Selectează textul de sub titlu.</p><p><b>Am pus titlul într-o casetă text nouă.</b> Arată ca un titlu, dar PowerPoint nu-l vede ca titlu. Folosește <b>Aspect → Titlu și conținut</b>.</p><p><b>Am schimbat doar culoarea textului.</b> Fundalul verde rămâne obositor. Schimbă și fundalul.</p>"}, {"titlu": "Pas în plus – ce arată Verificare accesibilitate", "html": "<p>Pe fișierul de pornire apare cel puțin eroarea <b>„Titlu lipsă”</b> la diapozitivul 3 și, de obicei, un avertisment despre <b>contrast</b> sau <b>ordinea de citire</b>. Pe fișierul reparat eroarea de titlu dispare. Numărul exact poate să difere de la o versiune de Office la alta.</p>"}]}, "glume": ["Comic Sans la o prezentare de birou e ca papucii la ședință: comozi, dar toată lumea se uită."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Găsește cele 7 probleme", 20], ["Cerința 2 – Repară-le", 20], ["Pas în plus – Verificare accesibilitate", 50], ["Întrebări și discuție", 15]]}, {"cod": "E17", "titlu": "Export PDF: din Word în PDF, corect, cu verificare", "statut": "rec", "nota": null, "ore": [21], "suport": "secț. 3, pg. 40-41", "org": "—", "vechi": "T11", "zi": 9, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-14", "sg2": "2026-11-06", "teorie": [{"zi": 6, "ora": 21, "titlu": "Export PDF și partajare pe OneDrive"}], "gata": true, "fisa": "fise/Fisa_E17_Export_PDF.docx", "rez_doc": "fise/Rezolvare_E17_Export_PDF.docx", "pornire_var": [], "pornire": "fise/E17_Anunt_PORNIRE.docx", "pornire_desc": "Un anunț de o pagină, cu un tabel și un link, plus o pagină goală la final.", "model": [], "fisier": "E17_Anunt_Nume_Prenume.pdf", "subiect": "E17 – Anunț PDF – Nume Prenume", "predare_obl": false, "pe_scurt": "Ai un anunț de o pagină, care are la final o <b>pagină goală</b> rămasă din greșeală. Scoți pagina goală, salvezi documentul ca <b>PDF</b> și verifici PDF-ul înainte să-l trimiți. La final faci vizibile <b>extensiile</b> fișierelor (.docx, .pdf), ca să le deosebești. Miezul: <b>cam 35 de minute</b>.", "recap": ["<b>PDF-ul</b> arată la fel pe orice calculator și telefon și nu se modifică din greșeală. E formatul potrivit când <b>trimiți</b> un document. Formatul <b>.docx</b> e pentru când lucrezi la el.", "Înainte să trimiți un PDF, îl <b>deschizi și îl verifici</b>: număr de pagini, diacritice, tabele întregi, linkuri care merg.", "Windows ascunde implicit <b>extensia</b> (ultima parte a numelui: <code>.docx</code>, <code>.pdf</code>). O faci vizibilă ca să știi exact ce fișier trimiți."], "text_dat": "", "cerinte": [{"titlu": "Scoate pagina goală", "minute": 15, "pasi": ["Descarcă <b>fișierul de pornire</b>, deschide-l și apasă <b>Activare editare</b> dacă apare bara galbenă. Derulează în jos: după anunț urmează o <b>pagină goală</b>.", "Apasă butonul <b>¶</b> (Afișare/Ascundere ¶, în fila <b>Pornire</b>) sau <code>Ctrl</code> + <code>Shift</code> + <code>8</code>. Apar semne care de obicei nu se văd: fiecare <b>¶</b> e un <code>Enter</code>, iar linia punctată „<b>Sfârșit de pagină</b>” (Page Break) mută textul pe pagina următoare.", "Dă click imediat <b>înaintea</b> primului ¶ gol de sub semnătură, ține apăsat <code>Shift</code> și apasă <code>Ctrl</code> + <code>End</code> (selectezi tot ce e până la final). Apasă <code>Delete</code>.", "Apasă din nou <b>¶</b> ca să ascunzi semnele. Verifică: <b>Fișier</b> (File) → <b>Imprimare</b> (Print). În dreapta vezi previzualizarea: trebuie să scrie <b>1 din 1</b> (o singură pagină). Apasă săgeata din stânga sus ca să te întorci."], "ghiduri": []}, {"titlu": "Salvează ca PDF și verifică-l", "minute": 20, "pasi": ["<b>Fișier</b> → <b>Salvare ca</b> → <b>Răsfoire</b> → la <b>Tip fișier</b> alegi <b>PDF</b> → numele <code>E17_Anunt_Nume_Prenume</code> → <b>Salvare</b> (ghidul <b>G4</b>).", "Deschide PDF-ul (dublu click pe el, în <b>Documente</b>). Verifică <b>4 lucruri</b>: are <b>o singură pagină</b>; diacriticele (ă, â, î, ș, ț) apar corect; <b>tabelul</b> e întreg; <b>linkul</b> e albastru și se poate apăsa.", "Fă extensiile vizibile: deschide Explorer (<code>Windows</code> + <code>E</code>) → <b>Documente</b>. Sus: pe Windows 11 <b>Vizualizare</b> (View) → <b>Afișare</b> (Show) → bifează <b>Extensii nume fișier</b> (File name extensions). Pe Windows 10: fila <b>Vizualizare</b> → bifează <b>Extensii nume fișier</b>.", "Acum vezi două fișiere cu același nume și extensii diferite: <code>….docx</code> (cel pe care îl modifici) și <code>….pdf</code> (cel pe care îl trimiți)."], "ghiduri": ["G4", "G3"]}], "in_plus": {"titlu": "Cât de mari sunt cele două fișiere?", "pasi": ["În Explorer, click dreapta pe fișierul <code>.docx</code> → <b>Proprietăți</b> (Properties) → uită-te la <b>Dimensiune</b> (Size). La fel pentru <code>.pdf</code>.", "Notează pe o foaie (sau în chat) care e mai mic. La un text simplu ca acesta, diferența e mică. La documente cu multe poze, PDF-ul poate fi mult mai mic sau mult mai mare, în funcție de cum a fost salvat."]}, "verifica": ["Documentul are o singură pagină (Fișier → Imprimare arată „1 din 1”).", "Ai un fișier <code>E17_Anunt_Nume_Prenume.pdf</code> care se deschide și arată ca documentul.", "În PDF, diacriticele sunt corecte, tabelul e întreg și linkul se poate apăsa.", "În Explorer vezi extensiile <code>.docx</code> și <code>.pdf</code>."], "rez": {"intro": "Exercițiul are un singur rezultat corect: un PDF de <b>o pagină</b>, care arată exact ca anunțul. Mai jos e explicat de ce apărea pagina goală și cum verifici totul.", "parti": [{"titlu": "De unde venea pagina goală", "html": "<p>La final erau <b>6 rânduri goale</b> (6 × ¶), apoi un <b>Sfârșit de pagină</b> și încă 2 rânduri goale. Sfârșitul de pagină „împinge” rândurile de după el pe pagina a doua, care pare goală, dar nu e.</p><p>Cu semnele ¶ vizibile vezi exact ce trebuie șters. Selecția de la primul ¶ gol până la final (<code>Shift</code> + <code>Ctrl</code> + <code>End</code>) prinde tot dintr-o mișcare.</p><div class='cadru'>Verificarea corectă: Fișier → Imprimare → „1 din 1”. Dacă scrie „1 din 2”, a mai rămas un ¶ sau sfârșitul de pagină: mai afișează o dată semnele ¶ și șterge-le.</div>"}, {"titlu": "Verificarea PDF-ului (toate 4 trebuie să fie „da”)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce verifici</th><th scope='col'>Cum arată corect</th></tr></thead><tbody><tr><td>Număr de pagini</td><td>1 pagină</td></tr><tr><td>Diacritice</td><td>„Anunț”, „sărbători”, „funcționează”, „șefa” se văd corect</td></tr><tr><td>Tabelul</td><td>4 rânduri de date + antet, pe aceeași pagină</td></tr><tr><td>Linkul</td><td>https://www.exemplu.ro/program e albastru și se poate apăsa (adresa e fictivă, deci pagina nu se deschide; contează că e link)</td></tr></tbody></table></div>"}, {"titlu": "Extensiile", "html": "<p>Cu <b>Extensii nume fișier</b> bifat, vezi <code>E17_Anunt_Nume_Prenume.docx</code> și <code>E17_Anunt_Nume_Prenume.pdf</code>. <b>De ce contează:</b> fără extensii, cele două par „același fișier de două ori” și e ușor să trimiți varianta greșită. Tot așa se vede și o păcăleală: un fișier numit <code>factura.pdf.exe</code> nu e un PDF, ci un program.</p>"}]}, "glume": ["O pagină goală la final e ca un vagon gol la coada trenului: nu încurcă pe nimeni, dar toată lumea întreabă de ce e acolo."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Scoate pagina goală", 15], ["Cerința 2 – Salvează ca PDF și verifică-l", 20], ["Pas în plus – Cât de mari sunt cele două fișiere?", 55], ["Întrebări și discuție", 15]]}, {"cod": "E18", "titlu": "OneDrive: partajare corectă", "statut": "rec", "nota": null, "ore": [21], "suport": "secț. 3, pg. 40-41", "org": "—", "vechi": "T11", "zi": 9, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-14", "sg2": "2026-11-06", "teorie": [{"zi": 6, "ora": 21, "titlu": "Export PDF și partajare pe OneDrive"}], "gata": true, "fisa": "fise/Fisa_E18_OneDrive.docx", "rez_doc": "fise/Rezolvare_E18_OneDrive.docx", "pornire_var": [], "pornire": "fise/E18_Partajare_PORNIRE.docx", "pornire_desc": "Tabelul cu cele 6 situații, de completat.", "model": [], "fisier": "E18_Partajare_Nume_Prenume.docx", "subiect": "E18 – Partajare – Nume Prenume", "predare_obl": false, "pe_scurt": "Două întrebări la orice partajare: <b>cine</b> poate deschide linkul și <b>ce poate face</b> (doar să vadă sau și să modifice). Alegi accesul corect pentru <b>6 situații</b>, apoi partajezi de-adevăratelea un fișier din OneDrive, cu acces doar de vizualizare. Miezul: <b>cam 35 de minute</b>.", "recap": ["<b>Cine:</b> <b>Persoane specifice</b> (doar cine scrii tu) · <b>Persoane din organizație</b> (toți colegii din firmă, cu contul de serviciu) · <b>Oricine are linkul</b> (oricine primește linkul, chiar dacă îl dă mai departe).", "<b>Ce poate face:</b> <b>Poate vizualiza</b> (doar citește) sau <b>Poate edita</b> (modifică). Pornești mereu de la <b>vizualizare</b>.", "Accesul se verifică și se oprește oricând: <b>Gestionare acces</b> (Manage access)."], "text_dat": "", "cerinte": [{"titlu": "Cine și ce poate face: 6 situații", "minute": 15, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> și salvează-l ca <code>E18_Partajare_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Pentru fiecare situație, întreabă-te întâi: <b>cine trebuie</b> să ajungă la fișier, nimeni în plus? Apoi: <b>trebuie să modifice</b> sau doar să citească?", "Completează cele 3 coloane goale. Pentru „De ce” ajunge o propoziție scurtă.", "Atenție la situația 6: acolo nu alegi un acces nou, ci scrii <b>ce faci</b> ca să repari greșeala."], "ghiduri": ["G3"]}, {"titlu": "Partajează de-adevăratelea", "minute": 20, "pasi": ["Intră în <b>OneDrive</b> (onedrive.live.com cu contul personal, sau OneDrive-ul de la serviciu) și încarcă un fișier oarecare: de exemplu PDF-ul de la E17. Pe web: <b>Adăugare nouă</b> (Add new) / <b>Încărcare</b> (Upload) → <b>Fișiere</b>.", "Partajează fișierul <b>doar cu vizualizare</b>, către <b>o singură persoană</b>: tu însuți pe altă adresă, un coleg care e de acord sau formatorul (<code>bogdan@pandapc.ro</code>). Pașii exacți sunt în ghidul <b>G9</b>.", "Deschide <b>Gestionare acces</b> (Manage access) și fă o <b>captură</b> (ghidul <b>G1</b>). Lipește-o în documentul tău (ghidul <b>G2</b>). În captură trebuie să se vadă persoana și „Poate vizualiza”.", "Dacă la serviciu partajarea în afara firmei e <b>blocată</b>, nu e greșeala ta: fă o captură cu mesajul primit. Asta e răspunsul corect pentru pasul ăsta.", "Salvează documentul (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": ["G9", "G1", "G2"]}], "in_plus": {"titlu": "Retrage accesul", "pasi": ["Din <b>Gestionare acces</b>, scoate persoana adăugată (săgeata de lângă nume → <b>Eliminare acces</b> / Stop sharing).", "Verifică din nou: lista trebuie să arate doar numele tău. Așa repari, în viața reală, un link trimis greșit."]}, "verifica": ["Toate cele 6 rânduri au „cine”, „ce poate face” și „de ce”.", "Nicio situație cu date personale (CNP, adrese) nu are „Oricine are linkul”.", "Ai o captură cu „Gestionare acces”, cu o singură persoană și „Poate vizualiza” (sau captura cu mesajul de blocare)."], "rez": {"intro": "Primele 5 situații au un singur răspuns corect, iar a șasea are o succesiune corectă de pași. Dacă „de ce”-ul tău spune același lucru cu alte cuvinte, e corect.", "parti": [{"titlu": "Cele 6 situații", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Cine</th><th scope='col'>Ce poate face</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>1</td><td>Persoane specifice (cei 4 colegi)</td><td>Poate vizualiza</td><td>Doar ei au nevoie, și doar să citească. Nimeni nu trebuie să modifice o minută deja scrisă.</td></tr><tr><td>2</td><td>Persoane specifice (cei 5 din echipă)</td><td>Poate edita</td><td>Lucrează împreună în același fișier, deci toți trebuie să poată scrie; restul firmei nu are ce căuta acolo.</td></tr><tr><td>3</td><td>Persoane din organizația mea</td><td>Poate vizualiza</td><td>Toți angajații trebuie să-l vadă, dar nu și cei din afara firmei; nimeni nu trebuie să-l modifice.</td></tr><tr><td>4</td><td>Persoane specifice (doar cine lucrează la personal)</td><td>Poate vizualiza (sau edita, doar pentru cine îl actualizează)</td><td>Sunt date personale: acces doar pentru cine are nevoie, niciodată prin „oricine are linkul”.</td></tr><tr><td>5</td><td>Oricine are linkul</td><td>Poate vizualiza</td><td>E public și nu are date personale; dacă ai opțiunea, pui și o dată de expirare.</td></tr><tr><td>6</td><td>—</td><td>—</td><td>Imediat: Gestionare acces → ștergi linkul trimis (sau îl treci pe „Poate vizualiza”); verifici în Istoricul versiunilor dacă a modificat cineva fișierul; trimiți în grup un link nou, doar de vizualizare.</td></tr></tbody></table></div><div class='cadru'>Regula de aur: pornești de la cel mai puțin acces (persoane specifice + vizualizare) și dai mai mult doar dacă e nevoie.</div>"}, {"titlu": "Partajarea reală – cum arată corect", "html": "<p>În <b>Gestionare acces</b> apare o singură persoană (sau adresa ta secundară), cu <b>Poate vizualiza</b>. Dacă scrie „Poate edita”, apasă pe text și schimbă în <b>Poate vizualiza</b>.</p><p><b>Dacă la serviciu ai primit un mesaj că nu poți partaja în afara organizației:</b> e o regulă de securitate a firmei, pusă de IT. Captura cu mesajul e răspunsul corect.</p><p><b>Bine de știut:</b> la <b>Persoane specifice</b> nu ai parolă și dată de expirare. Acestea apar doar la „Oricine are linkul”, și doar pe unele conturi.</p>"}]}, "glume": ["Un link „Oricine poate edita” trimis pe grupul de WhatsApp e ca o cheie lăsată în ușa biroului, cu bilet: «intrați, e deschis»."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Cine și ce poate face: 6 situații", 15], ["Cerința 2 – Partajează de-adevăratelea", 20], ["Pas în plus – Retrage accesul", 55], ["Întrebări și discuție", 15]]}, {"cod": "E19", "titlu": "Parole: evaluează 8 parole + construiește o parolă-frază", "statut": "rec", "nota": null, "ore": [23], "suport": "4.1, pg. 44", "org": "Studii securitate cibernetică 2", "vechi": "T13", "zi": 10, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-15", "sg2": "2026-11-09", "teorie": [{"zi": 6, "ora": 23, "titlu": "Parole, antivirus, firewall, conexiuni sigure"}], "gata": true, "fisa": "fise/Fisa_E19_Parole.docx", "rez_doc": "fise/Rezolvare_E19_Parole.docx", "pornire_var": [], "pornire": "fise/E19_Parole_PORNIRE.docx", "pornire_desc": "Tabelul cu cele 8 parole și întrebările, de completat.", "model": [], "fisier": "E19_Parole_Nume_Prenume.docx", "subiect": "E19 – Parole – Nume Prenume", "predare_obl": false, "pe_scurt": "Primești <b>8 parole</b> și spui despre fiecare dacă e <b>slabă, medie sau puternică</b>, și de ce. Apoi îți construiești o <b>parolă-frază</b> după metoda de la curs (<b>nu</b> o parolă pe care o folosești de-adevăratelea!) și răspunzi la 3 întrebări despre cum îți ții parolele. Miezul: <b>cam 35 de minute</b>.", "recap": ["<b>Lungimea contează cel mai mult.</b> O parolă de 16+ caractere din cuvinte fără legătură între ele e mai greu de spart decât una de 8 caractere „complicată”.", "<b>Nu folosești</b> nume, date de naștere, numele firmei, orașe, rânduri de taste. Astea se ghicesc primele, mai ales dacă apar pe rețelele sociale.", "<b>O parolă pentru fiecare cont.</b> Dacă un site e spart, atacatorii încearcă aceeași parolă peste tot. Plus <b>autentificare în doi pași</b> acolo unde se poate."], "text_dat": "", "cerinte": [{"titlu": "Cele 8 parole", "minute": 15, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> și salvează-l ca <code>E19_Parole_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Ia parolele la rând și pune-ți <b>3 întrebări</b>: e <b>lungă</b> (peste 12–14 caractere)? se poate <b>ghici</b> (nume, an, firmă, oraș, cuvântul „parola”, rând de taste)? e <b>ușor de ținut minte</b> pentru tine, dar greu de ghicit pentru alții?", "Scrie verdictul (slabă / medie / puternică) și motivul într-o propoziție."], "ghiduri": ["G3"]}, {"titlu": "Parola-frază și cele 3 întrebări", "minute": 20, "pasi": ["Alege <b>4 cuvinte fără legătură între ele</b>, ușor de imaginat împreună (de exemplu o imagine amuzantă). <b>Nu</b> nume din familie, <b>nu</b> date, <b>nu</b> cuvinte legate de tine.", "Leagă-le cu un semn (<code>-</code>, <code>.</code>, <code>!</code>) și adaugă <b>o cifră</b> undeva în mijloc. Numără caracterele: țintește <b>cel puțin 16</b>.", "⚠ Construiește o parolă <b>doar pentru exercițiu</b>. Nu scrie în document o parolă pe care o folosești sau o vei folosi.", "Răspunde la cele 3 întrebări din document, în 1–2 propoziții fiecare.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Unde îți ține browserul parolele", "pasi": ["În <b>Edge</b>: meniul <code>…</code> → <b>Setări</b> (Settings) → <b>Profiluri</b> (Profiles) → <b>Parole</b> (Passwords). Pe versiunile noi: <b>Portofel</b> (Wallet) → <b>Parole</b>. În <b>Chrome</b>: meniul <code>⋮</code> → <b>Manager de parole Google</b> (Google Password Manager).", "Uită-te dacă există secțiunea <b>Verificare</b> / <b>Siguranța parolelor</b> (Password Checkup): îți arată parolele <b>slabe</b>, <b>refolosite</b> sau <b>apărute în scurgeri de date</b>. Nu scrie nimic în document: e doar pentru tine."]}, "verifica": ["Toate cele 8 parole au verdict și motiv.", "Parola ta-frază are cel puțin 16 caractere, 4 cuvinte fără legătură și cel puțin o cifră.", "Ai răspuns la cele 3 întrebări.", "În document <b>nu</b> e nicio parolă pe care o folosești de-adevăratelea."], "rez": {"intro": "Verdictele de mai jos sunt cele corecte. Motivul tău poate fi spus altfel, dar trebuie să numească aceeași slăbiciune.", "parti": [{"titlu": "Partea 1 – Cele 8 parole", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Parola</th><th scope='col'>Verdict</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>1</td><td>123456</td><td>Slabă</td><td>E cea mai folosită parolă din lume; se ghicește instant.</td></tr><tr><td>2</td><td>Andreea1990</td><td>Slabă</td><td>Nume + an de naștere: informații care apar adesea pe Facebook. E chiar studiul de caz de la curs.</td></tr><tr><td>3</td><td>Parola123!</td><td>Slabă</td><td>Cuvântul „parola” + 123 + semn: e primul tipar încercat, chiar dacă „are de toate”.</td></tr><tr><td>4</td><td>CFRiasi2026</td><td>Slabă</td><td>Firmă + oraș + an: se ghicește ușor de cine știe unde lucrezi.</td></tr><tr><td>5</td><td>qwertyuiop</td><td>Slabă</td><td>Un rând de taste la rând; e în toate listele de parole sparte.</td></tr><tr><td>6</td><td>T7#kP9!z</td><td>Medie</td><td>E aleatorie, deci greu de ghicit, dar are doar 8 caractere (scurtă) și e greu de ținut minte.</td></tr><tr><td>7</td><td>cal-ceai-umbrela-tren</td><td>Puternică</td><td>21 de caractere, 4 cuvinte fără legătură: lungă și ușor de ținut minte.</td></tr><tr><td>8</td><td>Mere7!Nori&amp;Cizme+Lac</td><td>Puternică</td><td>20 de caractere, cuvinte fără legătură, cifră și semne.</td></tr></tbody></table></div><div class='cadru'>Lecția din tabel: parola 6 pare cea mai „complicată”, dar parolele 7 și 8 sunt mai bune pentru că sunt mult mai lungi și tot ușor de ținut minte.</div>"}, {"titlu": "Partea 2 – Exemplu de parolă-frază", "html": "<p>Cuvinte: <b>barcă, morcov, chitară, nor</b> → parola <code>Barca-Morcov7-Chitara-Nor</code> (25 de caractere). Imaginea care te ajută s-o ții minte: „o barcă plină de morcovi cântă la chitară pe un nor”.</p><p>⚠ Asta e doar un exemplu, publicat aici. Nu-l folosi niciodată ca parolă reală.</p>"}, {"titlu": "Partea 2 – Cele 3 întrebări", "html": "<p><b>a)</b> Dacă un singur site e spart și parola ajunge publică, atacatorii o încearcă automat pe toate celelalte conturi (e-mail, Facebook, serviciu). Cu parole diferite, pierzi un singur cont, nu pe toate.</p><p><b>b)</b> Cel mai sigur e <b>managerul de parole</b> (cel din browser sau o aplicație dedicată), protejat de parola contului și, ideal, de autentificare în doi pași. Biletul de pe monitor îl vede oricine trece pe lângă birou, iar fișierul „parole.docx” e primul lucru căutat de un virus.</p><p><b>c)</b> „Nu-ți dau parola mea, nici pentru 5 minute: tot ce se face de pe contul meu e pe numele meu. Hai să-l rugăm pe IT sau să-ți trimit eu ce ai nevoie.” Politicos, dar ferm.</p>"}]}, "glume": ["Parola ideală e ca periuța de dinți: nu o împrumuți nimănui și o schimbi dacă a umblat cineva la ea."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Cele 8 parole", 15], ["Cerința 2 – Parola-frază și cele 3 întrebări", 20], ["Pas în plus – Unde îți ține browserul parolele", 55], ["Întrebări și discuție", 15]]}, {"cod": "E20", "titlu": "Autentificare în doi pași + Securitate Windows", "statut": "rec", "nota": null, "ore": [23], "suport": "4.2-4.3, pg. 45-48", "org": "Studii securitate cibernetică", "vechi": "T13", "zi": 10, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-15", "sg2": "2026-11-09", "teorie": [{"zi": 6, "ora": 23, "titlu": "Parole, antivirus, firewall, conexiuni sigure"}], "gata": true, "fisa": "fise/Fisa_E20_Autentificare_in_doi_pasi_Securitate_Win.docx", "rez_doc": "fise/Rezolvare_E20_Autentificare_in_doi_pasi_Securitate_Win.docx", "pornire_var": [], "pornire": "fise/E20_Securitate_PORNIRE.docx", "pornire_desc": "Tabelul pentru verificarea Securității Windows și cele 5 situații, de completat.", "model": [], "fisier": "E20_Securitate_Nume_Prenume.docx", "subiect": "E20 – Securitate – Nume Prenume", "predare_obl": false, "pe_scurt": "Verifici, pe calculatorul tău, <b>Securitatea Windows</b>: antivirusul, firewallul și actualizările au bifă verde? Apoi răspunzi la <b>5 situații</b> despre <b>autentificarea în doi pași</b> și despre <b>Wi-Fi-ul public</b>. Miezul: <b>cam 35 de minute</b>.", "recap": ["<b>Antivirusul</b> (în Windows: Microsoft Defender) prinde programele rău-intenționate. <b>Firewallul</b> e „portarul” care oprește conexiunile nepoftite.", "<b>Autentificarea în doi pași (2FA):</b> pe lângă parolă, un al doilea lucru pe care doar tu îl ai (cod prin SMS, aplicație de autentificare). Codul <b>nu se dă nimănui, niciodată</b>.", "<b>Wi-Fi public</b> (gară, cafenea): fără bancă și fără parole importante. Folosește datele mobile sau hotspotul telefonului."], "text_dat": "", "cerinte": [{"titlu": "Verifică Securitatea Windows", "minute": 15, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> și salvează-l ca <code>E20_Securitate_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Apasă tasta <code>Windows</code>, scrie <b>Securitate Windows</b> (Windows Security) și apasă <code>Enter</code>. Se deschide un ecran cu mai multe pictograme.", "Uită-te la <b>Protecție împotriva virușilor și amenințărilor</b> și la <b>Firewall și protecție rețea</b>. O <b>bifă verde</b> = totul e în regulă. Un <b>semn galben sau roșu</b> = ceva are nevoie de atenție: dă click și urmează butonul propus (de exemplu <b>Activare</b>).", "Pentru actualizări: <code>Windows</code> → scrie <b>Windows Update</b> → <code>Enter</code>. Vezi dacă scrie „<b>Sunteți la zi</b>” (You're up to date) sau dacă așteaptă ceva.", "Completează tabelul. Fă o <b>captură</b> cu ecranul principal din Securitate Windows (ghidul <b>G1</b>) și lipește-o în document (ghidul <b>G2</b>).", "<b>Pe calculatorul de serviciu</b> poate scrie „<b>Gestionat de organizația dvs.</b>” (managed by your organization). E normal: setările le face IT-ul. Scrie asta în tabel și nu schimba nimic."], "ghiduri": ["G1", "G2"]}, {"titlu": "Cinci situații despre 2FA și Wi-Fi", "minute": 20, "pasi": ["Citește fiecare situație și scrie, în <b>2–3 pași scurți</b>, ce faci.", "Întreabă-te mereu: <b>cine a cerut</b> codul sau acțiunea, eu sau altcineva? Dacă nu tu ai pornit acțiunea, e un semn de pericol.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Activează autentificarea în doi pași pe e-mailul personal", "pasi": ["<b>Gmail:</b> intră în <b>Contul Google</b> (poza ta din dreapta sus → <b>Gestionați Contul Google</b>) → <b>Securitate</b> → <b>Verificare în doi pași</b> → urmezi pașii.", "<b>Outlook / Hotmail:</b> account.microsoft.com → <b>Securitate</b> (Security) → <b>Opțiuni de conectare</b> sau <b>Opțiuni avansate de securitate</b> → <b>Verificare în doi pași</b>.", "Salvează <b>codurile de rezervă</b> pe care ți le dă (le scrii pe hârtie și le pui la loc sigur, acasă). Fără ele, dacă pierzi telefonul, intri foarte greu în cont. Nu scrie nimic din acestea în document."]}, "verifica": ["Tabelul are cele 3 rânduri completate și ai lipit captura.", "La fiecare dintre cele 5 situații ai 2–3 pași.", "Niciun răspuns nu spune „dau codul” sau „aprob”."], "rez": {"intro": "Partea 1 depinde de calculatorul tău: mai jos e cum arată „corect”. Partea 2 are răspunsuri clare.", "parti": [{"titlu": "Partea 1 – Securitatea Windows: ce înseamnă ce vezi", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce vezi</th><th scope='col'>Ce înseamnă</th><th scope='col'>Ce faci</th></tr></thead><tbody><tr><td>Bifă verde</td><td>Protecția e pornită</td><td>Nimic. Scrii „bifă verde, nu e nevoie de acțiune”.</td></tr><tr><td>Semn galben</td><td>Recomandare (de exemplu o scanare veche sau o setare de verificat)</td><td>Dai click și apeși butonul propus (de exemplu „Scanare rapidă” sau „Respinge”, dacă știi că e în regulă).</td></tr><tr><td>Semn roșu</td><td>Protecție oprită sau amenințare găsită</td><td>Dai click și apeși „Activare” sau „Pornire acțiuni”. Pe calculatorul de serviciu, anunți IT-ul.</td></tr><tr><td>„Gestionat de organizația dvs.”</td><td>Setările le face IT-ul firmei</td><td>Nu schimbi nimic; e un răspuns corect în tabel.</td></tr><tr><td>Windows Update: „Sunteți la zi”</td><td>Ai ultimele actualizări</td><td>Nimic. Dacă scrie „Repornire necesară”, repornești când termini lucrul.</td></tr></tbody></table></div>"}, {"titlu": "Partea 2 – Cele 5 situații", "html": "<p><b>1) Cod prin SMS pe care nu l-ai cerut.</b> Nu-l dai nimănui. Înseamnă că cineva are deja parola ta și încearcă să intre: <b>schimbi parola imediat</b> și te uiți în setările contului la activitatea recentă (dispozitive conectate).</p><p><b>2) „Banca” îți cere codul la telefon.</b> Închizi. <b>Banca nu cere niciodată codul</b> primit prin SMS. Suni tu la numărul de pe spatele cardului și întrebi dacă e ceva în neregulă.</p><p><b>3) „Aprobați conectarea?” la 3 noaptea.</b> Apeși <b>Respingere / Nu am fost eu</b>. Cineva are parola ta: o schimbi dimineață (sau imediat) și verifici activitatea contului.</p><p><b>4) Dai telefonul vechi.</b> Înainte: muți aplicația de autentificare pe telefonul nou (sau verifici că numărul de telefon din cont e același), îți notezi codurile de rezervă, apoi <b>resetezi telefonul vechi la setările din fabrică</b>.</p><p><b>5) Plată pe Wi-Fi-ul din gară.</b> Nu folosești Wi-Fi-ul public pentru bancă. Oprești Wi-Fi-ul și folosești <b>datele mobile</b> sau hotspotul de pe telefonul tău, ori amâni plata până ajungi acasă.</p><div class='cadru'>Firul comun: dacă nu tu ai pornit acțiunea (codul, aprobarea, apelul), răspunsul e „nu”, iar pasul următor e să schimbi parola.</div>"}]}, "glume": ["Codul de 6 cifre primit prin SMS e ca periuța de dinți și parola: personal. Nici măcar «băncii» nu i-l arăți."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Verifică Securitatea Windows", 15], ["Cerința 2 – Cinci situații despre 2FA și Wi-Fi", 20], ["Pas în plus – Activează autentificarea în doi pași pe e-mailul personal", 55], ["Întrebări și discuție", 15]]}, {"cod": "E21", "titlu": "Phishing: găsește indiciile în 6 mesaje", "statut": "rec", "nota": null, "ore": [25], "suport": "4.4, pg. 48-55", "org": "Studii securitate cibernetică 1", "vechi": "T14", "zi": 11, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-16", "sg2": "2026-11-10", "teorie": [{"zi": 7, "ora": 25, "titlu": "Phishing: ce este, cele șapte indicii, apărare"}], "gata": true, "fisa": "fise/Fisa_E21_Phishing.docx", "rez_doc": "fise/Rezolvare_E21_Phishing.docx", "pornire_var": [], "pornire": "fise/E21_Phishing_PORNIRE.docx", "pornire_desc": "Cele 6 mesaje și tabelul de completat.", "model": [], "fisier": "E21_Phishing_Nume_Prenume.docx", "subiect": "E21 – Phishing – Nume Prenume", "predare_obl": false, "pe_scurt": "Primești <b>6 mesaje</b>: e-mailuri, un SMS și un WhatsApp. Spui la fiecare dacă e <b>phishing</b> sau <b>legitim</b> și ce <b>indicii</b> ai văzut, folosind lista de 10 secunde de la curs. Apoi scrii ce faci concret la două dintre ele. Miezul: <b>cam 40 de minute</b>.", "recap": ["<b>Lista de 10 secunde, înainte de click:</b> 1) E urgent? 2) Cere date, parole sau coduri? 3) Expeditorul se potrivește (adresa reală)? 4) Linkul duce unde pretinde (cursorul peste link, fără click)? 5) Problema „există” (poți intra normal în cont)? 6) Textul sună firesc? 7) Vine pe un canal neobișnuit?", "Un singur răspuns care te pune pe gânduri ajunge ca să <b>nu</b> dai click.", "Phishingul vine și prin <b>SMS</b> (smishing), <b>WhatsApp</b> și <b>apel</b> (vishing), nu doar pe e-mail."], "text_dat": "", "cerinte": [{"titlu": "Phishing sau legitim? 6 mesaje", "minute": 25, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> și salvează-l ca <code>E21_Phishing_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Citește mesajele pe rând. Pentru fiecare treci prin <b>lista de 10 secunde</b> (e în caseta „Ce ai învățat la teorie”, de mai sus). La fiecare întrebare care te pune pe gânduri, notează indiciul.", "Uită-te atent la <b>adresele expeditorilor</b>: compară-le literă cu literă cu cele adevărate. O cifră pusă în loc de literă sau un cuvânt în plus („-verificare”, „-support”) e un indiciu.", "În tabelul „Verdictele” scrie <b>phishing</b> sau <b>legitim</b> și cel puțin <b>2 indicii</b> pentru fiecare mesaj. Și la mesajele legitime scrii de ce sunt în regulă."], "ghiduri": ["G3"]}, {"titlu": "Ce faci concret", "minute": 15, "pasi": ["Pentru <b>mesajul 1</b> și <b>mesajul 4</b>, scrie <b>3 pași</b>: ce faci acum, cum verifici și cui spui.", "Gândește-te și la „<b>dacă aș fi dat deja click</b>”: ce ai face atunci?", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Cursorul peste link (fără click)", "pasi": ["Deschide în căsuța ta de e-mail un mesaj de la un magazin sau de la o firmă de la care primești des (un newsletter oarecare).", "Pune <b>cursorul</b> peste un link sau buton, <b>fără să dai click</b>. Jos, în stânga ferestrei (sau într-un mic balon), apare <b>adresa reală</b> unde duce linkul.", "Compară: adresa începe cu domeniul firmei (de exemplu <code>…magazin.ro/…</code>)? Așa verifici orice link înainte să dai click. Pe telefon: ții degetul apăsat pe link (fără să-l deschizi) și vezi adresa."]}, "verifica": ["Toate cele 6 mesaje au verdict și cel puțin 2 indicii.", "La fiecare e-mail ai comparat adresa expeditorului literă cu literă.", "La mesajele 1 și 4 ai câte 3 pași, inclusiv cui spui."], "rez": {"intro": "Patru mesaje sunt phishing (1, 2, 4, 6), iar două sunt legitime (3, 5). Indiciile de mai jos sunt cele principale; dacă ai găsit și altele corecte, cu atât mai bine.", "parti": [{"titlu": "Partea 1 – Verdictele", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Verdict</th><th scope='col'>Indiciile</th></tr></thead><tbody><tr><td>1</td><td>Phishing</td><td>Urgență („24 de ore”, „URGENT”); cere datele cardului; adresa „banca-ta-verificare.com” nu e a băncii; butonul „Confirmă acum” duce pe un site străin.</td></tr><tr><td>2</td><td>Phishing (SMS / smishing)</td><td>Nu aștepți niciun colet (problema nu există); cere bani, chiar dacă puțini; link scurtat (bit.ly), care ascunde adresa; canal neobișnuit pentru plăți.</td></tr><tr><td>3</td><td>Legitim</td><td>Expeditorul e adresa obișnuită a IT-ului din domeniul firmei; nu cere nimic; nu are link sau atașament; e o informare, nu o urgență.</td></tr><tr><td>4</td><td>Phishing (fraudă „număr nou”)</td><td>Număr necunoscut; urgență; cere bani; povestea „mi s-a stricat telefonul” explică de ce nu poți suna pe numărul vechi. E un tipar foarte des întâlnit.</td></tr><tr><td>5</td><td>Legitim</td><td>Ai făcut tu comanda ieri; are numărul comenzii; nu cere plată sau date; linkul, verificat cu cursorul, duce pe adresa magazinului.</td></tr><tr><td>6</td><td>Phishing</td><td>„micros0ft” cu cifra 0 în loc de litera o; urgență („AZI”); cere parola actuală („ca s-o păstrați” e o capcană: nimeni nu are nevoie de parola ta ca s-o păstreze).</td></tr></tbody></table></div>"}, {"titlu": "Partea 2 – Pașii corecți", "html": "<p><b>Mesajul 1:</b> 1) Nu dai click, nu răspunzi. 2) Verifici altfel: intri în aplicația băncii sau suni la numărul de pe card și întrebi dacă e ceva cu contul. 3) Raportezi: la serviciu, butonul <b>Raportați</b> din Outlook (sau anunți IT-ul); acasă, ștergi mesajul. <b>Dacă ai dat deja datele cardului:</b> suni imediat la bancă să blochezi cardul și raportezi frauda la DNSC (1911, dnsc.ro) și la poliție, dacă au plecat bani.</p><p><b>Mesajul 4:</b> 1) Nu trimiți bani și nu răspunzi la mesaj. 2) <b>Suni tu</b> copilul pe <b>numărul vechi</b>, cel pe care îl știi, sau pe cineva care e lângă el. 3) Blochezi numărul și îl raportezi în WhatsApp (<b>Raportează</b>). Spune-le și celorlalți din familie, ca să nu cadă și ei. <b>Dacă ai trimis deja bani:</b> suni imediat la bancă (poate opri transferul dacă e repede) și mergi la poliție.</p><div class='cadru'>Cum verifici un mesaj suspect: niciodată folosind datele din mesaj (link, număr de telefon din mesaj). Mereu pe un drum pe care îl știi tu: aplicația oficială, numărul de pe card, numărul vechi din agendă.</div>"}]}, "glume": ["„micros0ft” cu zero e ca un tren „lnterRegio” cu L mic: arată bine de departe, dar nu te duce unde vrei."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Phishing sau legitim? 6 mesaje", 25], ["Cerința 2 – Ce faci concret", 15], ["Pas în plus – Cursorul peste link (fără click)", 50], ["Întrebări și discuție", 15]]}, {"cod": "E22", "titlu": "Phishing pe SMS, WhatsApp și telefon: ce faci și cui raportezi", "statut": "rec", "nota": null, "ore": [25], "suport": "4.4, pg. 48-55", "org": "Studii securitate cibernetică", "vechi": "T14/T19", "zi": 11, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-16", "sg2": "2026-11-10", "teorie": [{"zi": 7, "ora": 25, "titlu": "Phishing: ce este, cele șapte indicii, apărare"}], "gata": true, "fisa": "fise/Fisa_E22_Phishing_pe_SMS_WhatsApp_si_telefon.docx", "rez_doc": "fise/Rezolvare_E22_Phishing_pe_SMS_WhatsApp_si_telefon.docx", "pornire_var": [], "pornire": "fise/E22_Raportare_PORNIRE.docx", "pornire_desc": "Cele 5 situații și tabelul „Unde raportez”, de completat.", "model": [], "fisier": "E22_Raportare_Nume_Prenume.docx", "subiect": "E22 – Raportare – Nume Prenume", "predare_obl": false, "pe_scurt": "Înșelătoriile nu vin doar pe e-mail: vin prin <b>telefon</b>, <b>SMS</b>, <b>WhatsApp</b>, <b>Messenger</b>, chiar și cu <b>vocea clonată</b> a unui om drag. Scrii ce faci în <b>5 situații</b>, apoi completezi un tabel scurt: <b>unde raportezi</b> fiecare tip de problemă. Miezul: <b>cam 35 de minute</b>.", "recap": ["<b>Vishing</b> = înșelătorie prin apel. <b>Smishing</b> = prin SMS. <b>Clonarea vocii</b> = cu un fragment de voce de pe internet se poate imita vocea cuiva.", "Regula de aur: <b>nu verifici niciodată folosind datele primite în mesaj</b>. Închizi și suni tu, pe un număr pe care îl știi.", "O <b>familie</b> se poate apăra cu un <b>cuvânt de siguranță</b>: un cuvânt știut doar de voi, pe care îl cereți la orice telefon ciudat „de urgență”."], "text_dat": "", "cerinte": [{"titlu": "Cinci situații", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> și salvează-l ca <code>E22_Raportare_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Pentru fiecare situație scrie <b>2–3 pași</b>: ce faci <b>acum</b>, cum <b>verifici</b> pe un drum sigur, ce faci <b>după</b>.", "Ține minte regula: <b>nu folosești</b> numărul, linkul sau contul din mesaj ca să verifici. Folosești ce știi tu."], "ghiduri": ["G3"]}, {"titlu": "Unde raportez", "minute": 15, "pasi": ["Completează tabelul „Unde raportez?”. Poți scrie mai multe locuri pe un rând.", "Ce trebuie să știi: la serviciu, mesajele suspecte merg la <b>IT</b> (în Outlook există butonul <b>Raportați</b> / Report). Pentru fraude online există <b>DNSC</b> (Directoratul Național de Securitate Cibernetică): <b>dnsc.ro</b> și numărul de telefon <b>1911</b>. Dacă ai pierdut bani: <b>banca</b> și <b>poliția</b>.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Cuvântul de siguranță al familiei", "pasi": ["Gândește-te la un <b>cuvânt de siguranță</b> pe care l-ai putea stabili cu familia: ușor de ținut minte, dar pe care nu-l ghicește nimeni (nu numele câinelui de pe Facebook!).", "<b>Nu-l scrie în document.</b> Vorbește despre asta acasă. Regula: la orice telefon „de urgență” cu cerere de bani, întrebi cuvântul."]}, "verifica": ["Fiecare dintre cele 5 situații are 2–3 pași.", "Niciun pas nu folosește numărul sau linkul din mesaj ca să verifice.", "Tabelul „Unde raportez?” are toate cele 5 rânduri completate."], "rez": {"intro": "Situațiile au un răspuns corect clar. Formularea ta poate fi diferită, dar pașii trebuie să fie aceiași.", "parti": [{"titlu": "Partea 1 – Cele 5 situații", "html": "<p><b>1) „Banca” la telefon cere codul.</b> Închizi. Nu dai codul: banca nu-l cere niciodată. Suni tu la <b>numărul de pe spatele cardului</b> și întrebi dacă e vreo problemă.</p><p><b>2) Vocea fiului cere bani urgent.</b> Nu trimiți nimic. <b>Suni tu</b> fiul pe numărul lui știut sau pe cineva de lângă el și ceri cuvântul de siguranță, dacă aveți unul. Vocile se pot clona din câteva secunde de înregistrare de pe internet.</p><p><b>3) SMS „ANAF” cu date de card.</b> E fals: ANAF nu cere date de card prin SMS. Nu deschizi linkul și ștergi mesajul. Dacă vrei să verifici, intri singur în <b>Spațiul Privat Virtual (SPV)</b> sau suni la ANAF pe numărul de pe site-ul oficial.</p><p><b>4) Prietenul de pe Messenger cere codul.</b> Contul prietenului e, foarte probabil, deja furat. Codul cerut e cel care i-ar da hoțului <b>contul tău</b> (de WhatsApp sau Facebook). Nu dai codul, iar pe prieten îl anunți <b>pe alt canal</b> (telefon), ca să-și recupereze contul.</p><p><b>5) Ai dat parola de la e-mail pe un site fals.</b> Imediat: <b>schimbi parola</b> (de pe alt dispozitiv, dacă poți), activezi <b>autentificarea în doi pași</b>, verifici în setări că nu s-a adăugat o regulă de redirecționare a mesajelor. Dacă e contul de serviciu, anunți <b>IT-ul</b> imediat. Schimbi parola și pe alte conturi unde ai folosit-o pe aceeași.</p>"}, {"titlu": "Partea 2 – Unde raportez", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce s-a întâmplat</th><th scope='col'>Unde / cui raportez</th></tr></thead><tbody><tr><td>E-mail suspect la serviciu</td><td>IT-ul firmei; în Outlook, butonul <b>Raportați</b> (Report) → Phishing. Nu îl redirecționezi colegilor.</td></tr><tr><td>Fraudă online</td><td><b>DNSC</b>: dnsc.ro (secțiunea de raportare a incidentelor) sau la telefon <b>1911</b>.</td></tr><tr><td>Am pierdut bani</td><td><b>Banca</b>, imediat, la numărul de pe card (poate bloca cardul sau opri transferul), apoi <b>Poliția</b> (plângere). Poți anunța și DNSC.</td></tr><tr><td>Cont de Facebook / WhatsApp furat</td><td>Procedura de recuperare a platformei (Facebook: „Contul meu a fost spart”; WhatsApp: te reînregistrezi cu numărul tău). Îi anunți pe prieteni, pe alt canal, să nu răspundă la cereri de bani.</td></tr><tr><td>SMS fals („curier”, „ANAF”)</td><td>Nu răspunzi și nu deschizi linkul; ștergi mesajul și blochezi numărul. Poți raporta la DNSC.</td></tr></tbody></table></div>"}]}, "glume": ["„Sunt de la bancă, dați-mi codul” e ca un controlor care îți cere portofelul ca să-ți verifice biletul."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Cinci situații", 20], ["Cerința 2 – Unde raportez", 15], ["Pas în plus – Cuvântul de siguranță al familiei", 55], ["Întrebări și discuție", 15]]}, {"cod": "E23", "titlu": "Date personale: ce dai și ce nu dai", "statut": "rec", "nota": null, "ore": [27], "suport": "4.5, pg. 55", "org": "Studii comunicare 3", "vechi": "T15", "zi": 12, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-19", "sg2": "2026-11-11", "teorie": [{"zi": 7, "ora": 27, "titlu": "Date personale · siguranța copiilor"}], "gata": true, "fisa": "fise/Fisa_E23_Date_personale.docx", "rez_doc": "fise/Rezolvare_E23_Date_personale.docx", "pornire_var": [], "pornire": "fise/E23_Date_personale_PORNIRE.docx", "pornire_desc": "Tabelul cu cele 8 situații și studiul de caz, cu întrebările lui.", "model": [], "fisier": "E23_Date_personale_Nume_Prenume.docx", "subiect": "E23 – Date personale – Nume Prenume", "predare_obl": false, "pe_scurt": "Cineva îți cere date personale: unele cereri sunt firești, altele sunt capcane. Pentru <b>8 situații</b> hotărăști <b>dai sau nu dai</b> și de ce. Apoi analizezi un <b>studiu de caz al organizatorului</b>: o listă cu numele și telefoanele unor călători, trimisă din greșeală în grupul general. Miezul: <b>cam 35 de minute</b>.", "recap": ["<b>Dată personală</b> = orice informație care te poate identifica, direct (nume, CNP, seria și numărul actului) sau prin combinare (adresă, telefon, e-mail personal, cont bancar, date medicale, fotografii).", "Trei întrebări înainte să dai o dată: <b>cine</b> o cere (instituția reală sau doar cineva care spune că e)? <b>De ce</b> are nevoie de ea? <b>Pe ce canal</b> o ceri și o dai (ghișeu, cont oficial, nu un mesaj primit din senin)?", "Datele altora le trimiți <b>doar persoanei care are nevoie de ele</b>, pe <b>canalul aprobat</b> de instituție, și <b>doar cât e necesar</b>. Nu într-un grup general."], "text_dat": "", "cerinte": [{"titlu": "Dai sau nu dai? Opt situații", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E23_Date_personale_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Ia situațiile la rând și pune-ți cele <b>3 întrebări</b>: <b>cine</b> cere? <b>de ce</b> are nevoie? <b>pe ce canal</b>?", "Scrie în coloana a treia <b>DA</b>, <b>NU</b> sau <b>DOAR O PARTE</b>. În ultima coloană scrie motivul, într-o propoziție.", "Atenție la capcană: aceeași dată (de exemplu CNP-ul) poate fi cerută <b>corect</b> într-o situație și <b>ca înșelătorie</b> în alta. Diferența o fac cine o cere și pe ce canal."], "ghiduri": ["G3"]}, {"titlu": "Studiul de caz: lista de pasageri", "minute": 15, "pasi": ["Citește studiul de caz din partea a doua a documentului. E unul dintre studiile de caz oficiale ale cursului (comunicare și etichetă digitală, nr. 3).", "<b>a)</b> Scrie ce reguli au fost încălcate. Gândește-te: <b>cine</b> a primit datele? <b>avea nevoie</b> de ele? erau <b>toate</b> necesare?", "<b>b)</b> Rescrie, în 1–2 propoziții, mesajul pe care colegul l-ar fi putut trimite în grup <b>fără</b> date personale.", "<b>c)</b> Scrie <b>3 pași</b>, în ordine, pentru ce face echipa acum.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Ce permisiuni au aplicațiile de pe telefonul tău", "pasi": ["<b>Android:</b> <b>Setări</b> → <b>Securitate și confidențialitate</b> (sau <b>Confidențialitate</b>) → <b>Manager de permisiuni</b> (Permission manager). Numele exacte diferă de la un telefon la altul. <b>iPhone:</b> <b>Configurări</b> → <b>Confidențialitate și securitate</b>.", "Deschide <b>Locație</b>, apoi <b>Contacte</b>. Uită-te ce aplicații au acces. Are nevoie de locație un joc? Are nevoie de contacte o aplicație de editat poze?", "Scoate accesul unei aplicații care nu are nevoie de el (alegi <b>Nu permite</b> / Don't allow). Notează la finalul documentului ce aplicație ai schimbat. Nu scrie alte detalii despre telefonul tău."]}, "verifica": ["Toate cele 8 situații au DA / NU / DOAR O PARTE și un motiv.", "Situațiile 2, 3, 5 și 7 au răspunsul NU.", "La studiul de caz ai răspuns la a), b) și c), iar la c) ai 3 pași în ordine.", "Mesajul rescris de la b) nu conține niciun nume și niciun număr de telefon."], "rez": {"intro": "Răspunsurile de la partea 1 sunt fixe. La studiul de caz contează ideile: formulările tale pot fi altele.", "parti": [{"titlu": "Partea 1 – Cele 8 situații", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Dau?</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>1</td><td>DA</td><td>Adresa și telefonul sunt necesare pentru livrare, iar curierul lucrează pentru o comandă făcută de tine.</td></tr><tr><td>2</td><td>NU</td><td>Pentru livrare ajung numele, adresa și telefonul. CNP-ul nu are ce căuta într-o comandă obișnuită.</td></tr><tr><td>3</td><td>NU</td><td>O poză cu buletinul dă CNP-ul, seria și numărul actului, adresa. E exact ce caută cine vrea să-ți fure identitatea. Un concurs nu are nevoie de ea.</td></tr><tr><td>4</td><td>DA</td><td>Banca reală, la ghișeu, față în față, are obligația să te identifice când deschizi un cont.</td></tr><tr><td>5</td><td>NU</td><td>O lanternă nu are nevoie de contacte și locație. Refuzi permisiunile; dacă aplicația nu merge fără ele, o ștergi.</td></tr><tr><td>6</td><td>DA</td><td>Angajatorul are nevoie de aceste date pentru contract, iar cererea vine pe canalul oficial al firmei.</td></tr><tr><td>7</td><td>NU</td><td>Necunoscut, pe WhatsApp, înainte de interviu: e o înșelătorie clasică. Un angajator real îți cere actele la angajare, prin canalul lui oficial.</td></tr><tr><td>8</td><td>NU (cel mult DOAR O PARTE)</td><td>Pe un site necunoscut nu-ți salvezi cardul. Plătești o dată, cu confirmarea băncii, și atât. Pe un magazin mare, cunoscut, la care cumperi des, e alegerea ta.</td></tr></tbody></table></div><div class='cadru'>Regula din spatele tabelului: aceeași dată poate fi cerută corect (CNP-ul la HR, situația 6) sau ca înșelătorie (CNP-ul pe WhatsApp, situația 7). Nu te uiți doar la ce se cere, ci și la cine cere, de ce și pe ce canal.</div>"}, {"titlu": "Partea 2 – Studiul de caz", "html": "<p><b>a) Ce s-a încălcat:</b> datele personale (nume și telefon) au ajuns la <b>toți</b> cei 40 de membri ai grupului, nu doar la cine avea nevoie de ele. Nu exista niciun motiv de serviciu ca toată lumea să le vadă. Și, pentru anunț, <b>nu era nevoie deloc</b> de ele. Buna intenție a colegului nu șterge greșeala: rămâne o problemă de confidențialitate.</p><p><b>b) Varianta corectă</b>, în grup: „Bună ziua! De mâine, trenul de 17:10 circulă pe alt traseu, prin X. Câțiva călători au sunat deja să întrebe; lista cu ei i-am trimis-o doar Anei, care îi sună înapoi.” Lista ajunge <b>doar</b> la persoana care îi sună, pe <b>canalul aprobat</b> de instituție (e-mailul de serviciu, de exemplu).</p><div class='tw'><table><thead><tr><th scope='col'>Pas</th><th scope='col'>c) Ce face echipa acum</th></tr></thead><tbody><tr><td>1</td><td>Colegul <b>șterge imediat mesajul pentru toți</b> (în WhatsApp: apăsare lungă → Șterge → <b>Șterge pentru toți</b>).</td></tr><tr><td>2</td><td>Cere membrilor grupului să șteargă tabelul, dacă l-au descărcat sau l-au trimis mai departe.</td></tr><tr><td>3</td><td><b>Anunță șeful</b> și responsabilul cu protecția datelor din instituție. Ei hotărăsc dacă trebuie anunțați călătorii sau autoritatea (ANSPDCP).</td></tr></tbody></table></div><p><b>De ce contează pasul 3:</b> o greșeală spusă repede se poate limita. Una ascunsă crește.</p>"}, {"titlu": "Pas în plus – permisiunile", "html": "<p>Nu există un singur răspuns corect: contează să fi găsit cel puțin o aplicație care avea un acces de care nu are nevoie și să i-l fi scos. Exemple dese: jocuri cu acces la locație, aplicații de editat poze cu acces la contacte.</p>"}]}, "glume": ["Datele personale sunt ca biletul de tren: le arăți controlorului, nu tuturor celor din vagon."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Dai sau nu dai? Opt situații", 20], ["Cerința 2 – Studiul de caz: lista de pasageri", 15], ["Pas în plus – Ce permisiuni au aplicațiile de pe telefonul tău", 55], ["Întrebări și discuție", 15]]}, {"cod": "E24", "titlu": "Siguranța copiilor: reguli de familie + control parental", "statut": "rec", "nota": null, "ore": [27], "suport": "4.6, pg. 55-57", "org": "—", "vechi": "T16", "zi": 12, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-19", "sg2": "2026-11-11", "teorie": [{"zi": 7, "ora": 27, "titlu": "Date personale · siguranța copiilor"}], "gata": true, "fisa": "fise/Fisa_E24_Siguranta_copiilor.docx", "rez_doc": "fise/Rezolvare_E24_Siguranta_copiilor.docx", "pornire_var": [], "pornire": "fise/E24_Copii_PORNIRE.docx", "pornire_desc": "Tabelul cu cele 5 situații, pașii amestecați pentru primul cont și tabelul cu funcțiile controlului parental.", "model": [], "fisier": "E24_Copii_Nume_Prenume.docx", "subiect": "E24 – Copii – Nume Prenume", "predare_obl": false, "pe_scurt": "Un prieten, Mircea, are doi copii: <b>Tudor, de 11 ani</b>, și <b>Ioana, de 8</b>. Te roagă să-l ajuți. Pentru <b>5 situații</b> spui ce risc e și <b>care e prima reacție bună</b>. Apoi pui în ordine pașii pentru <b>primul cont pe o rețea socială</b> și potrivești funcțiile <b>controlului parental</b>. Familia e inventată. Miezul: <b>cam 35 de minute</b>.", "recap": ["Trei riscuri specifice copiilor: <b>hărțuirea</b> din partea altor copii (cyberbullying), <b>contactul cu necunoscuți</b> care se pot da drept altcineva și <b>conținutul nepotrivit</b> vârstei.", "Trei direcții de apărare: <b>controlul parental</b> (unealta), <b>discuția deschisă</b> cu copilul și o <b>supraveghere echilibrată</b>, care nu strică încrederea. Unealta nu ține loc de discuție.", "Unelte: pe <b>Android</b>, <b>Family Link</b> (gratuit). Pe <b>iPhone</b>, <b>Timpul de utilizare</b>, din Setări, protejat cu un cod știut doar de părinte."], "text_dat": "", "cerinte": [{"titlu": "Cinci situații: ce risc e și ce faci", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E24_Copii_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Pentru fiecare situație scrie <b>ce risc e</b>, alegând din lista de deasupra tabelului.", "Scrie <b>prima reacție bună</b>, în 1–2 propoziții. Gândește-te ca un părinte calm: întâi <b>discuția</b> cu copilul, apoi <b>unealta</b> sau ajutorul altcuiva.", "O reacție bună <b>nu</b> începe cu „îi iau telefonul”. Un copil pedepsit pentru ce ți-a spus nu-ți mai spune nimic data viitoare."], "ghiduri": ["G3"]}, {"titlu": "Pașii pentru primul cont și controlul parental", "minute": 15, "pasi": ["<b>a)</b> Pune cei 4 pași în ordine: scrie 1, 2, 3 sau 4 în coloana a doua.", "<b>b)</b> Pentru fiecare dorință a lui Mircea, scrie funcția potrivită: <b>restricționarea conținutului</b>, <b>monitorizarea activității</b>, <b>limitele de timp</b> sau <b>localizarea</b>.", "<b>c)</b> Răspunde la cele două întrebări despre unealta potrivită.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Regulile familiei, pe o pagină", "pasi": ["La finalul documentului scrie <b>5 reguli</b> pentru Tudor, ca și cum le-ați fi stabilit împreună. Scrie-le pe limba lui, la persoana I plural: „Noi…”.", "Fiecare regulă e <b>scurtă</b> și <b>verificabilă</b>: „Telefonul doarme în bucătărie de la 22:00” e o regulă. „Folosim telefonul responsabil” nu e.", "Măcar o regulă spune <b>ce face Tudor când vede ceva ciudat</b> și măcar una spune <b>ce face părintele</b> (de exemplu: „Nu te cert dacă îmi spui”)."]}, "verifica": ["Cele 5 situații au riscul și o primă reacție care începe cu o discuție, nu cu o pedeapsă.", "Pașii pentru primul cont sunt în ordinea 3 – 4 – 1 – 2 (citind tabelul de sus în jos).", "Fiecare dorință a lui Mircea are una dintre cele 4 funcții.", "Ai scris Family Link pentru Android și Timpul de utilizare, cu cod, pentru iPhone."], "rez": {"intro": "Riscurile, ordinea pașilor și funcțiile au un singur răspuns corect. La „prima reacție” contează ideile: discuția calmă întâi, apoi unealta sau ajutorul altcuiva.", "parti": [{"titlu": "Partea 1 – Cele 5 situații", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Ce risc e</th><th scope='col'>Prima reacție bună</th></tr></thead><tbody><tr><td>1</td><td>Hărțuire (cyberbullying)</td><td>Îl asculți calm și îi spui că a făcut bine că ți-a spus. Nu răspunde la mesaje; păstrați capturi de ecran; blocați și raportați expeditorii. Anunți dirigintele.</td></tr><tr><td>2</td><td>Contact cu un necunoscut</td><td>Îi spui Ioanei, calm, că a făcut bine că ți-a arătat și că nu e vina ei. Nu mai răspunde, nu trimite nicio poză. Faceți capturi, blocați și raportați contul în joc. Dacă s-au cerut poze, anunți poliția.</td></tr><tr><td>3</td><td>Conținut nepotrivit vârstei</td><td>Vorbești cu ea despre ce a văzut și o liniștești. Pornești filtrarea: modul restricționat pe platformă și restricționarea conținutului din controlul parental.</td></tr><tr><td>4</td><td>Prea mult timp pe ecran</td><td>Stabiliți împreună o oră de culcare pentru telefon și o puneți și în controlul parental (limite de timp, ore de inactivitate).</td></tr><tr><td>5</td><td>Semn de alarmă (nu un diagnostic)</td><td>O discuție calmă, între patru ochi, fără acuzații: „Te văd mai trist în ultima vreme. S-a întâmplat ceva online?”. Dacă bănuiala se confirmă, ceri ajutorul școlii sau, după caz, al autorităților.</td></tr></tbody></table></div><div class='cadru'>Ce au în comun toate cele 5: copilul trebuie să știe că poate veni la tine fără să-și piardă telefonul. Asta e cea mai bună protecție, iar nicio aplicație nu o poate înlocui.</div>"}, {"titlu": "Partea 2 – Pașii și funcțiile", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ordinea corectă</th><th scope='col'>Pasul</th></tr></thead><tbody><tr><td>1</td><td>Verificați vârsta minimă cerută de platformă.</td></tr><tr><td>2</td><td>Instalați controlul parental, împreună, înainte să creați contul.</td></tr><tr><td>3</td><td>Stabiliți împreună regulile: ce se postează, cu cine vorbește, ce face dacă apare ceva ciudat.</td></tr><tr><td>4</td><td>Verificați din când în când, împreună cu el, cum merge.</td></tr></tbody></table></div><p>În tabelul din fișierul de pornire (de sus în jos) se scrie: <b>3 – 4 – 1 – 2</b>.</p><div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Funcția</th></tr></thead><tbody><tr><td>1</td><td>Restricționarea conținutului</td></tr><tr><td>2</td><td>Limitele de timp</td></tr><tr><td>3</td><td>Localizarea</td></tr><tr><td>4</td><td>Monitorizarea activității</td></tr></tbody></table></div><p><b>c)</b> Pentru Tudor (Android): <b>Family Link</b>. Pentru Ioana (iPhone): <b>Timpul de utilizare</b>, din Setări (Configurări), protejat cu un <b>cod pe care îl știe doar părintele</b>. Fără cod, Ioana îl poate opri singură.</p>"}, {"titlu": "Pas în plus – exemplu de reguli", "html": "<p>• Telefonul doarme în bucătărie, de la 22:00.</p><p>• Vorbim online doar cu oameni pe care îi cunoaștem și în viața reală.</p><p>• Nu trimitem poze cu noi, cu casa sau cu actele nimănui.</p><p>• Dacă vedem ceva ciudat sau cineva ne supără, venim și spunem. Nu se supără nimeni pe noi.</p><p>• O dată pe lună ne uităm împreună prin setările contului.</p>"}]}, "glume": ["Controlul parental e ca bariera de la trecerea la nivel: ajută mult, dar tot te uiți în stânga și-n dreapta. Iar discuția e semaforul."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Cinci situații: ce risc e și ce faci", 20], ["Cerința 2 – Pașii pentru primul cont și controlul parental", 15], ["Pas în plus – Regulile familiei, pe o pagină", 55], ["Întrebări și discuție", 15]]}, {"cod": "E25", "titlu": "Competențe verzi: fișa de lucru a organizatorului", "statut": "rec", "nota": null, "ore": [21, 29], "suport": "4 + 4.9, pg. 58-61", "org": "FIȘA DE LUCRU – Competențe verzi", "vechi": "T17", "zi": 13, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-20", "sg2": "2026-11-12", "teorie": [{"zi": 6, "ora": 21, "titlu": "Export PDF și partajare pe OneDrive"}, {"zi": 8, "ora": 29, "titlu": "Actualizări, înșelătorii, plăți online"}], "gata": true, "fisa": "fise/Fisa_E25_Competente_verzi.docx", "rez_doc": "fise/Rezolvare_E25_Competente_verzi.docx", "pornire_var": [], "pornire": "fise/E25_Verde_fisa_PORNIRE.docx", "pornire_desc": "Exercițiile din fișa de lucru a organizatorului, așezate ca să le completezi direct în Word.", "model": [], "fisier": "E25_Verde_fisa_Nume_Prenume.docx", "subiect": "E25 – Fișa verde – Nume Prenume", "predare_obl": false, "pe_scurt": "Lucrezi <b>fișa de lucru a organizatorului</b> despre competențele verzi: definiții de completat, adevărat sau fals, noțiuni de asociat, obiceiuri bune de bifat și un studiu de caz scurt. La final scrii <b>două reguli verzi</b> pentru biroul tău. Miezul: <b>cam 40 de minute</b>.", "recap": ["<b>Dezvoltarea durabilă</b> răspunde nevoilor de azi fără să le strice pe ale celor de mâine. Caută echilibrul dintre economie, mediu și bunăstarea oamenilor.", "<b>Principiul DNSH</b> („Do No Significant Harm”, adică „a nu aduce prejudicii semnificative”) cere ca o activitate să <b>nu afecteze grav mediul</b>: clima, apa, solul, biodiversitatea, economia circulară, poluarea.", "<b>Competențele verzi</b> în digital: folosești eficient energia și echipamentele, tipărești doar ce e nevoie, ții echipamentele cât mai mulți ani și le duci la <b>reciclare autorizată</b> la final."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Noțiunea</th><th scope='col'>Pe scurt (din fișa organizatorului și din suport, pg. 58–61)</th></tr></thead><tbody><tr><td>Protecția mediului</td><td>Măsurile prin care previi sau reduci efectele negative ale activităților oamenilor asupra naturii: resurse folosite cu grijă, mai puțină poluare, reciclare, energie economisită.</td></tr><tr><td>Dezvoltarea durabilă</td><td>Răspunde nevoilor de azi fără să le compromită pe ale generațiilor viitoare. Echilibru între dezvoltarea economică, protecția mediului și bunăstarea socială.</td></tr><tr><td>Imunizarea climatică</td><td>Activitățile și investițiile sunt adaptate ca să reziste efectelor schimbărilor climatice.</td></tr><tr><td>Principiul DNSH</td><td>O activitate nu are voie să aducă prejudicii semnificative mediului (clima, apa, solul, biodiversitatea, economia circulară, poluarea).</td></tr><tr><td>Competențele verzi</td><td>Cunoștințele, abilitățile și atitudinile cu care lucrezi responsabil față de mediu.</td></tr><tr><td>Economia verde</td><td>Dezvoltare economică cu impact redus asupra mediului. În digital: mai puțină hârtie, echipamente eficiente, folosite mai mult timp și reciclate, ședințe online în loc de drumuri.</td></tr></tbody></table></div>", "cerinte": [{"titlu": "Exercițiile 1, 2 și 3: noțiunile", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E25_Verde_fisa_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Citește întâi tabelul „<b>Textul pe care îl folosești</b>” de mai sus. Cele 6 noțiuni nu s-au predat pe larg la teorie: aici le ai pe toate, pe scurt.", "<b>Exercițiul 1:</b> dă dublu click pe liniuța <code>______</code>, ca s-o selectezi, și scrie cuvântul. Liniuța dispare.", "<b>Exercițiul 2:</b> scrie <b>A</b> (adevărat) sau <b>F</b> (fals) în ultima coloană. Atenție la cuvintele „<b>doar</b>” și „<b>niciun</b>”: de obicei fac o afirmație falsă.", "<b>Exercițiul 3:</b> scrie la „Răspunsuri” litera potrivită pentru fiecare cifră, de exemplu <code>1 – b</code>."], "ghiduri": ["G3"]}, {"titlu": "Exercițiile 4 și 5 și cele două reguli verzi", "minute": 20, "pasi": ["<b>Exercițiul 4:</b> scrie <b>X</b> în ultima coloană la comportamentele corecte. Sunt mai multe.", "<b>Exercițiul 5:</b> citește situația și scrie <b>două măsuri bune</b> pe care compania le-a luat deja și <b>o practică</b> care afectează mediul.", "<b>Activitatea aplicativă:</b> scrie <b>2 reguli verzi</b> pentru biroul tău. Fiecare regulă spune <b>ce faci</b> și <b>când</b>, ca să se poată verifica. De exemplu: „Seara, la plecare, opresc monitorul și calculatorul.”", "Completează <b>autoevaluarea</b>. E doar pentru tine: răspunde sincer.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Digitalizarea ajută sau afectează mediul?", "pasi": ["Studiile de caz ale organizatorului au un text cu titlul acesta. Ideea lui: digitalizarea are <b>și</b> efecte bune, <b>și</b> efecte rele.", "La finalul documentului scrie <b>două efecte bune</b> (de exemplu: mai puțină hârtie, mai puține drumuri) și <b>două efecte rele</b> (de exemplu: curentul consumat de centrele de date, deșeurile electronice).", "Încheie cu o propoziție: ce poți face <b>tu</b>, ca să rămână mai multe efecte bune decât rele?"]}, "verifica": ["Ai completat toate cele 5 spații de la exercițiul 1.", "La exercițiul 2 ai 6 răspunsuri A/F, iar la exercițiul 3 patru perechi.", "La exercițiul 4 ai bifat 4 comportamente.", "Ai două măsuri și o practică la exercițiul 5 și două reguli verzi verificabile."], "rez": {"intro": "Exercițiile 1–4 au răspunsuri fixe. La exercițiul 5 și la reguli contează ideile.", "parti": [{"titlu": "Exercițiul 1 – Definițiile", "html": "<div class='tw'><table><thead><tr><th scope='col'>Spațiul</th><th scope='col'>Cuvântul</th></tr></thead><tbody><tr><td>a)</td><td>naturii (sau: mediului)</td></tr><tr><td>b)</td><td>mediului</td></tr><tr><td>c)</td><td>mediului</td></tr><tr><td>d)</td><td>responsabil</td></tr><tr><td>e)</td><td>responsabil (se acceptă și: sustenabil)</td></tr></tbody></table></div>"}, {"titlu": "Exercițiul 2 – Adevărat sau fals", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>A / F</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>1</td><td>F</td><td>Cuvântul „doar”: dezvoltarea durabilă înseamnă echilibru între economie, mediu și bunăstarea socială.</td></tr><tr><td>2</td><td>A</td><td>Exact asta înseamnă DNSH.</td></tr><tr><td>3</td><td>F</td><td>Cuvântul „niciun”: echipamentele consumă curent, se fabrică din resurse rare și devin deșeuri electronice.</td></tr><tr><td>4</td><td>A</td><td>Reciclarea recuperează materiale și evită poluarea.</td></tr><tr><td>5</td><td>A</td><td>Un document trimis electronic nu mai trebuie tipărit.</td></tr><tr><td>6</td><td>A</td><td>Un echipament oprit nu consumă.</td></tr></tbody></table></div>"}, {"titlu": "Exercițiul 3 – Asocierile", "html": "<div class='tw'><table><thead><tr><th scope='col'>Noțiunea</th><th scope='col'>Explicația</th></tr></thead><tbody><tr><td>1 – Dezvoltare durabilă</td><td>b. Utilizarea responsabilă a resurselor pentru prezent și viitor</td></tr><tr><td>2 – DNSH</td><td>c. O activitate nu produce daune semnificative mediului</td></tr><tr><td>3 – Competențe verzi</td><td>d. Cunoștințe și comportamente ecologice la locul de muncă</td></tr><tr><td>4 – Economia verde</td><td>a. Reducerea impactului negativ asupra mediului</td></tr></tbody></table></div><p>Răspunsul scurt: <b>1 – b, 2 – c, 3 – d, 4 – a</b>.</p>"}, {"titlu": "Exercițiul 4 – Practicile corecte", "html": "<p>Corecte (cu X): <b>2, 4, 5 și 7</b>.</p><p>Greșite: <b>1</b> (consum degeaba), <b>3</b> (bateriile și echipamentele vechi sunt deșeuri periculoase și se duc la colectare separată) și <b>6</b> (un echipament care merge bine, schimbat degeaba, devine deșeu mai devreme).</p>"}, {"titlu": "Exercițiul 5 și regulile verzi", "html": "<p><b>a) Măsuri sustenabile</b> (oricare două): documentele se transmit online; ședințele se țin prin videoconferință (mai puține drumuri); arhivarea se face electronic.</p><p><b>b) Practici care afectează mediul</b> (oricare una): echipamentele lăsate pornite; tipărirea fără nevoie; deșeurile electronice necolectate separat.</p><p><b>Exemple de reguli verzi, verificabile:</b> „Seara, la plecare, opresc monitorul și calculatorul.” · „Tipăresc doar ce cere procedura pe hârtie, și atunci față-verso.” · „Bateriile și echipamentele stricate le duc la punctul de colectare, nu la coș.”</p><div class='cadru'>O regulă bună se poate verifica: la final de zi vezi dacă monitorul e oprit. „Să fim mai verzi” nu se poate verifica, deci nu e o regulă.</div>"}, {"titlu": "Pas în plus – ajută sau afectează?", "html": "<p><b>Efecte bune:</b> mai puțină hârtie; mai puține drumuri (ședințe și lucru la distanță); senzori și sisteme inteligente care economisesc energie și apă; platforme pentru reutilizare și reciclare.</p><p><b>Efecte rele:</b> curentul și răcirea pentru centrele de date; deșeurile electronice; resursele rare scoase din pământ pentru fabricarea echipamentelor; „efectul de revenire” (rebound): pentru că e ușor, folosim tot mai mult.</p><p><b>Concluzia textului:</b> digitalizarea nu e în sine bună sau rea. Depinde de cum o folosim.</p>"}]}, "glume": ["Un monitor lăsat pornit peste noapte e ca un tren care circulă gol: ajunge la timp, dar nu duce pe nimeni."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Exercițiile 1, 2 și 3: noțiunile", 20], ["Cerința 2 – Exercițiile 4 și 5 și cele două reguli verzi", 20], ["Pas în plus – Digitalizarea ajută sau afectează mediul?", 50], ["Întrebări și discuție", 15]]}, {"cod": "E26", "titlu": "Competențe verzi: amprenta mea digitală", "statut": "obl", "nota": "N4", "ore": [29], "suport": "4.9, pg. 58-61", "org": "Studii comp. verzi", "vechi": "T17", "zi": 13, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-20", "sg2": "2026-11-12", "teorie": [{"zi": 8, "ora": 29, "titlu": "Actualizări, înșelătorii, plăți online"}], "gata": true, "fisa": "fise/Fisa_E26_Competente_verzi.docx", "rez_doc": "fise/Rezolvare_E26_Competente_verzi.docx", "pornire_var": [], "pornire": "fise/E26_Amprenta_PORNIRE.docx", "pornire_desc": "Documentul gata structurat: tabelul de măsurători, tabelul cu cele 3 acțiuni (înainte – după) și locul pentru concluzie și sursă.", "model": ["fise/Model_E26_Amprenta.docx"], "fisier": "E26_Amprenta_Nume_Prenume.docx", "subiect": "E26 – Amprenta digitală – Nume Prenume", "predare_obl": true, "pe_scurt": "<b>Exercițiul se notează (Nota 4).</b> Îți măsori <b>amprenta digitală</b>: cât spațiu ocupă e-mailul, OneDrive-ul (sau Google Drive) și telefonul tău, câte e-mailuri mari și câte newslettere ai. Apoi alegi <b>3 acțiuni</b>, <b>le faci</b> și notezi <b>cât s-a schimbat</b>. Încheii cu o concluzie scurtă, cu sursa. Cifrele sunt ale tale, deci lucrarea ta nu seamănă cu a nimănui. Miezul: <b>cam 45 de minute</b>.", "recap": ["Tot ce păstrăm online stă pe <b>servere</b> care consumă curent și trebuie răcite zi și noapte. Fișierele de care nu mai avem nevoie, păstrate „pentru orice eventualitate”, consumă degeaba.", "<b>Moderația digitală</b> (digital sobriety, din suportul de curs, pg. 61): folosești resursele IT <b>conștient</b>. Ștergi ce nu-ți trebuie, nu trimiți același fișier mare la 20 de oameni (trimiți un link), îți ții echipamentele cât mai mulți ani.", "Nu căutăm cifre de CO₂, care diferă mult de la o sursă la alta. Măsurăm ce <b>vedem</b>: GB, număr de e-mailuri, număr de abonamente. Și comparăm <b>înainte</b> și <b>după</b>."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Acțiunea (alegi 3)</th><th scope='col'>Cum o faci</th></tr></thead><tbody><tr><td>Ștergi e-mailurile mari de care nu mai ai nevoie</td><td>Le găsești cu căutarea de la Cerința 1 (pasul 2), le ștergi, apoi golești dosarul <b>Coș de gunoi</b> / <b>Elemente șterse</b> (Trash / Deleted Items).</td></tr><tr><td>Te dezabonezi de la cel puțin 3 newslettere</td><td>Linkul <b>Dezabonare</b> (Unsubscribe), de obicei jos în mesaj sau sus, lângă expeditor. <b>Doar</b> la expeditori pe care îi recunoști; la mesajele suspecte nu apeși nimic.</td></tr><tr><td>Ștergi pozele și clipurile în dublu sau ratate de pe telefon</td><td>Din <b>Galerie</b> / <b>Fotografii</b>. Apoi golești și dosarul <b>Șterse recent</b> (Recently deleted).</td></tr><tr><td>Ștergi fișierele vechi din OneDrive / Google Drive</td><td>Apoi golești și <b>Coșul de reciclare</b> al lor (pe web, în stânga).</td></tr><tr><td>Golești Coșul de reciclare de pe calculator</td><td>Click dreapta pe <b>Coș de reciclare</b> (Recycle Bin) → <b>Golire Coș de reciclare</b>.</td></tr><tr><td>Setezi oprirea ecranului după 5–10 minute</td><td><b>Setări</b> → <b>Sistem</b> → <b>Alimentare</b> (Power) → <b>Ecran și repaus</b>. La serviciu poate fi setat de IT.</td></tr></tbody></table></div>", "cerinte": [{"titlu": "Măsoară-ți amprenta digitală", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E26_Amprenta_Nume_Prenume.docx</code> (ghidul <b>G3</b>). Scrie-ți numele și data sus.", "<b>E-mailul:</b> vezi cât spațiu ocupă (ghidul <b>G10</b>). În <b>Gmail</b> scrie în căsuța de căutare <code>has:attachment larger:10M</code> și numără mesajele găsite. În <b>Outlook.com</b>: <b>Filtru</b> (Filter) → <b>Are fișiere</b> (Has files), apoi sortează după <b>Dimensiune</b> (Size).", "<b>Newsletterele:</b> caută în căsuța ta mesajele din ultima săptămână de la magazine, site-uri și reclame. Numără <b>câți expeditori</b> diferiți sunt.", "<b>OneDrive (sau Google Drive) și telefonul:</b> vezi spațiul folosit (ghidul <b>G10</b>). <b>Coșul de gunoi:</b> pe ecranul calculatorului, pictograma <b>Coș de reciclare</b> (Recycle Bin) e plină sau goală?", "Scrie toate cifrele în tabelul 1, cu locul în care le-ai văzut. Fă <b>cel puțin două capturi</b> (de exemplu spațiul din e-mail și cel de pe telefon) și lipește-le sub tabel (ghidurile <b>G1</b> și <b>G2</b>).", "⚠ În capturi să <b>nu</b> se vadă subiectele e-mailurilor, nume de persoane sau poze personale. Decupează doar zona cu spațiul ocupat."], "ghiduri": ["G3", "G10", "G1", "G2"]}, {"titlu": "Fă 3 acțiuni, măsoară din nou, scrie concluzia", "minute": 25, "pasi": ["Alege <b>3 acțiuni</b> din tabelul „<b>Textul pe care îl folosești</b>” de mai sus (sau altele, la fel de concrete) și <b>fă-le acum</b>, la curs.", "<b>Măsoară din nou</b> și completează tabelul 2: <b>ce ai făcut</b>, cifra de <b>înainte</b>, cifra de <b>după</b> și <b>cât a scăzut</b>.", "Scrie <b>concluzia</b> (4–6 rânduri), pentru colegii tăi de birou: ce te-a surprins, ce acțiune a contat cel mai mult și ce obicei păstrezi de acum. Scrie simplu, ca pentru cineva care n-a fost la curs.", "La <b>Sursa</b>, scrie de unde ai luat ideile, de exemplu: „Suport de curs Competențe digitale, secțiunea 4.9, pg. 58–61” sau „Studii de caz – competențe verzi: «Digitalizarea ajută sau afectează mediul?»”.", "Verifică textul cu <code>F7</code> (ortografia), salvează (<code>Ctrl</code> + <code>S</code>) și trimite fișierul (ghidul <b>G6</b>)."], "ghiduri": ["G6"]}], "in_plus": {"titlu": "Un afiș mic pentru birou", "pasi": ["Pe o pagină nouă (<code>Ctrl</code> + <code>Enter</code>) fă un <b>afiș</b> cu titlul „<b>3 gesturi verzi la calculator</b>”: cele 3 acțiuni care ți s-au părut cele mai ușoare, cu litere mari (cel puțin 20 pt).", "Adaugă o pictogramă (<b>Inserare</b> → <b>Pictograme</b>, de exemplu o frunză) cu <b>text alternativ</b> (ghidul <b>G7</b>).", "Afișul e opțional și nu adaugă puncte în plus, dar e un bun exercițiu pentru E08 și pentru examen."]}, "verifica": ["Tabelul 1 are cifrele tale (sau „nu folosesc”) și locul în care le-ai văzut.", "Ai cel puțin două capturi, în care nu se văd date personale.", "Tabelul 2 are 3 acțiuni făcute de tine, cu cifrele înainte și după.", "Concluzia are 4–6 rânduri, e scrisă pentru colegi și are sursa trecută dedesubt.", "Ai verificat ortografia (<code>F7</code>) și ai trimis fișierul cu subiectul corect."], "rez": {"intro": "Exercițiul e personal: cifrele tale sunt diferite de ale oricui. Mai jos ai <b>o lucrare-model</b>, făcută cu cifre inventate, ca să vezi cum arată o lucrare de nota 10. Lucrarea-model e și în fișierul <code>Model_E26_Amprenta.docx</code>. Notarea se face după <b>baremul oficial</b>: îl găsești la final, cu ce urmărim la fiecare criteriu.", "parti": [{"titlu": "Lucrarea-model: ce am măsurat (cifre inventate)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce am măsurat</th><th scope='col'>Unde am văzut</th><th scope='col'>Cât era</th></tr></thead><tbody><tr><td>Spațiul ocupat de e-mail</td><td>Gmail, jos, sub lista de mesaje</td><td>11,2 GB din 15 GB</td></tr><tr><td>E-mailuri cu atașamente mai mari de 10 MB</td><td>Gmail, căutare has:attachment larger:10M</td><td>38</td></tr><tr><td>Newslettere în ultima săptămână</td><td>Căsuța de e-mail, numărate de mână</td><td>14 expeditori</td></tr><tr><td>Spațiul în OneDrive</td><td>OneDrive pe web, jos în stânga</td><td>4,1 GB din 5 GB</td></tr><tr><td>Spațiul pe telefon</td><td>Setări → Îngrijire dispozitiv → Stocare</td><td>97 GB din 128 GB</td></tr><tr><td>Coșul de reciclare</td><td>Pictograma de pe ecran</td><td>plin (2,3 GB)</td></tr></tbody></table></div>"}, {"titlu": "Lucrarea-model: cele 3 acțiuni", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Ce am făcut</th><th scope='col'>Înainte</th><th scope='col'>După</th><th scope='col'>Cât a scăzut</th></tr></thead><tbody><tr><td>1</td><td>Am șters 31 de e-mailuri mari și am golit Coșul de gunoi din Gmail</td><td>11,2 GB</td><td>8,6 GB</td><td>2,6 GB</td></tr><tr><td>2</td><td>M-am dezabonat de la 9 newslettere pe care nu le citeam</td><td>14 expeditori</td><td>5 expeditori</td><td>9 expeditori</td></tr><tr><td>3</td><td>Am șters de pe telefon clipurile și pozele în dublu din ultimul an</td><td>97 GB</td><td>84 GB</td><td>13 GB</td></tr></tbody></table></div>"}, {"titlu": "Lucrarea-model: concluzia și sursa", "html": "<p>„Nu știam că am 38 de e-mailuri cu atașamente uriașe, majoritatea poze trimise de două ori. În jumătate de oră am eliberat aproape 16 GB, fără să pierd nimic important. Cel mai mult a contat telefonul: clipurile ocupă enorm. De acum, o dată pe lună golesc coșul și mă dezabonez de la ce nu citesc. Vă recomand să încercați: durează mai puțin decât o pauză de cafea.”</p><p><b>Sursa:</b> Suport de curs Competențe digitale, secțiunea 4.9 (competențe verzi, moderație digitală), pg. 58–61.</p>"}, {"titlu": "Cum se notează (baremul oficial) și ce urmărim", "html": "<div class='tw'><table><thead><tr><th scope='col'>Criteriu</th><th scope='col'>Puncte</th><th scope='col'>Ce urmărim la E26</th></tr></thead><tbody><tr><td>Planificarea conținutului</td><td>10</td><td>Cele 3 părți sunt în ordine și complete: măsurători, acțiuni, concluzie.</td></tr><tr><td>Calitatea informației</td><td>15</td><td>Cifrele sunt reale, cu unitatea de măsură (GB, număr) și locul în care au fost văzute; înainte și după se potrivesc.</td></tr><tr><td>Creativitate și design</td><td>10</td><td>Tabelele sunt completate îngrijit, capturile sunt decupate și se văd clar.</td></tr><tr><td>Utilizarea instrumentelor digitale</td><td>10</td><td>Căutarea în e-mail, spațiul de stocare, capturile, golirea coșului, dezabonarea: făcute corect.</td></tr><tr><td>Respectarea drepturilor de autor</td><td>10</td><td>Sursa e trecută; capturile nu arată date personale ale altora.</td></tr><tr><td>Adaptarea la publicul țintă</td><td>15</td><td>Concluzia e scrisă pentru colegi: simplu, concret, cu o recomandare.</td></tr><tr><td>Corectitudine lingvistică</td><td>10</td><td>Diacritice, ortografie, propoziții complete.</td></tr><tr><td>Finalizare și prezentare</td><td>10</td><td>Fișierul are numele corect și a fost trimis cu subiectul cerut.</td></tr><tr><td>Din oficiu</td><td>10</td><td></td></tr></tbody></table></div><div class='cadru'>Greșeli care costă puncte: cifre fără unitate („11” în loc de „11 GB”); acțiuni scrise, dar nefăcute (lipsește cifra „după”); capturi în care se văd subiectele e-mailurilor; concluzie generală („trebuie să protejăm mediul”) în loc de ce ai aflat tu; lipsa sursei.</div>"}]}, "glume": ["Căsuța de e-mail plină de newslettere e ca un vagon de marfă plin cu pliante: îl tragi după tine, dar nu-l descarcă nimeni."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Măsoară-ți amprenta digitală", 20], ["Cerința 2 – Fă 3 acțiuni, măsoară din nou, scrie concluzia", 25], ["Pas în plus – Un afiș mic pentru birou", 45], ["Întrebări și discuție", 15]]}, {"cod": "E27", "titlu": "Actualizări: Windows, telefon și falsa actualizare", "statut": "rec", "nota": null, "ore": [29], "suport": "4.7, pg. 57", "org": "—", "vechi": "T18", "zi": 14, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-21", "sg2": "2026-11-13", "teorie": [{"zi": 8, "ora": 29, "titlu": "Actualizări, înșelătorii, plăți online"}], "gata": true, "fisa": "fise/Fisa_E27_Actualizari.docx", "rez_doc": "fise/Rezolvare_E27_Actualizari.docx", "pornire_var": [], "pornire": "fise/E27_Actualizari_PORNIRE.docx", "pornire_desc": "Tabelul pentru starea calculatorului și a telefonului tău și tabelul cu cele 6 situații.", "model": [], "fisier": "E27_Actualizari_Nume_Prenume.docx", "subiect": "E27 – Actualizări – Nume Prenume", "predare_obl": false, "pe_scurt": "Verifici dacă <b>Windows</b> și <b>telefonul</b> tău sunt la zi și afli ce versiune de Windows ai. Apoi recunoști <b>falsa actualizare</b>: pentru <b>6 situații</b> spui dacă e adevărată sau falsă și ce faci. Miezul: <b>cam 35 de minute</b>.", "recap": ["Actualizările <b>închid breșe</b> de securitate cunoscute. WannaCry (2017) s-a răspândit prin calculatoarele care nu instalaseră o actualizare deja disponibilă.", "Unde le găsești: <b>Windows</b>: Setări → <b>Windows Update</b>. <b>Android</b>: Setări → <b>Actualizare software</b> (numele diferă). <b>iPhone</b>: Configurări → General → <b>Actualizare software</b>. <b>Aplicațiile</b>: din <b>Google Play</b> sau <b>App Store</b>.", "<b>Falsa actualizare</b>: o fereastră apărută pe un site sau un link primit într-un mesaj. Actualizarea adevărată vine <b>doar</b> din Setări sau din magazinul oficial."], "text_dat": "", "cerinte": [{"titlu": "Calculatorul și telefonul tău", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E27_Actualizari_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "<b>Windows Update:</b> apasă <code>Windows</code> + <code>I</code> (se deschid Setările) → <b>Windows Update</b> (pe Windows 10: <b>Actualizare și securitate</b> → <b>Windows Update</b>). Apasă <b>Căutați actualizări</b> (Check for updates). Scrie în tabel ce vezi și fă o captură (ghidurile <b>G1</b> și <b>G2</b>).", "La serviciu poate scrie „<b>Unele setări sunt gestionate de organizația dvs.</b>”. E normal: actualizările le face IT-ul. Scrie asta în tabel.", "<b>Versiunea de Windows:</b> apasă <code>Windows</code> + <code>R</code>, scrie <code>winver</code> și apasă <code>Enter</code>. Fereastra îți arată dacă ai <b>Windows 10</b> sau <b>Windows 11</b> și versiunea (de exemplu 24H2). Scrie-le în tabel.", "<b>Telefonul:</b> Android: <b>Setări</b> → <b>Actualizare software</b>. iPhone: <b>Configurări</b> → <b>General</b> → <b>Actualizare software</b>. Scrie dacă e la zi.", "<b>Aplicațiile:</b> în <b>Google Play</b>: poza ta din dreapta sus → <b>Setări</b> → <b>Preferințe de rețea</b> → <b>Actualizare automată aplicații</b>. Pe iPhone: <b>Configurări</b> → <b>App Store</b> → <b>Actualizări de aplicații</b>. Scrie dacă sunt pornite."], "ghiduri": ["G3", "G1", "G2"]}, {"titlu": "Șase situații: adevărată sau falsă?", "minute": 15, "pasi": ["Pentru fiecare situație întreabă-te: <b>de unde vine</b> actualizarea? Din <b>Setări</b> sau din <b>magazinul oficial</b>? Sau dintr-un <b>site</b> ori un <b>mesaj</b>?", "Scrie <b>adevărată</b> sau <b>falsă</b>, apoi <b>ce faci</b>, într-o propoziție.", "Atenție la situația 6: nu pare o actualizare, dar e aceeași capcană. Niciun site serios nu-ți cere să <b>rulezi comenzi</b> pe calculator.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Windows 10 acasă: ce variante ai", "pasi": ["Dacă la <code>winver</code> ai văzut <b>Windows 10</b>: suportul obișnuit s-a încheiat pe <b>14 octombrie 2025</b>. Ai două variante: treci la <b>Windows 11</b>, dacă aparatul îl acceptă, sau te înscrii în programul de <b>actualizări extinse</b> (ESU), care ține până în <b>octombrie 2027</b>.", "Ca să afli dacă merge Windows 11: <b>Setări</b> → <b>Windows Update</b>. Dacă aparatul e compatibil, acolo apare oferta de trecere la Windows 11.", "Scrie la final, într-o propoziție, ce variantă ai tu (sau „am deja Windows 11”). La serviciu, întrebarea e pentru IT, nu pentru tine."]}, "verifica": ["Tabelul 1 are starea Windows Update, versiunea din winver, starea telefonului și a aplicațiilor (sau „gestionat de organizație”).", "Ai captura cu Windows Update.", "Situațiile 2 și 4 sunt „adevărate”, iar 1, 3, 5 și 6 sunt „false”.", "La fiecare situație falsă ai scris ce faci, nu doar „nu apăs”."], "rez": {"intro": "Partea 1 diferă de la un calculator la altul: mai jos ai ce înseamnă fiecare mesaj. Partea a doua are răspunsuri fixe.", "parti": [{"titlu": "Partea 1 – Ce înseamnă ce vezi", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce vezi în Windows Update</th><th scope='col'>Ce înseamnă</th><th scope='col'>Ce faci</th></tr></thead><tbody><tr><td>„Sunteți la zi” (You're up to date)</td><td>Ai toate actualizările</td><td>Nimic</td></tr><tr><td>„Actualizări disponibile”</td><td>Sunt actualizări care nu s-au instalat încă</td><td>Descărcați și instalați</td></tr><tr><td>„Repornire necesară”</td><td>Actualizarea e descărcată, dar se aplică abia după repornire</td><td>Repornești azi, nu „mâine”</td></tr><tr><td>„Unele setări sunt gestionate de organizația dvs.”</td><td>Calculatorul de serviciu e actualizat de IT</td><td>Nimic; anunți IT-ul dacă vezi erori</td></tr></tbody></table></div><p><b>winver</b> arată, de exemplu: „Windows 11, Versiunea 24H2”. Pe telefon e bine să scrie „Software-ul este actualizat” (sau ceva asemănător), iar actualizările automate ale aplicațiilor să fie pornite.</p>"}, {"titlu": "Partea 2 – Cele 6 situații", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Adevărată / falsă</th><th scope='col'>Ce fac</th></tr></thead><tbody><tr><td>1</td><td>Falsă</td><td>Nu apăs nimic. Închid fila (sau tot browserul, dacă fila nu se închide). Un site nu-ți poate actualiza sistemul.</td></tr><tr><td>2</td><td>Adevărată</td><td>Apăs „Descărcați și instalați” și repornesc când se cere. Vine din Setări.</td></tr><tr><td>3</td><td>Falsă</td><td>Nu apăs pe link și șterg SMS-ul. WhatsApp se actualizează din Google Play sau App Store.</td></tr><tr><td>4</td><td>Adevărată</td><td>Le actualizez din Google Play („Actualizați tot”). E magazinul oficial.</td></tr><tr><td>5</td><td>Falsă</td><td>Nu deschid fișierul și îl șterg. Chrome se actualizează singur, din meniul ⋮ → Ajutor → Despre Google Chrome.</td></tr><tr><td>6</td><td>Falsă (capcana ClickFix)</td><td>Nu apăs tastele și nu lipesc nimic. Închid pagina. Textul copiat ar fi fost o comandă care instalează un program rău-intenționat.</td></tr></tbody></table></div><div class='cadru'>Dacă ai apăsat deja la o actualizare falsă: rulezi o scanare cu antivirusul (Securitate Windows), schimbi parolele importante de pe alt dispozitiv și, la serviciu, anunți imediat IT-ul.</div>"}, {"titlu": "Pas în plus – Windows 10", "html": "<p>Windows 10 nu mai primește actualizările obișnuite din 14 octombrie 2025. Variantele: Windows 11, dacă aparatul îl acceptă, sau programul de actualizări extinse (ESU), care ține până în 12 octombrie 2027. Un calculator fără actualizări de securitate e o țintă ușoară, mai ales pentru operațiunile cu banca.</p>"}]}, "glume": ["O actualizare amânată e ca o ușă de vagon cu încuietoarea stricată: merge, merge, până când nu mai merge."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Calculatorul și telefonul tău", 20], ["Cerința 2 – Șase situații: adevărată sau falsă?", 15], ["Pas în plus – Windows 10 acasă: ce variante ai", 55], ["Întrebări și discuție", 15]]}, {"cod": "E28", "titlu": "Plăți online: verifică un magazin înainte să plătești", "statut": "rec", "nota": null, "ore": [29], "suport": "4.8, pg. 57-58", "org": "—", "vechi": "T18", "zi": 14, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-21", "sg2": "2026-11-13", "teorie": [{"zi": 8, "ora": 29, "titlu": "Actualizări, înșelătorii, plăți online"}], "gata": true, "fisa": "fise/Fisa_E28_Plati_online.docx", "rez_doc": "fise/Rezolvare_E28_Plati_online.docx", "pornire_var": [], "pornire": "fise/E28_Plati_PORNIRE.docx", "pornire_desc": "Tabelul cu cele două magazine inventate, pe 7 semne, și cele 5 situații la plată.", "model": [], "fisier": "E28_Plati_Nume_Prenume.docx", "subiect": "E28 – Plăți – Nume Prenume", "predare_obl": false, "pe_scurt": "Înainte să plătești, verifici magazinul. Compari <b>două magazine inventate</b>, A și B, pe <b>7 semne</b> și hotărăști de la care ai cumpăra. Apoi spui ce faci în <b>5 situații</b> la plată: un cod primit din senin, un „cumpărător” care vrea datele cardului, un cod QR. Miezul: <b>cam 35 de minute</b>.", "recap": ["Trei reguli din suport (pg. 57): <b>platforme de plată cunoscute</b>, <b>recenzii verificate</b> (și în alte surse, nu doar pe site-ul magazinului), <b>cardul nu se salvează</b> pe site-uri nesigure.", "<b>3D Secure</b>: banca îți cere confirmarea (cod prin SMS sau aprobare în aplicație). Oprește un hoț care știe doar datele cardului. <b>Codul e doar al tău</b>: nu-l spui nimănui.", "Un preț „prea bun ca să fie adevărat” e un semnal de alarmă. <b>Lacătul</b> din bara de adrese arată doar că legătura e criptată, <b>nu</b> că magazinul e cinstit."], "text_dat": "", "cerinte": [{"titlu": "Magazinul A sau magazinul B?", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E28_Plati_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Citește tabelul rând cu rând. Pentru fiecare <b>semn</b>, scrie în ultima coloană ce îți spune: care magazin are aici <b>semnul bun</b> și care <b>semnul rău</b>, și de ce, pe scurt.", "Numără semnele rele ale fiecărui magazin. Scrie sub tabel de la ce magazin ai cumpăra și de ce, în 2–3 propoziții."], "ghiduri": ["G3"]}, {"titlu": "Cinci situații la plată", "minute": 15, "pasi": ["Pentru fiecare situație, scrie <b>ce faci</b>, în 1–2 propoziții. Scrie <b>pașii</b>, nu doar „nu fac nimic”.", "Ține minte firul comun: <b>dacă nu tu ai pornit plata</b>, nu confirmi nimic. Iar ca să <b>primești</b> bani, nimeni nu are nevoie de codul sau de data de expirare a cardului tău.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Notificările băncii", "pasi": ["Deschide aplicația băncii tale și caută <b>Notificări</b> (de obicei în <b>Setări</b> sau <b>Profil</b>).", "Verifică dacă primești o notificare la <b>fiecare plată cu cardul</b>. Dacă nu, pornește-o. Așa afli în aceeași secundă dacă plătește altcineva cu cardul tău.", "Nu face nicio captură din aplicația băncii și nu scrie în document nimic despre contul tău. Scrie doar „am verificat” sau „am pornit notificările”."]}, "verifica": ["Toate cele 7 semne au, în ultima coloană, ce îți spun.", "Ai ales magazinul B și ai scris de ce.", "La situațiile 1 și 2 ai scris că nu confirmi și nu dai datele cardului, plus ce faci în loc.", "La situația 5 ai scris că suni banca imediat."], "rez": {"intro": "Ambele părți au răspunsuri fixe. Formulările pot fi altele, dar ideile trebuie să fie aceleași.", "parti": [{"titlu": "Partea 1 – Cele 7 semne", "html": "<div class='tw'><table><thead><tr><th scope='col'>Semnul</th><th scope='col'>Ce îți spune</th></tr></thead><tbody><tr><td>Prețul</td><td>A: semn rău. O reducere de 73% la un telefon nou e „prea bună ca să fie adevărată”. B are un preț normal.</td></tr><tr><td>Datele firmei</td><td>A: semn rău. Un magazin din România trebuie să-și afișeze datele de identificare (nume, CUI, adresă). B le are.</td></tr><tr><td>Adresa site-ului</td><td>A: semn rău. Site nou, cu nume lung și „reduceri” în el. B are o adresă simplă și veche.</td></tr><tr><td>Recenziile</td><td>A: semn rău. Recenziile de pe site le controlează vânzătorul, iar toate de 5 stele, din aceeași zi, sunt suspecte. B are păreri și în alte surse.</td></tr><tr><td>Plata</td><td>A: semn rău. Doar transfer în avans, într-un cont personal: banii nu se mai pot recupera. B are card cu 3D Secure și ramburs.</td></tr><tr><td>Returul</td><td>A: semn rău. La cumpărăturile online ai, de regulă, 14 zile în care te poți răzgândi. B respectă asta.</td></tr><tr><td>Graba</td><td>A: semn rău. Cronometrul e un truc de presiune, ca să nu mai verifici. B nu te grăbește.</td></tr></tbody></table></div><p><b>Concluzia:</b> magazinul <b>A</b> are <b>7 semne rele din 7</b>. Cumperi de la <b>B</b>. Chiar și un singur semn rău, ca plata doar în avans, într-un cont personal, ajunge ca să te oprești.</p>"}, {"titlu": "Partea 2 – Cele 5 situații", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Ce faci</th></tr></thead><tbody><tr><td>1</td><td>Nu introduci codul și nu aprobi nimic. Suni imediat banca, la numărul de pe spatele cardului, și blochezi cardul: cineva are datele lui.</td></tr><tr><td>2</td><td>Nu intri pe link. E înșelătoria clasică cu „curierul”: ca să primești bani, nimeni nu-ți cere datele cardului. Vorbești doar prin site-ul de anunțuri și raportezi contul.</td></tr><tr><td>3</td><td>Nu scanezi. Codurile QR lipite pe stâlpi pot fi puse peste cele reale și duc la site-uri false. Plătești din aplicația oficială a parcării, de la automat sau prin SMS, la numărul scris pe panoul oficial.</td></tr><tr><td>4</td><td>Faci un card separat pentru internet (unele bănci au card virtual, din aplicație), pe care pui doar suma de care ai nevoie. Și pornești notificările la fiecare plată.</td></tr><tr><td>5</td><td>Suni imediat banca și ceri blocarea cardului și contestarea plății. Apoi raportezi la DNSC (1911 sau pnrisc.dnsc.ro) și, pentru că e o înșelătorie, la poliție.</td></tr></tbody></table></div><div class='cadru'>Firul comun: dacă nu tu ai pornit plata, nu confirmi. Iar pentru a primi bani ajung numele și IBAN-ul. Codul, data de expirare și cele 3 cifre de pe spatele cardului nu se dau niciodată.</div>"}, {"titlu": "Pas în plus – notificările", "html": "<p>Aproape toate aplicațiile bancare au notificări la fiecare plată cu cardul. Sunt gratuite în multe bănci și sunt cel mai rapid „sistem de alarmă” pe care îl ai.</p>"}]}, "glume": ["Un telefon de 4.800 lei la 1.299 lei e ca un tren care face Iași – București într-o oră: ar fi frumos, dar nu e adevărat."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Magazinul A sau magazinul B?", 20], ["Cerința 2 – Cinci situații la plată", 15], ["Pas în plus – Notificările băncii", 55], ["Întrebări și discuție", 15]]}, {"cod": "E29", "titlu": "Rezolvarea problemelor: 6 situații de zi cu zi", "statut": "rec", "nota": null, "ore": [31], "suport": "secț. 5, pg. 62-67", "org": "Studii REZOLVAREA PROBLEMELOR", "vechi": "T20", "zi": 15, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-22", "sg2": "2026-11-16", "teorie": [{"zi": 8, "ora": 31, "titlu": "De la idei la LLM: promptul și limitele lui"}], "gata": true, "fisa": "fise/Fisa_E29_Rezolvarea_problemelor.docx", "rez_doc": "fise/Rezolvare_E29_Rezolvarea_problemelor.docx", "pornire_var": [], "pornire": "fise/E29_Probleme_PORNIRE.docx", "pornire_desc": "Tabelul cu cele 6 situații, cu coloane pentru primii pași și pentru momentul în care ceri ajutor.", "model": [], "fisier": "E29_Probleme_Nume_Prenume.docx", "subiect": "E29 – Probleme – Nume Prenume", "predare_obl": false, "pe_scurt": "Ești „omul care se pricepe” din birou. Pentru <b>6 probleme de zi cu zi</b> (internetul, un fișier șters, Word închis fără salvare, proiectorul, microfonul din Zoom, calculatorul lent) scrii <b>primii pași</b> pe care îi încerci și <b>când te oprești și ceri ajutor</b>. Două situații sunt din studiile de caz ale organizatorului. Miezul: <b>cam 35 de minute</b>.", "recap": ["<b>Metoda în 5 pași:</b> 1) descrii exact problema (ce, de când, ce mesaj apare); 2) încerci întâi lucrurile simple (e pornit? e conectat? repornești); 3) schimbi <b>un singur lucru odată</b>; 4) cauți soluția în <b>surse oficiale</b> (ajutorul Microsoft, Google, al producătorului); 5) știi <b>când te oprești</b>.", "Te oprești și ceri ajutor (IT, furnizorul) când problema ține de <b>date importante</b>, de <b>securitate</b> sau când pașii simpli n-au mers. Nu instalezi programe „de reparat” găsite pe internet.", "<b>Folosirea creativă a tehnologiei</b> (suport, pg. 62): combini unelte și găsești soluții, nu doar apeși butoane. Un mesaj bun către IT e și el o soluție: spune ce, când, ce ai încercat și are o captură."], "text_dat": "", "cerinte": [{"titlu": "Situațiile 1, 2 și 3", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E29_Probleme_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Pentru fiecare situație scrie <b>3 pași</b>, în ordine, de la cel mai simplu la cel mai complicat. Gândește-te ce ai face <b>concret</b>: „verific dacă e pornit routerul”, nu „verific internetul”.", "În ultima coloană scrie <b>când te oprești</b> și <b>cui</b> ceri ajutor (IT-ul de la serviciu, furnizorul de internet, un coleg).", "La situația 3 ai nevoie de un drum din Word pe care poate nu-l știi: <b>Fișier</b> (File) → <b>Informații</b> (Info) → <b>Gestionare document</b> (Manage Document) → <b>Recuperare documente nesalvate</b> (Recover Unsaved Documents). Pune-l între pașii tăi."], "ghiduri": ["G3"]}, {"titlu": "Situațiile 4, 5 și 6", "minute": 15, "pasi": ["<b>Situația 4:</b> o scurtătură face aproape tot: <code>Windows</code> + <code>P</code>. Încearc-o acum pe calculatorul tău: se deschide meniul <b>Proiectare</b> (Project), cu variantele <b>Doar ecranul PC-ului</b>, <b>Duplicare</b>, <b>Extindere</b>, <b>Doar al doilea ecran</b>. Apasă <code>Esc</code> ca să-l închizi.", "<b>Situația 5:</b> în Zoom, lângă butonul <b>Dezactivare sunet</b> (Mute) e o săgeată mică <code>^</code>. Din ea alegi <b>microfonul</b> corect și găsești <b>Testare difuzor și microfon</b> (Test Speaker &amp; Microphone).", "<b>Situația 6:</b> apasă <code>Ctrl</code> + <code>Shift</code> + <code>Esc</code>. Se deschide <b>Managerul de activități</b> (Task Manager). Uită-te în coloana <b>CPU</b> ce program folosește cel mai mult. Închide fereastra fără să oprești nimic.", "Completează tabelul pentru situațiile 4, 5 și 6. Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Mesajul către IT", "pasi": ["Pentru situația 6, scrie la finalul documentului mesajul pe care l-ai trimite IT-ului, dacă pașii tăi n-au mers.", "Mesajul răspunde la 4 întrebări: <b>ce</b> se întâmplă, <b>de când</b>, <b>ce ai încercat deja</b> și <b>cum te pot contacta</b>. Adaugă: „Atașez o captură cu Managerul de activități.”", "Fă și captura (ghidul <b>G1</b>) și lipește-o sub mesaj (ghidul <b>G2</b>)."]}, "verifica": ["Toate cele 6 situații au 3 pași concreți, în ordine, de la simplu la complicat.", "Fiecare situație are scris când te oprești și cui ceri ajutor.", "La situația 3 apare <b>Recuperare documente nesalvate</b>, la 4 <code>Windows</code> + <code>P</code>, la 5 alegerea microfonului, la 6 <b>Managerul de activități</b>.", "Nicăieri nu scrie „instalez un program de reparat de pe internet”."], "rez": {"intro": "Ordinea poate să difere puțin, dar pașii trebuie să fie aceiași, de la simplu la complicat, iar la fiecare situație trebuie să știi când te oprești.", "parti": [{"titlu": "Situațiile 1, 2 și 3", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Primii pași, în ordine</th><th scope='col'>Când te oprești</th></tr></thead><tbody><tr><td>1</td><td>1) Verifici că <b>modul Avion</b> e oprit și că ești conectat la <b>rețeaua Wi-Fi corectă</b> (nu la una veche). 2) Te uiți la router: e pornit, are lumini? Repornești routerul și laptopul. 3) Încerci internetul pe telefon, pe același Wi-Fi, și rulezi depanarea de rețea din Windows (în Setări cauți „depanare”).</td><td>Dacă nici telefonul nu are internet pe Wi-Fi după repornire: suni la furnizorul de internet. Raportul urgent îl trimiți între timp de pe telefon, cu datele mobile.</td></tr><tr><td>2</td><td>1) Deschizi <b>Coșul de reciclare</b> (Recycle Bin), cauți fișierul (după nume sau dată) → click dreapta → <b>Restabilire</b> (Restore). 2) Dacă nu e acolo: cauți în <b>OneDrive</b> (sau Google Drive), inclusiv în coșul lor și în <b>Istoricul versiunilor</b>. 3) După ce l-ai găsit, faci o copie de siguranță și pornești salvarea automată în cloud.</td><td>Dacă nu e nici în coș, nici în cloud și e un fișier de serviciu: anunți IT-ul imediat. Uneori există copii de rezervă, dar nu mai scrii nimic pe disc între timp.</td></tr><tr><td>3</td><td>1) Redeschizi Word: deseori apare singur, în stânga, panoul <b>Recuperare documente</b> (Document Recovery). 2) Dacă nu apare: <b>Fișier</b> → <b>Informații</b> → <b>Gestionare document</b> → <b>Recuperare documente nesalvate</b>. 3) După ce l-ai recuperat, îl salvezi imediat cu nume bun și pornești <b>Salvare automată</b> (AutoSave), dacă lucrezi pe OneDrive.</td><td>Dacă nu e în niciun loc: anunți IT-ul (dacă e calculator de serviciu). Lecția: <code>Ctrl</code> + <code>S</code> des, sau AutoSave pornit.</td></tr></tbody></table></div><p><b>Soluțiile din studiile de caz:</b> la 1, laptopul se conectase automat la o rețea veche; după alegerea rețelei corecte și introducerea parolei, internetul a revenit. La 2, fișierul era în Coșul de reciclare și a fost restabilit, iar apoi s-a pornit salvarea automată în cloud.</p>"}, {"titlu": "Situațiile 4, 5 și 6", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Primii pași, în ordine</th><th scope='col'>Când te oprești</th></tr></thead><tbody><tr><td>4</td><td>1) Verifici că proiectorul e pornit și că pe el e aleasă intrarea corectă (HDMI). 2) Verifici cablul, la ambele capete. 3) Apeși <code>Windows</code> + <code>P</code> și alegi <b>Duplicare</b> (vezi același lucru și pe laptop, și pe perete).</td><td>Dacă nici cu alt cablu sau alt laptop nu merge: anunți persoana care se ocupă de sală. Între timp, prezinți de pe laptop sau trimiți PDF-ul participanților.</td></tr><tr><td>5</td><td>1) Verifici că nu ai microfonul oprit în Zoom (butonul <b>Dezactivare sunet</b> / Mute nu e tăiat). 2) Săgeata <code>^</code> de lângă el → alegi microfonul corect (căștile, nu camera). 3) <b>Testare difuzor și microfon</b>; dacă tot nu merge, ieși și intri din nou în ședință.</td><td>Dacă nici după reintrare nu te aud: scrii pe chat-ul ședinței și intri cu telefonul (cu sunetul, ca plan B), apoi anunți IT-ul după ședință.</td></tr><tr><td>6</td><td>1) Salvezi ce ai deschis și repornești calculatorul (<b>Repornire</b>, nu doar închiderea capacului). 2) Deschizi <b>Managerul de activități</b> (<code>Ctrl</code> + <code>Shift</code> + <code>Esc</code>) și vezi ce program folosește mult <b>CPU</b> sau <b>Memorie</b>; închizi programul tău care s-a blocat (<b>Terminare activitate</b>). 3) Verifici <b>Windows Update</b> și rulezi o scanare din <b>Securitate Windows</b>.</td><td>Dacă rămâne lent după repornire, sau un program necunoscut folosește mult CPU: te oprești și anunți IT-ul. Nu închizi procese pe care nu le cunoști și nu instalezi „optimizatoare”.</td></tr></tbody></table></div><div class='cadru'>Firul comun: întâi lucrurile simple (pornit, conectat, repornit), apeși un singur buton odată și te oprești când e vorba de date importante sau de securitate.</div>"}, {"titlu": "Pas în plus – un mesaj bun către IT", "html": "<p>„Bună ziua! De azi-dimineață, de la ora 8:30, calculatorul din biroul casei de bilete (ghișeul 2) merge foarte greu, iar ventilatorul se aude tare. Am repornit calculatorul și am rulat o scanare din Securitate Windows, fără rezultat. În Managerul de activități, un program numit X folosește aproape tot procesorul. Atașez o captură. Mă găsiți la interior 214. Mulțumesc! [Nume Prenume]”</p>"}]}, "glume": ["Prima regulă a depanării: „L-ați oprit și l-ați pornit?”. Funcționează și la calculatoare, și la luni dimineața."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Situațiile 1, 2 și 3", 20], ["Cerința 2 – Situațiile 4, 5 și 6", 15], ["Pas în plus – Mesajul către IT", 55], ["Întrebări și discuție", 15]]}, {"cod": "E30", "titlu": "Asistentul AI: un prompt bun și verificarea răspunsului", "statut": "rec", "nota": null, "ore": [31], "suport": "secț. 5, pg. 62-67", "org": "—", "vechi": "T20", "zi": 15, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-22", "sg2": "2026-11-16", "teorie": [{"zi": 8, "ora": 31, "titlu": "De la idei la LLM: promptul și limitele lui"}], "gata": true, "fisa": "fise/Fisa_E30_Asistentul_AI.docx", "rez_doc": "fise/Rezolvare_E30_Asistentul_AI.docx", "pornire_var": [], "pornire": "fise/E30_AI_PORNIRE.docx", "pornire_desc": "Locul pentru promptul tău și răspunsul asistentului, apoi tabelul cu cele 8 afirmații de verificat.", "model": [], "fisier": "E30_AI_Nume_Prenume.docx", "subiect": "E30 – AI – Nume Prenume", "predare_obl": false, "pe_scurt": "Două lucruri: scrii un <b>prompt bun</b>, cu cele <b>4 ingrediente</b> de la curs (rol, context, sarcină, format), și <b>verifici</b> ce răspunde un asistent AI. Primești un răspuns „scris de AI” cu <b>8 afirmații</b>. Unele sunt greșite, dar sună convingător: le găsești și le corectezi din ce ai învățat la curs. Miezul: <b>cam 35 de minute</b>.", "recap": ["Un <b>LLM</b> (ChatGPT, Copilot, Gemini, Claude…) <b>prezice</b> textul bucată cu bucată, nu îl „caută”. De aceea poate scrie, foarte sigur pe el, lucruri <b>inventate</b> (halucinații): cazul avocaților din New York, 2023, cu hotărâri judecătorești inventate.", "<b>Promptul</b> are 4 ingrediente: <b>rol</b> („ești un…”), <b>context</b> (pentru cine și de ce), <b>sarcină</b> (un singur lucru, clar), <b>format</b> (listă, tabel, 5 rânduri). Apoi ajustezi: prima variantă e doar un început.", "Două reguli care nu se negociază: <b>fără date personale sau confidențiale</b> în prompt și <b>verifici</b> tot ce contează, în surse de încredere."], "text_dat": "", "cerinte": [{"titlu": "Un prompt bun, cu 4 ingrediente", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E30_AI_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Situația: vrei un <b>anunț pentru colegii de birou</b> că, de luni, documentele se trimit doar ca <b>PDF</b>, nu ca poze făcute cu telefonul. Promptul slab e „Scrie un anunț.”. Completează tabelul: <b>rol</b>, <b>context</b>, <b>sarcină</b>, <b>format</b>. Apoi scrie promptul complet, într-un paragraf.", "Deschide un asistent AI: <b>Copilot</b> (copilot.microsoft.com), <b>ChatGPT</b> sau <b>Gemini</b>. Lipește promptul și trimite-l. ⚠ Nu pune în prompt nume reale, numere de telefon sau date de la serviciu.", "Citește răspunsul și cere <b>o singură ajustare</b> (de exemplu: „Scurtează la 5 rânduri și fă tonul mai prietenos.”). Scrie ajustarea în document și lipește răspunsul final.", "Nu ai acces la un asistent AI (nu merge pe calculatorul de serviciu, n-ai cont)? Nu e o problemă: scrie doar promptul și ajustarea. Răspunsul-model e în rezolvare."], "ghiduri": ["G3"]}, {"titlu": "Verifică răspunsul asistentului", "minute": 15, "pasi": ["Citește cele 8 afirmații din partea a doua. Toate sună sigur și convingător. Asta e capcana.", "Pentru fiecare, scrie <b>corect</b> sau <b>greșit</b>. Folosește ce ai învățat la curs: parolele (Ora 23, E19), phishingul (Ora 25), datele personale (Ora 27), plățile și raportarea (Ora 29).", "La fiecare afirmație greșită, scrie <b>varianta corectă</b>, într-o propoziție.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Pune asistentul să se critice singur", "pasi": ["În aceeași conversație cu asistentul, scrie: „<b>Care sunt cele mai slabe trei puncte ale anunțului tău?</b>”.", "Citește răspunsul. Sunt critici bune? Te ajută să-l îmbunătățești? Scrie o propoziție la finalul documentului.", "Un asistent tinde să-ți dea dreptate (lingușirea, de la Ora 31). Întrebarea asta îl obligă să caute și ce nu merge."]}, "verifica": ["Tabelul cu cele 4 ingrediente e completat, iar promptul complet le conține pe toate.", "Promptul nu conține nume reale, telefoane sau date de serviciu.", "Ai cerut o ajustare (sau ai scris-o, dacă n-ai avut acces la AI).", "La partea 2: afirmațiile 3, 7 și 8 sunt corecte; 1, 2, 4, 5 și 6 sunt greșite și au varianta corectă scrisă."], "rez": {"intro": "Partea 1 poate arăta altfel la tine: contează să ai toate cele 4 ingrediente. Partea 2 are răspunsuri fixe.", "parti": [{"titlu": "Partea 1 – Un prompt-model", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ingredientul</th><th scope='col'>Exemplu</th></tr></thead><tbody><tr><td>Rol</td><td>Ești un coleg de birou care scrie clar și prietenos.</td></tr><tr><td>Context</td><td>Anunțul e pentru colegii de la casa de bilete. Mulți trimit documentele ca poze făcute cu telefonul, care se citesc greu și nu se pot căuta.</td></tr><tr><td>Sarcină</td><td>Scrie un anunț scurt că, de luni, documentele se trimit doar ca PDF, și spune pe scurt cum se salvează un PDF din Word.</td></tr><tr><td>Format</td><td>Cel mult 6 rânduri, cu un titlu și 3 marcatori. Fără majuscule și fără ton de reproș.</td></tr></tbody></table></div><p><b>Promptul complet:</b> „Ești un coleg de birou care scrie clar și prietenos. Scrie un anunț pentru colegii de la casa de bilete: de luni, documentele se trimit doar ca PDF, nu ca poze făcute cu telefonul, pentru că pozele se citesc greu și nu se pot căuta. Spune pe scurt cum se salvează un PDF din Word. Cel mult 6 rânduri, cu un titlu și 3 marcatori, fără majuscule și fără ton de reproș.”</p><p><b>Ajustare bună:</b> „Scurtează la 5 rânduri și adaugă la final: «Dacă aveți nevoie de ajutor, sunt la interior 214.»”</p><p><b>Un răspuns posibil:</b> „<b>De luni: documentele, doar ca PDF</b> · Un PDF se citește ușor pe orice calculator și se poate căuta în el. · Din Word: Fișier → Salvare ca → la Tip fișier alegeți PDF. · Pozele făcute cu telefonul nu le mai trimitem. Mulțumesc!”</p>"}, {"titlu": "Partea 2 – Cele 8 afirmații", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Corect / greșit</th><th scope='col'>Varianta corectă</th></tr></thead><tbody><tr><td>1</td><td>Greșit</td><td>Lungimea contează cel mai mult: cel puțin 12–14 caractere, mai bine o parolă-frază de 16+ (E19, Ora 23). 8 caractere „complicate” se sparg repede.</td></tr><tr><td>2</td><td>Greșit</td><td>O parolă pentru fiecare cont. Dacă un site e spart, atacatorii încearcă aceeași parolă peste tot.</td></tr><tr><td>3</td><td>Corect</td><td>—</td></tr><tr><td>4</td><td>Greșit</td><td>Codul din SMS e doar al tău. Nicio bancă nu ți-l cere la telefon: închizi și suni tu la numărul de pe card.</td></tr><tr><td>5</td><td>Greșit</td><td>Phishingul se raportează la DNSC: 1911 sau pnrisc.dnsc.ro. La serviciu, anunți și IT-ul; dacă e vorba de bani, suni și banca.</td></tr><tr><td>6</td><td>Greșit</td><td>Lacătul arată doar că legătura e criptată, nu că site-ul e cinstit. Și un site fals poate avea lacăt.</td></tr><tr><td>7</td><td>Corect</td><td>—</td></tr><tr><td>8</td><td>Corect</td><td>—</td></tr></tbody></table></div><div class='cadru'>Ce ne învață: cinci greșeli din opt, toate spuse sigur pe sine și în română corectă. Un răspuns AI bine scris nu e și un răspuns corect. La ce contează (bani, sănătate, lege, securitate) verifici în surse de încredere.</div>"}, {"titlu": "Pas în plus – autocritica asistentului", "html": "<p>De obicei asistentul găsește critici utile: anunțul e prea lung, nu spune de ce, nu spune pe cine întrebi. Merită folosită întrebarea de fiecare dată când un text contează.</p>"}]}, "glume": ["Asistentul AI e ca Data din Star Trek: face exact ce i-ai cerut, nu ce ai vrut să spui. Iar uneori inventează cu aceeași seriozitate."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Un prompt bun, cu 4 ingrediente", 20], ["Cerința 2 – Verifică răspunsul asistentului", 15], ["Pas în plus – Pune asistentul să se critice singur", 55], ["Întrebări și discuție", 15]]}, {"cod": "E31", "titlu": "Recapitulare Modulele 1-2", "statut": "rec", "nota": null, "ore": [5, 9, 13, 15], "suport": "secț. 1-2", "org": "—", "vechi": "—", "zi": 16, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-23", "sg2": "2026-11-17", "teorie": [{"zi": 2, "ora": 5, "titlu": "Motoare de căutare, operatori, surse"}, {"zi": 3, "ora": 9, "titlu": "Comunicare digitală · e-mail"}, {"zi": 4, "ora": 13, "titlu": "Comunicarea digitală la locul de muncă"}, {"zi": 4, "ora": 15, "titlu": "Egalitate de șanse și nediscriminare"}], "gata": true, "fisa": "fise/Fisa_E31_Recapitulare_Modulele_1_2.docx", "rez_doc": "fise/Rezolvare_E31_Recapitulare_Modulele_1_2.docx", "pornire_var": [], "pornire": "fise/E31_Recapitulare_M1_M2_PORNIRE.docx", "pornire_desc": "Cele 4 stații, cu tabele de completat.", "model": [], "fisier": "E31_Recapitulare_M1_M2_Nume_Prenume.docx", "subiect": "E31 – Recapitulare M1-M2 – Nume Prenume", "predare_obl": false, "pe_scurt": "Recapitulăm <b>Modulele 1 și 2</b> pe un traseu cu <b>4 stații</b>: <b>căutarea</b> (operatori), <b>e-mailul</b> (găsești greșelile și îl rescrii), <b>canalul potrivit</b> (e-mail, mesaj, telefon; Cc sau Bcc) și <b>nediscriminarea</b> (directă sau indirectă). Fiecare stație are răspunsuri clare. Miezul: <b>cam 40 de minute</b>.", "recap": ["<b>Căutarea</b> (Ora 5): <code>\"ghilimele\"</code> = expresia exactă · <code>-cuvânt</code> = scoate un termen · <code>site:exemplu.ro</code> = doar pe acel site · <code>filetype:pdf</code> = doar fișiere PDF. Verifici domeniul sursei și încă 2–3 surse.", "<b>E-mailul și canalul</b> (Orele 9 și 13): subiect clar; adresare, context, ce dorești, până când; încheiere și semnătură. <b>Către</b> = cui îi ceri ceva, <b>Cc</b> = cine trebuie să știe, <b>Bcc</b> = copie ascunsă. Urgent înseamnă telefon sau alertă, nu e-mail.", "<b>Nediscriminarea</b> (Ora 15, OG 137/2000): <b>directă</b> = tratament diferit din cauza unui criteriu (vârstă, sex, etnie…). <b>Indirectă</b> = o regulă aparent neutră care dezavantajează unii oameni. Întrebarea de control: <b>cine lipsește?</b>"], "text_dat": "", "cerinte": [{"titlu": "Stațiile 1 și 2: căutarea și e-mailul", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E31_Recapitulare_M1_M2_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "<b>Stația 1:</b> pentru fiecare nevoie scrie ce tastezi în Google, cu operatorul potrivit. Apoi <b>încearcă</b> fiecare căutare în browser și vezi dacă rezultatele sunt cele dorite.", "<b>Stația 2:</b> citește e-mailul și găsește <b>5 probleme</b> (te uiți la subiect, adresare, conținut, ton, destinatari, atașament, semnătură). Scrie câte una pe rând.", "Rescrie e-mailul corect: <b>Către</b>, <b>Subiect</b> și <b>mesajul</b> (adresare, ce trimiți, ce ceri, până când, încheiere, semnătură)."], "ghiduri": ["G3"]}, {"titlu": "Stațiile 3 și 4: canalul și nediscriminarea", "minute": 20, "pasi": ["<b>Stația 3:</b> pentru fiecare situație alege canalul: <b>e-mail</b>, <b>mesaj</b> (chat) sau <b>telefon</b>. Unde e cazul, scrie cine e la <b>Către</b>, cine la <b>Cc</b> și cine la <b>Bcc</b>.", "<b>Stația 4:</b> pentru fiecare situație scrie <b>directă</b>, <b>indirectă</b> sau <b>nu e discriminare</b>. La „De ce” scrie <b>criteriul</b> (la directă) sau <b>cine e dezavantajat</b> (la indirectă).", "Rescrie anunțul de la situația 1 astfel încât să descrie <b>ce trebuie să știe să facă</b> omul, nu cine e.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Gluma nepotrivită din grup", "pasi": ["Un coleg pune în grupul de lucru o glumă despre „femeile la volan”. Scrie la finalul documentului <b>cei 3 pași</b>, în ordine, de la Ora 15.", "Apoi scrie mesajul <b>în privat</b> pe care i l-ai trimite colegului: calm, scurt, fără să-l faci de râs."]}, "verifica": ["Stația 1: 4 căutări, fiecare cu operatorul potrivit (site:, ghilimele, filetype:, minus).", "Stația 2: 5 probleme și e-mailul rescris, cu subiect clar și semnătură, doar către Ana Rusu.", "Stația 3: telefon la situația 3; Cc la situația 2; Bcc la situația 4.", "Stația 4: 1 și 3 directe, 2 indirectă, 4 nu e discriminare; anunțul rescris fără vârstă și sex."], "rez": {"intro": "Toate stațiile au răspunsuri fixe. La e-mailul rescris și la anunț contează să ai aceleași elemente.", "parti": [{"titlu": "Stația 1 – Căutarea", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Ce scrii</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>1</td><td>phishing site:dnsc.ro</td><td>site: păstrează doar paginile de pe acel domeniu</td></tr><tr><td>2</td><td>\"autentificare în doi pași\"</td><td>Ghilimelele caută exact expresia, cu cuvintele în ordinea asta</td></tr><tr><td>3</td><td>ghid accesibilitate filetype:pdf</td><td>filetype: păstrează doar fișierele de tipul ales</td></tr><tr><td>4</td><td>jaguar animal -mașina</td><td>Minusul scoate rezultatele care conțin cuvântul; „animal” ajută și el</td></tr></tbody></table></div><p>Fără spațiu după <code>site:</code> și <code>filetype:</code>, și fără spațiu între minus și cuvânt.</p>"}, {"titlu": "Stația 2 – E-mailul", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Problema</th></tr></thead><tbody><tr><td>1</td><td>Subiectul „Salut” nu spune nimic: nu se găsește și nu se înțelege despre ce e.</td></tr><tr><td>2</td><td>Adresarea „Bună,” e prea familiară pentru șefă și lipsește numele.</td></tr><tr><td>3</td><td>„Vezi atașat”, dar nu e atașat niciun fișier, iar mesajul nu spune ce anume trimite.</td></tr><tr><td>4</td><td>MAJUSCULELE și „!!!” se citesc ca un țipăt; tonul e de ordin, nu de cerere.</td></tr><tr><td>5</td><td>„Răspuns tuturor” la 25 de persoane, în loc de un singur destinatar; și lipsește semnătura.</td></tr></tbody></table></div><p><b>Varianta corectă:</b></p><div class='cadru'>Către: Ana Rusu · Subiect: Programul de ture pentru decembrie · „Bună ziua, doamna Rusu, vă trimit atașat programul de ture pentru decembrie, așa cum mi-ați cerut. Vă rog să-mi spuneți până joi dacă e nevoie de modificări, ca să-l pot afișa vineri. Mulțumesc! Cu stimă, [Nume Prenume], casa de bilete” · Atașament: Program_ture_decembrie.pdf</div><p>Dacă problemele tale sunt aceleași, doar în altă ordine sau grupate altfel (de exemplu semnătura pe un rând separat), e corect.</p>"}, {"titlu": "Stația 3 – Canalul", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Canalul</th><th scope='col'>Către / Cc / Bcc</th></tr></thead><tbody><tr><td>1</td><td>Mesaj (chat)</td><td>—</td></tr><tr><td>2</td><td>E-mail</td><td>Către: șefa (îi ceri aprobarea) · Cc: contabila (trebuie doar să știe)</td></tr><tr><td>3</td><td>Telefon (sau alerta stației)</td><td>— Urgent înseamnă telefon, nu e-mail</td></tr><tr><td>4</td><td>E-mail</td><td>Bcc: cele 30 de persoane (Către: tu însuți sau adresa organizatorului), ca să nu-și vadă adresele unii altora</td></tr></tbody></table></div>"}, {"titlu": "Stația 4 – Nediscriminarea", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Răspuns</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>1</td><td>Directă</td><td>Criteriile sunt sexul și vârsta: bărbații și persoanele peste 35 de ani sunt excluse din start.</td></tr><tr><td>2</td><td>Indirectă</td><td>Regula pare neutră („toți sunt pe WhatsApp”), dar îi lasă pe dinafară pe cei doi colegi fără telefon inteligent.</td></tr><tr><td>3</td><td>Directă</td><td>Criteriul este vârsta: competența e „ghicită” după vârstă, fără să fie verificată.</td></tr><tr><td>4</td><td>Nu e discriminare</td><td>Informația ajunge la toți, pe două canale. Așa arată, de fapt, incluziunea.</td></tr></tbody></table></div><p><b>Anunțul rescris:</b> „Căutăm casier sau casieră. Cerințe: lucru cu calculatorul și cu casa de marcat, comunicare politicoasă cu călătorii, program în ture.”</p>"}, {"titlu": "Pas în plus – gluma nepotrivită", "html": "<p><b>Cei 3 pași:</b> 1) nu râzi și nu dai „like”; 2) îi spui colegului, calm și în privat; 3) dacă se repetă sau e grav, raportezi superiorului.</p><p><b>Mesajul în privat:</b> „Salut, Mihai! Știu că n-ai vrut să superi pe nimeni, dar gluma din grup a sunat rău pentru colegele noastre. Poți s-o ștergi? Mersi!”</p>"}]}, "glume": ["Bcc e ca vagonul de dormit: toți ajung la destinație, dar nimeni nu vede cine mai e în compartiment."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Stațiile 1 și 2: căutarea și e-mailul", 20], ["Cerința 2 – Stațiile 3 și 4: canalul și nediscriminarea", 20], ["Pas în plus – Gluma nepotrivită din grup", 50], ["Întrebări și discuție", 15]]}, {"cod": "E32", "titlu": "Recapitulare Modulele 3-4: checklist de siguranță", "statut": "rec", "nota": null, "ore": [19, 23, 25, 29], "suport": "secț. 3-4", "org": "—", "vechi": "T21", "zi": 16, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-23", "sg2": "2026-11-17", "teorie": [{"zi": 5, "ora": 19, "titlu": "Conținut digital: Word și PowerPoint"}, {"zi": 6, "ora": 23, "titlu": "Parole, antivirus, firewall, conexiuni sigure"}, {"zi": 7, "ora": 25, "titlu": "Phishing: ce este, cele șapte indicii, apărare"}, {"zi": 8, "ora": 29, "titlu": "Actualizări, înșelătorii, plăți online"}], "gata": true, "fisa": "fise/Fisa_E32_Recapitulare_Modulele_3_4.docx", "rez_doc": "fise/Rezolvare_E32_Recapitulare_Modulele_3_4.docx", "pornire_var": [], "pornire": "fise/E32_Recapitulare_M3_M4_PORNIRE.docx", "pornire_desc": "Checklistul cu 12 întrebări, tabelul pentru cele 3 reparații și cele 8 întrebări rapide.", "model": [], "fisier": "E32_Recapitulare_M3_M4_Nume_Prenume.docx", "subiect": "E32 – Recapitulare M3-M4 – Nume Prenume", "predare_obl": false, "pe_scurt": "Recapitulăm <b>Modulele 3 și 4</b> în două părți. Întâi un <b>checklist de siguranță pentru tine</b>: 12 întrebări despre telefonul, calculatorul și conturile tale. Repari pe loc 3 lucruri. Apoi <b>8 întrebări rapide</b>, cu răspuns scurt, din tot ce am făcut la conținut digital și siguranță. Miezul: <b>cam 40 de minute</b>.", "recap": ["<b>Modulul 3 – Conținut digital:</b> Word cu stiluri, PowerPoint cu o idee pe diapozitiv, <b>PDF</b> pentru ce trimiți, <b>OneDrive</b> partajat cu „persoane specifice” și „vizualizare” când e de ajuns.", "<b>Modulul 4 – Siguranță:</b> parolă lungă și unică + <b>autentificare în doi pași</b>; phishingul se recunoaște după grabă, cereri de date și linkuri ciudate; <b>date personale</b> puține și doar unde trebuie; <b>actualizări</b> din Setări; <b>plăți</b> cu 3D Secure, pe magazine verificate.", "Cele trei reflexe de la final: <b>zece minute</b> (nu răspunzi și nu plătești imediat), <b>alt canal</b> (suni tu, pe numărul tău), întrebarea „<b>cine câștigă dacă fac asta?</b>”."], "text_dat": "", "cerinte": [{"titlu": "Checklistul meu și 3 reparații", "minute": 25, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E32_Recapitulare_M3_M4_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Răspunde la cele 12 afirmații cu <b>DA</b>, <b>NU</b> sau <b>NU ȘTIU</b>. Unde nu știi, <b>verifică</b> pe loc: Setările telefonului, Windows Update, Securitate Windows, aplicația băncii.", "Alege <b>3 afirmații</b> cu NU sau NU ȘTIU și <b>repară-le acum</b>, la curs. Exemple: pornești blocarea automată a telefonului, pornești actualizările automate, scoți accesul unui fișier partajat cu „oricine are linkul”.", "Pentru autentificarea în doi pași, la parole și la bancă ai pașii în exercițiile <b>E19</b>, <b>E20</b> și <b>E28</b>. La OneDrive, în ghidul <b>G9</b>.", "Completează tabelul „Cele 3 lucruri pe care le repar azi”. Dacă ceva nu merge (de exemplu e blocat de IT), scrie de ce."], "ghiduri": ["G3", "G9"]}, {"titlu": "Opt întrebări rapide", "minute": 15, "pasi": ["Răspunde scurt, într-un rând sau două, la cele 8 întrebări din partea a doua.", "Încearcă întâi <b>fără</b> să te uiți în fișele vechi. Abia apoi verifică cu fișele E17–E28 ce nu știai sigur.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "Checklistul pentru cineva drag", "pasi": ["Ia aceleași 12 afirmații și treci-le, cu permisiunea lui, prin telefonul unui părinte, al unui bunic sau al unui prieten mai puțin obișnuit cu tehnologia.", "Repară împreună cu el un singur lucru: de obicei <b>blocarea ecranului</b> sau <b>actualizările automate</b>.", "Notează la finalul documentului doar ce ați reparat, fără alte detalii despre persoană."]}, "verifica": ["Toate cele 12 afirmații au DA / NU / NU ȘTIU și ai numărat DA-urile.", "Ai 3 reparații făcute azi, cu ce ai făcut (sau de ce n-a mers).", "Ai răspuns la toate cele 8 întrebări rapide.", "În document nu e nicio parolă, niciun număr de card și niciun cod."], "rez": {"intro": "Checklistul e personal: mai jos ai cum arată „DA” la fiecare afirmație și unde repari. Întrebările rapide au răspunsuri fixe.", "parti": [{"titlu": "Partea 1 – Cum ajungi la DA", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Unde repari</th></tr></thead><tbody><tr><td>1</td><td>Android: Setări → Ecran de blocare (sau Securitate). iPhone: Configurări → Face ID/Touch ID și cod. Blocare automată: 30 de secunde – 1 minut.</td></tr><tr><td>2</td><td>Obiceiul: <code>Windows</code> + <code>L</code> de fiecare dată când te ridici.</td></tr><tr><td>3</td><td>Setările contului de e-mail → Securitate → Verificare în doi pași (E20).</td></tr><tr><td>4</td><td>Schimbi întâi parola de la e-mail: cine are e-mailul poate reseta toate celelalte parole (E19).</td></tr><tr><td>5</td><td>Setări → Windows Update → Căutați actualizări (E27).</td></tr><tr><td>6</td><td>Google Play / App Store → actualizări automate (E27).</td></tr><tr><td>7</td><td>Securitate Windows → Protecție împotriva virușilor și amenințărilor (E20).</td></tr><tr><td>8</td><td>OneDrive: dosarele Documente și Imagini sincronizate, sau o copie pe stick, o dată pe lună.</td></tr><tr><td>9</td><td>OneDrive → Partajat (Shared) → Gestionare acces la fiecare fișier (E18, G9).</td></tr><tr><td>10</td><td>Aplicația băncii → Setări → Notificări (E28).</td></tr><tr><td>11</td><td>Un cuvânt sau o frază de 2–3 cuvinte fără legătură, stabilită față în față, pe care o cere cel care primește apelul (Ora 29).</td></tr><tr><td>12</td><td>La serviciu: IT-ul. Acasă: DNSC, la 1911 sau pnrisc.dnsc.ro; dacă e vorba de bani, și banca (E22).</td></tr></tbody></table></div><p>Cine are 10–12 DA stă bine. Cu 7–9, are de reparat câteva lucruri ușoare, iar sub 7 merită să reia E19, E20 și E27.</p>"}, {"titlu": "Partea 2 – Cele 8 întrebări", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Răspunsul</th></tr></thead><tbody><tr><td>1</td><td>PDF.</td></tr><tr><td>2</td><td>Persoane specifice (cei 4 colegi) + Poate vizualiza.</td></tr><tr><td>3</td><td>cal-ceai-umbrela-tren: e mult mai lungă (21 de caractere față de 8), iar lungimea contează cel mai mult. Și e mai ușor de ținut minte.</td></tr><tr><td>4</td><td>Nu dai click și ștergi SMS-ul. Dacă aștepți un colet, verifici în aplicația curierului sau pe site-ul lui, tastat de tine.</td></tr><tr><td>5</td><td>Oricare trei dintre: CNP-ul, adresa exactă, datele bancare (cardul), seria și numărul actului (inclusiv o poză cu buletinul), data plecării în vacanță.</td></tr><tr><td>6</td><td>Timpul de utilizare (Screen Time), protejat cu un cod știut doar de părinte.</td></tr><tr><td>7</td><td>Din Setări (Windows Update, Actualizare software) sau din magazinul oficial (Google Play, App Store). Niciodată dintr-o fereastră de pe un site sau dintr-un link primit.</td></tr><tr><td>8</td><td>Confirmarea suplimentară cerută de bancă la o plată online: un cod prin SMS sau aprobarea în aplicația băncii.</td></tr></tbody></table></div>"}]}, "glume": ["Checklistul de siguranță e ca verificarea tehnică a locomotivei: plictisitoare, până în ziua în care te salvează."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Checklistul meu și 3 reparații", 25], ["Cerința 2 – Opt întrebări rapide", 15], ["Pas în plus – Checklistul pentru cineva drag", 50], ["Întrebări și discuție", 15]]}, {"cod": "E33", "titlu": "Simulare proba practică de examen", "statut": "rec", "nota": null, "ore": [5, 9, 15, 29], "suport": "toate", "org": "Model organizator: căutare + e-mail", "vechi": "T19", "zi": 17, "slot": 0, "interval": "17:00–19:00", "sg1": "2026-10-26", "sg2": "2026-11-18", "teorie": [{"zi": 2, "ora": 5, "titlu": "Motoare de căutare, operatori, surse"}, {"zi": 3, "ora": 9, "titlu": "Comunicare digitală · e-mail"}, {"zi": 4, "ora": 15, "titlu": "Egalitate de șanse și nediscriminare"}, {"zi": 8, "ora": 29, "titlu": "Actualizări, înșelătorii, plăți online"}], "gata": true, "fisa": "fise/Fisa_E33_Simulare_proba_practica_de_examen.docx", "rez_doc": "fise/Rezolvare_E33_Simulare_proba_practica_de_examen.docx", "pornire_var": [{"lit": "A", "href": "fise/E33_Simulare_A_PORNIRE.docx"}, {"lit": "B", "href": "fise/E33_Simulare_B_PORNIRE.docx"}, {"lit": "C", "href": "fise/E33_Simulare_C_PORNIRE.docx"}], "pornire": "fise/E33_Simulare_A_PORNIRE.docx", "pornire_desc": "Subiectul de examen pentru varianta ta și foaia de răspuns pentru căutare. Sunt 3 fișiere, câte unul pentru fiecare variantă: îl descarci doar pe al tău.", "model": [], "fisier": "E33_Cautare_Nume_Prenume.docx", "subiect": "E33 – Simulare examen – Varianta X – Nume Prenume", "predare_obl": false, "pe_scurt": "<b>Repetiția generală pentru proba practică de examen.</b> Ca la examen, fiecare cursant primește <b>o variantă cu 2 cerințe</b>: o <b>căutare cu verdict</b> (cuvinte-cheie, primul site, e credibil?) și un <b>e-mail formal</b> cu care trimiți rezultatul. Sunt <b>3 variante (A, B, C)</b>, cu teme și destinatari diferiți. Lucrezi contra cronometru: <b>55 de minute</b> pentru amândouă. Cerințele sunt după modelul organizatorului. Nu se notează, dar merită să-l trimiți: primești părerea formatorului înainte de examen.", "recap": ["<b>Căutarea:</b> 2–4 cuvinte-cheie, nu o propoziție întreagă. Treci peste <b>rezultatele sponsorizate</b> (reclame). Te uiți la <b>domeniu</b> (cine e în spatele site-ului), la <b>autor</b>, la <b>dată</b> și la <b>scop</b> (informează sau vinde?). Confirmi în încă 1–2 surse.", "<b>E-mailul formal:</b> subiect clar; „Bună ziua,” + numele; ce trimiți și de ce; ce ceri; încheiere („Cu stimă,”) și semnătură; atașamentul cu nume bun, verificat înainte de Trimitere.", "La examen, fiecare lucrare se notează după <b>baremul oficial</b>: 8 criterii, 90 de puncte + 10 din oficiu. Îl găsești la „Pas în plus” și, explicat pe această lucrare, în rezolvare."], "text_dat": "<div class='tw'><table><thead><tr><th scope='col'>Varianta</th><th scope='col'>Cerința 1 – cauți despre</th><th scope='col'>Cerința 2 – e-mail către</th><th scope='col'>Cine primește varianta</th></tr></thead><tbody><tr><td>A</td><td>autentificarea în doi pași</td><td>angajatorul tău</td><td>numele de familie începe cu A – F</td></tr><tr><td>B</td><td>managerul de parole</td><td>profesorul tău</td><td>numele de familie începe cu G – O</td></tr><tr><td>C</td><td>copia de siguranță (backupul) a fișierelor</td><td>șefa ta, Ana Rusu (inventată), cu o propunere</td><td>numele de familie începe cu P – Z</td></tr></tbody></table></div><p>Literele cu diacritice se citesc fără ele: Ă și Â ca A, Î ca I, Ș ca S, Ț ca T. Dacă formatorul îți dă altă variantă, lucrezi pe aceea.</p>", "cerinte": [{"titlu": "Căutare eficientă pe internet", "minute": 30, "pasi": ["Află-ți <b>varianta</b> din tabelul „<b>Textul pe care îl folosești</b>” (după prima literă a numelui de familie) și descarcă fișierul de pornire al variantei tale.", "Pornește o numărătoare inversă de <b>55 de minute</b>: pe telefon (aplicația <b>Ceas</b> → <b>Cronometru</b> / Timer) sau în Windows (aplicația <b>Ceas</b> → <b>Temporizator</b>). De acum lucrezi ca la examen.", "Deschide fișierul, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E33_Cautare_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Caută <b>tema variantei tale</b>. Scrie în tabel cuvintele-cheie exacte pe care le-ai tastat.", "Treci peste rezultatele marcate <b>Sponsorizat</b> (Sponsored). Deschide primul rezultat <b>organic</b> și copiază adresa completă din bara de adrese (<code>Ctrl</code> + <code>L</code>, apoi <code>Ctrl</code> + <code>C</code>).", "Completează rândurile: <b>cine</b> e în spatele site-ului (uită-te jos pe pagină sau la „Despre noi”), <b>data</b>, <b>verdictul</b> și <b>cel puțin 3 motive</b>. Găsește o <b>a doua sursă</b> care spune același lucru.", "Scrie, cu cuvintele tale, ce ai aflat (2–3 propoziții). Fă o captură cu pagina de rezultate și lipește-o (ghidurile <b>G1</b> și <b>G2</b>). Salvează."], "ghiduri": ["G3", "G1", "G2"]}, {"titlu": "Trimiterea unui e-mail corect", "minute": 25, "pasi": ["Citește în fișierul variantei tale <b>cui</b> scrii și <b>ce</b> îi ceri (angajatorul, profesorul sau șefa). Formatorul joacă rolul acelei persoane, deci adresa e mereu <code>bogdan@pandapc.ro</code>.", "Deschide e-mailul tău și apasă <b>E-mail nou</b> (New mail / Compose). <b>Către:</b> <code>bogdan@pandapc.ro</code>. <b>Subiect:</b> <code>E33 – Simulare examen – Varianta X – Nume Prenume</code>, cu litera variantei și numele tău.", "<b>Mesajul</b>, în 4–6 rânduri: adresare formală, potrivită destinatarului; ce trimiți; o propoziție cu verdictul tău despre sursă; <b>cererea</b> din varianta ta (părerea, o întrebare sau o propunere); încheiere și semnătură (nume, grupa).", "<b>Atașează</b> fișierul <code>E33_Cautare_Nume_Prenume.docx</code> (ghidul <b>G5</b>) și verifică dacă apare caseta cu numele lui.", "Citește tot e-mailul încă o dată: diacritice, ton, atașament. Apoi <b>Trimitere</b>. Oprește cronometrul și notează cât ai lucrat."], "ghiduri": ["G5", "G6"]}], "in_plus": {"titlu": "Notează-te singur, cu baremul oficial", "pasi": ["Dă-ți puncte cinstite pe cele 8 criterii ale baremului oficial: <b>planificarea</b> (10), <b>calitatea informației</b> (15), <b>creativitate și design</b> (10), <b>instrumentele digitale</b> (10), <b>drepturile de autor</b> (10), <b>publicul țintă</b> (15), <b>corectitudinea lingvistică</b> (10), <b>finalizarea</b> (10), plus 10 din oficiu.", "Scrie la finalul documentului (sau într-un al doilea e-mail) totalul și <b>criteriul la care ai luat cele mai puține puncte</b>. Pe acela îl repeți până la examen.", "Ai terminat mai repede? Fă și o altă variantă, doar Cerința 1, fără să o trimiți."]}, "verifica": ["Ai lucrat pe varianta ta (A, B sau C), iar litera apare în subiectul e-mailului.", "Tabelul de la cerința 1 are toate cele 8 rânduri completate, cu adresa completă a site-ului.", "Verdictul are cel puțin 3 motive și o a doua sursă care confirmă. Ai captura cu pagina de rezultate.", "E-mailul are adresare potrivită destinatarului, conținut, cererea din varianta ta, încheiere, semnătură și atașamentul.", "Ai terminat în 55 de minute (sau știi unde ai pierdut timpul)."], "rez": {"intro": "Fiecare cursant găsește alte site-uri, deci nu există un singur răspuns. Mai jos ai <b>câte o lucrare-model pentru fiecare variantă</b> și <b>cum se notează</b>, criteriu cu criteriu, după baremul oficial. Așa va fi corectată și lucrarea de la examen.", "parti": [{"titlu": "Varianta A – autentificarea în doi pași", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce completezi</th><th scope='col'>Exemplu bun</th></tr></thead><tbody><tr><td>Cuvintele-cheie</td><td>autentificare în doi pași ce este</td></tr><tr><td>Primul site accesat</td><td>Pagina de ajutor Google despre Verificarea în doi pași (support.google.com), sau pagina similară de la Microsoft (support.microsoft.com)</td></tr><tr><td>Cine e în spatele site-ului</td><td>Google, firma care oferă serviciul despre care se vorbește</td></tr><tr><td>Data</td><td>Paginile de ajutor nu au mereu dată; sunt actualizate de firmă</td></tr><tr><td>Credibilă? De ce</td><td>Da: 1) e site-ul oficial al serviciului; 2) explică pașii, nu vinde nimic; 3) aceeași informație apare și la Microsoft și la DNSC</td></tr><tr><td>Ce am aflat</td><td>La conectare, pe lângă parolă, contul îți cere încă o dovadă că ești tu: un cod pe telefon sau o aprobare în aplicație. Chiar dacă cineva îți află parola, nu poate intra fără telefonul tău.</td></tr></tbody></table></div><div class='cadru'>E-mail-model · Către: bogdan@pandapc.ro · Subiect: E33 – Simulare examen – Varianta A – Popescu Maria · „Bună ziua, domnule director, vă trimit atașat rezultatul căutării despre autentificarea în doi pași. Ca primă sursă am ales pagina de ajutor Google, pe care o consider credibilă, pentru că este site-ul oficial al serviciului, iar informația se confirmă și pe site-ul Microsoft. Vă rog să-mi spuneți dacă verdictul meu vi se pare corect. Vă mulțumesc! Cu stimă, Maria Popescu, casa de bilete” · Atașament: E33_Cautare_Popescu_Maria.docx</div>"}, {"titlu": "Varianta B – managerul de parole", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce completezi</th><th scope='col'>Exemplu bun</th></tr></thead><tbody><tr><td>Cuvintele-cheie</td><td>manager de parole ce este</td></tr><tr><td>Primul site accesat</td><td>Pagina de ajutor Google despre Managerul de parole Google (support.google.com), sau pagina Microsoft despre parolele salvate în Edge (support.microsoft.com)</td></tr><tr><td>Cine e în spatele site-ului</td><td>Google (sau Microsoft): firma care oferă unealta</td></tr><tr><td>Data</td><td>Fără dată vizibilă; pagina e actualizată de firmă</td></tr><tr><td>Credibilă? De ce</td><td>Da, pentru „cum funcționează”: 1) e pagina oficială a uneltei; 2) explică pașii; 3) ideea de bază (o parolă diferită la fiecare cont, ținută criptat) se confirmă și în recomandările DNSC. Atenție: site-urile firmelor care vând manageri de parole explică bine, dar vor să-ți vândă produsul.</td></tr><tr><td>Ce am aflat</td><td>Un manager de parole îți păstrează parolele criptat, sub o singură parolă principală, și le completează singur. Așa poți avea o parolă lungă și diferită la fiecare cont, fără să le ții minte pe toate.</td></tr></tbody></table></div><div class='cadru'>E-mail-model · Către: bogdan@pandapc.ro · Subiect: E33 – Simulare examen – Varianta B – Ionescu Andrei · „Bună ziua, domnule profesor, vă trimit atașat tema: căutarea despre managerul de parole. Sursa principală este pagina de ajutor Google, pe care o consider credibilă, pentru că este pagina oficială a uneltei, iar informația se confirmă în recomandările DNSC. Am o întrebare: este sigur să folosesc managerul de parole din browser și pe calculatorul de la serviciu? Vă mulțumesc! Cu stimă, Andrei Ionescu, Grupa 4” · Atașament: E33_Cautare_Ionescu_Andrei.docx</div>"}, {"titlu": "Varianta C – copia de siguranță (backupul)", "html": "<div class='tw'><table><thead><tr><th scope='col'>Ce completezi</th><th scope='col'>Exemplu bun</th></tr></thead><tbody><tr><td>Cuvintele-cheie</td><td>backup fișiere cum fac</td></tr><tr><td>Primul site accesat</td><td>Pagina de ajutor Microsoft despre copia de rezervă a folderelor în OneDrive (support.microsoft.com)</td></tr><tr><td>Cine e în spatele site-ului</td><td>Microsoft, firma care face Windows și OneDrive</td></tr><tr><td>Data</td><td>Fără dată vizibilă; pagina e actualizată de firmă</td></tr><tr><td>Credibilă? De ce</td><td>Da: 1) e site-ul oficial al produsului; 2) explică pașii, cu imagini; 3) sfatul de a avea o copie în alt loc decât calculatorul apare și în recomandările DNSC despre ransomware</td></tr><tr><td>Ce am aflat</td><td>Backupul e o copie a fișierelor importante, ținută în alt loc decât calculatorul: în cloud (OneDrive) sau pe un disc extern. Dacă se strică laptopul sau apare un virus, fișierele nu se pierd. O regulă des întâlnită: 3 copii, pe 2 suporturi diferite, dintre care 1 în alt loc.</td></tr></tbody></table></div><div class='cadru'>E-mail-model · Către: bogdan@pandapc.ro · Subiect: E33 – Simulare examen – Varianta C – Stan Elena · „Bună ziua, doamna Rusu, vă propun ca biroul nostru să facă o copie de siguranță a fișierelor de lucru o dată pe lună, pe OneDrive. Așa nu pierdem documentele dacă se strică un calculator. Am atașat rezultatul căutării, cu sursa: pagina oficială Microsoft, care explică pașii. Vă rog să-mi spuneți dacă putem discuta propunerea la ședința de joi. Vă mulțumesc! Cu stimă, Elena Stan, casa de bilete” · Atașament: E33_Cautare_Stan_Elena.docx</div>"}, {"titlu": "Cum se notează (baremul oficial), pe oricare variantă", "html": "<div class='tw'><table><thead><tr><th scope='col'>Criteriu</th><th scope='col'>Puncte</th><th scope='col'>Ce urmărim la E33</th></tr></thead><tbody><tr><td>Planificarea conținutului</td><td>10</td><td>Tabelul e completat în ordine; e-mailul are adresare, conținut, cerere, încheiere.</td></tr><tr><td>Calitatea informației</td><td>15</td><td>Cuvinte-cheie potrivite, sursă organică și credibilă, motive concrete, a doua sursă, rezumat corect.</td></tr><tr><td>Creativitate și design</td><td>10</td><td>Document îngrijit, captură decupată, e-mail aerisit.</td></tr><tr><td>Utilizarea instrumentelor digitale</td><td>10</td><td>Adresa copiată corect, captura, atașamentul pus și verificat.</td></tr><tr><td>Respectarea drepturilor de autor</td><td>10</td><td>Sursele sunt numite cu adresa; rezumatul e cu cuvintele tale, nu copiat.</td></tr><tr><td>Adaptarea la publicul țintă</td><td>15</td><td>Tonul se potrivește destinatarului: angajator, profesor sau șefă; cererea e clară.</td></tr><tr><td>Corectitudine lingvistică</td><td>10</td><td>Diacritice, ortografie, majuscule la locul lor.</td></tr><tr><td>Finalizare și prezentare</td><td>10</td><td>Subiectul exact (cu litera variantei), fișierul cu nume corect, trimis în timp.</td></tr><tr><td>Din oficiu</td><td>10</td><td></td></tr></tbody></table></div><div class='cadru'>Cele mai dese pierderi de puncte: primul rezultat ales a fost o reclamă; „e credibil pentru că e primul” (nu e un motiv); rezumat copiat de pe site; e-mail fără atașament sau fără semnătură; subiect fără litera variantei; la varianta C, lipsește propunerea concretă (ce, cât de des, unde).</div>"}]}, "glume": ["Trei variante, un singur tren: fiecare urcă în vagonul lui, dar toți ajung la examen."], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Căutare eficientă pe internet", 30], ["Cerința 2 – Trimiterea unui e-mail corect", 25], ["Pas în plus – Notează-te singur, cu baremul oficial", 35], ["Întrebări și discuție", 15]]}, {"cod": "E34", "titlu": "Checklist final + recapitulare pentru grilă", "statut": "rec", "nota": null, "ore": [31], "suport": "toate", "org": "—", "vechi": "T21", "zi": 17, "slot": 1, "interval": "19:00–21:00", "sg1": "2026-10-26", "sg2": "2026-11-18", "teorie": [{"zi": 8, "ora": 31, "titlu": "De la idei la LLM: promptul și limitele lui"}], "gata": true, "fisa": "fise/Fisa_E34_Checklist_final_grila.docx", "rez_doc": "fise/Rezolvare_E34_Checklist_final_grila.docx", "pornire_var": [], "pornire": "fise/E34_Final_PORNIRE.docx", "pornire_desc": "Checklistul cu 15 afirmații pe cele 5 verbe, planul pe 30 de zile și cele 10 întrebări grilă.", "model": [], "fisier": "E34_Final_Nume_Prenume.docx", "subiect": "E34 – Final – Nume Prenume", "predare_obl": false, "pe_scurt": "Ultimul exercițiu. Două părți: un <b>checklist cinstit</b> cu cele <b>15 lucruri</b> pe care le-ai învățat (pot singur / cu ajutor / nu încă), cu un plan scurt, și <b>10 întrebări grilă</b>, exact ca la proba scrisă a examenului: 4 variante, una singură corectă. Miezul: <b>cam 40 de minute</b>.", "recap": ["Cursul în <b>5 verbe</b>: <b>Verificăm</b> (căutare, Excel, fișiere) · <b>Colaborăm</b> (e-mail, comunicare, nediscriminare) · <b>Creăm</b> (Word, PowerPoint, PDF, OneDrive) · <b>Protejăm</b> (parole, phishing, date, actualizări, plăți) · <b>Rezolvăm</b> (probleme, AI).", "<b>Proba scrisă:</b> 20 de întrebări din toată materia, fiecare cu 4 variante și un singur răspuns corect. Nota minimă: <b>5</b>. Te pregătești refăcând testele de la <b>Teorie</b> (fiecare zi are testele cu rezolvări).", "Trei idei de luat cu tine (Ora 31): AI-ul e un stagiar foarte citit, pe care îl instruiești bine și îl verifici. La tot ce contează verifici, îți protejezi datele și rămâi tu în buclă. Curiozitatea e cea mai bună unealtă."], "text_dat": "", "cerinte": [{"titlu": "Checklistul final și planul pe 30 de zile", "minute": 20, "pasi": ["Descarcă <b>fișierul de pornire</b>, apasă <b>Activare editare</b> dacă apare bara galbenă și salvează-l ca <code>E34_Final_Nume_Prenume.docx</code> (ghidul <b>G3</b>).", "Pentru fiecare dintre cele 15 afirmații scrie <b>2</b> (pot singur), <b>1</b> (pot cu ajutor) sau <b>0</b> (nu încă). Fii cinstit: un 1 cinstit te ajută mai mult decât un 2 pus din politețe.", "Adună punctele pe fiecare verb (fiecare verb are 3 afirmații, deci cel mult 6 puncte) și completează al doilea tabel. Încercuiește (sau îngroașă) verbul cu cele mai puține puncte.", "În <b>Planul meu pe 30 de zile</b> alege <b>3 afirmații</b> cu 0 sau 1. Pentru fiecare scrie <b>ce faci concret</b> (de exemplu: „refac E14 și E17”) și <b>când</b>."], "ghiduri": ["G3"]}, {"titlu": "Zece întrebări grilă", "minute": 20, "pasi": ["Răspunde la cele 10 întrebări <b>fără</b> să te uiți în notițe, ca la examen. Ai cam 1 minut pentru fiecare.", "La fiecare întrebare: citești <b>toate cele 4 variante</b> înainte să alegi. Variantele cu „<b>orice</b>”, „<b>mereu</b>”, „<b>niciodată nu greșește</b>” sunt de obicei greșite.", "După ce rezolvarea apare pe site, verifică-te și scrie câte ai avut corecte. Ce n-ai știut, repetă din testele de la <b>Teorie</b>.", "Salvează (<code>Ctrl</code> + <code>S</code>)."], "ghiduri": []}], "in_plus": {"titlu": "O întâlnire cu tine, peste 30 de zile", "pasi": ["Pune în calendar (Outlook sau Google Calendar) un eveniment peste 30 de zile, cu titlul „<b>Planul meu digital: verific ce am făcut</b>”.", "La descriere, lipește cele 3 rânduri din planul tău. Pune o notificare cu o zi înainte.", "Bonus: refă unul dintre testele de la <b>Teorie</b> (pagina Teorie, la ziua ta cea mai slabă) și notează câte răspunsuri corecte ai avut."]}, "verifica": ["Toate cele 15 afirmații au 2, 1 sau 0, iar punctele sunt adunate pe fiecare verb.", "Planul are 3 rânduri, fiecare cu ce faci concret și când.", "Ai răspuns la toate cele 10 întrebări grilă, cu câte o singură literă."], "rez": {"intro": "Checklistul e personal și nu are răspunsuri greșite. Grila are o singură variantă corectă la fiecare întrebare: mai jos ai răspunsul și de ce.", "parti": [{"titlu": "Partea 1 – Cum citești checklistul", "html": "<div class='tw'><table><thead><tr><th scope='col'>Verbul cu puțin punctaj</th><th scope='col'>Ce refaci</th></tr></thead><tbody><tr><td>Verificăm</td><td>E01, E02, E03, E05 și testele Zilelor 2–4</td></tr><tr><td>Colaborăm</td><td>E04, E06, E07, E08, E31</td></tr><tr><td>Creăm</td><td>E14, E15, E16, E17, E18</td></tr><tr><td>Protejăm</td><td>E19–E24, E27, E28, E32</td></tr><tr><td>Rezolvăm</td><td>E29, E30 și testul Zilei 8</td></tr></tbody></table></div><p>Un plan bun are lucruri <b>mici</b> și <b>cu dată</b>: „Joi seara refac E17” e un plan. „Să învăț mai mult Word” nu e.</p>"}, {"titlu": "Partea 2 – Răspunsurile la grilă", "html": "<div class='tw'><table><thead><tr><th scope='col'>Nr.</th><th scope='col'>Răspuns</th><th scope='col'>De ce</th></tr></thead><tbody><tr><td>1</td><td>b</td><td>site: păstrează doar paginile de pe domeniul scris după el (de exemplu site:dnsc.ro).</td></tr><tr><td>2</td><td>c</td><td>SUM adună; AVERAGE face media; =B2+B8 adună doar două celule.</td></tr><tr><td>3</td><td>b</td><td>Cc = cine trebuie să știe. La Către e cel căruia îi ceri ceva.</td></tr><tr><td>4</td><td>b</td><td>Regula pare neutră, dar îi dezavantajează pe cei fără calculator: discriminare indirectă.</td></tr><tr><td>5</td><td>a</td><td>Cuprinsul se face din stiluri și se actualizează cu „Actualizare tabel”.</td></tr><tr><td>6</td><td>c</td><td>Date personale: acces doar pentru cine are nevoie, niciodată „oricine are linkul”.</td></tr><tr><td>7</td><td>d</td><td>E cea mai lungă (20 de caractere), din cuvinte fără legătură, cu cifră și semne.</td></tr><tr><td>8</td><td>c</td><td>Codul din SMS e doar al tău; verifici pe un canal pe care îl alegi tu.</td></tr><tr><td>9</td><td>b</td><td>Actualizările adevărate vin din Setări sau din magazinul oficial.</td></tr><tr><td>10</td><td>b</td><td>AI-ul poate inventa legi și citate. La ce contează, verifici în surse oficiale.</td></tr></tbody></table></div><p><b>8–10 corecte:</b> ești pregătit pentru proba scrisă. <b>5–7:</b> refă testele zilelor la care ai greșit. <b>Sub 5:</b> refă toate testele de la Teorie, câte unul pe zi.</p>"}]}, "glume": ["Ultima stație: toată lumea coboară. Bagajul de competențe digitale îl luați cu voi. 🚉"], "ecran": [["Deschidem fișa și (dacă e cazul) fișierul de pornire", 5], ["Teoria pe scurt: ce ne trebuie azi", 10], ["Cerința 1 – Checklistul final și planul pe 30 de zile", 20], ["Cerința 2 – Zece întrebări grilă", 20], ["Pas în plus – O întâlnire cu tine, peste 30 de zile", 50], ["Întrebări și discuție", 15]]}];
